/* 令和元年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r01.committeeSessions.push(...[{"id":"r01-20190121-6","meetingId":"r01-cm01","date":"2019年1月21日","dateIso":"2019-01-21","committee":"区民委員会","time":"午後 １時００分～午後 ２時３４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件整理しています。","topics":[{"id":"topic-01","title":"「地域でつながる みんなの暮らし展２０１９」の開催","agenda":"「地域でつながる みんなの暮らし展２０１９」の開催","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"今までの議事録を見ますと、チラシが資料としてあったと思うのですけれども、今回ないというのは、その理由を伺いたいと思います。ぜひいただきたいという思いも込めて、よろしいか尋ねました。","respondent":"遠藤協働・国際担当課長","answer":"ちょうど次回の区民委員会の前日にこちらの事業が開催される予定になっていまして、準備でき次第ご用意できるかなと思っているところです。申し訳ございませんでした。","id":"exchange-001"}]},{"id":"topic-02","title":"証明交付窓口のリニューアル","agenda":"証明交付窓口のリニューアル","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"初めに、今後のスケジュール感を伺いたいのですけれども、この後というのは、何か条例改正とか、そういうものが実施までに必要になってくるのか、議会での報告など、どういったプロセスがあるのかをご説明ほしいと求めました。","respondent":"提坂戸籍住民課長","answer":"特にこちらについては、事務の体制を見直すということで、条例改正等は必要ございませんので予定しておりません。２月、３月で委託業者のほうがスタッフの募集をかけまして、４月１日に本番に臨むという形です。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"区では、なぜできないのかと思いますので、ご説明をお願いしたいと思います。やはり来庁された方が問い合わせをするのが多いのはどういった書類が、そういった対応をするのがフロアマネジャーということになるのか伺います。","respondent":"提坂戸籍住民課長","answer":"大体４０人から５０人のスタッフを雇用して、その人数によってお客様を待たせないことができるのではないかということが期待できます。そういうご相談については、ちょっと疑義というか、かなり困難な部分がある場合においては職員がかわって対応させていただこうと考えています。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"このフロアマネジャーの方の専門性というのですか、そういったところも含めて委託になっているということなのか、伺いたいと思います。そういったある程度、待たせないことができるということだと思うのですけれども、その点もなぜ区ではできないのか伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"窓口の案内係ということで、委託の一環ということで行う予定でございまして、実際去年の１２月から一部入れてあります。形式的な申請で対応できる部分については、証明書の作成、委託業者が手数料と引きかえにお客様に証明書をお渡しするという流れになってあります。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"低くなるのか伺いたいと思うのですけれども、人員配置の体制が現在何名で、民間委託した場合に何名になるのか伺いたいと思います。そういった点でも雇用面、処遇の面でどう考えていらっしゃるのか、伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"適切に導入することで中期的、委託を入れさせていただいたほうが２,５００万円程度のコスト減となる見込みと大体試算をしています。そのまま４人の体制でいこうと思っておりまして、人数の指定はできませんけれども、大体１５人前後を見込んでいるところです。","id":"exchange-005"},{"speaker":"のだて委員","kind":"確認","question":"ちょっと確認ですが、業務委託で費用が高くなるのか低くなるのかということで、充実するには高くなるのもやむを得ないというお話もありましたけれども、２,５００万円減の予定だということで、つまりは２,５００万円減の予定だということでいいのですよね。","respondent":"提坂戸籍住民課長","answer":"直営でやるか、一部委託を入れるかということで比較すると、中長期的には２,５００万円ぐらいコストを減らすことができるだろう。現在よりちょっと高くなるのはやむを得ないかなと。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"今示されている１億９,０００万円というのは、この後これを続けていくと、中長期的には２,５００万円減になる。何年かはちょっとよくわからないのですけれども、ということでいいのか尋ねました。","respondent":"提坂戸籍住民課長","answer":"３年後、４年後につきましても、２,０００万円とか３,０００万円増ぐらいにはなってしまうのではないかなとは考えております。トータル的には、コスト増になるのはいたし方ないと考えています。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問","question":"賃金が低くなってワーキングプアを生み出していくということにもつながると思うのですけれども、そういった面でどう考えていらっしゃるのかということもお聞きしたので、その点をお聞きしたいと思います。","respondent":"提坂戸籍住民課長","answer":"ちょっとこちらでは指定はできませんし、比較的この地域とこの品川区周辺から通われる方が多いと見込んでいるのですけれども、そういう意味で。ちょっとワーキングプアということについては、考えてございません。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"どんどん追い詰められていくということになりますので、やはり行政がそういったところをなくしていくという立場に立つことが必要だと思います。やはりこの民間委託ですね、今回のこの本庁舎の窓口委託はやめるべきだということを要望いたしますけれども、いかがか尋ねました。","respondent":"提坂戸籍住民課長","answer":"２３区の状況を見ましても、品川区としてもちょっと遅いくらいなのかなと考えていますので、品川区としてもそれに沿った形で適切に民間委託を進めてまいりたいと考えています。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問・要望","question":"国が進めていて２３区も進んで、品川区は遅いという話でしたけれども、遅いか早いかではないと思うのですよね。職員に相談しなければならないということになると、そういった住民サービスが低下する、この民間委託というのはやめるべきだと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問","question":"丁寧な対応になったということですけれども、これは民間でなくても、きちんと職員の方がされていなければいけないことだと思います。作成、職員は検認などを行うということなのですけれども、それが本当に効率的なのかというところをちょっと具体的に教えてほしいのですけど。","respondent":"提坂戸籍住民課長","answer":"正確性を保つということで、委託業者の方にはしっかりとした受け付けをやっていただいて、証明書を作成してプリントしてもらう。最近では、迅速性と正確性をあわせもって対応するということで、サービスアップにつながっていると考えています。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問","question":"では、効率的で短時間、待たせないような対応になっているということで大丈夫なのですか。〔「偽装請負」と呼ぶ者あり〕あっ、そう、偽装請負の部分とかも、現状どのような報告があるのかを教えてほしいのですけど。","respondent":"提坂戸籍住民課長","answer":"申請内容に疑義があるとか、その辺は全部しっかりと区のほうで対応させていただいているというのが現状で、それは本庁舎でも同じような手順になると思います。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問","question":"それは、偽装請負にはならないで、今までの目黒や大井町ではそのようなトラブルはなかったので、今回本庁舎のほうでもやられるということなのですか。トラブルとかは一切なかったのか尋ねました。","respondent":"提坂戸籍住民課長","answer":"偽装請負の疑義を持つようなトラブルは一切生じてございません。きちんとファイルボックスに入れて、引き継いでもらって、区の職員がその後は責任を持って対応していますので、その辺は問題ございません。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問","question":"その他のトラブル、例えば情報漏えいだったりとか、そういうことはどうなのでしょうか。今のところ、トラブルとして上がってきてはいますか。","respondent":"提坂戸籍住民課長","answer":"２年前に情報漏えいの疑義があるような件があったということは、一昨年ですかね、報告させていただきましたけれども、あれは直営のときだったのですけれども、委託になってからは、そういうのは一切生じてございません。","id":"exchange-014"},{"speaker":"田中委員","kind":"質問","question":"大井町のときも多分私は質問していると思うのですけれども、なぜ報告といった形なのかということと、実施しますという報告ではないですか。それまでに議論する場を持ってほしかったなと思うのですけれども、そのところの考えをちょっと説明を求めました。","respondent":"提坂戸籍住民課長","answer":"業務委託ということは数年以上前から検討してきて、今回、戸籍住民課の本課の窓口業務を委託するということで検討を重ねてまいりまして。議決というものとは違うので、報告事項という形でとどめしています。","id":"exchange-015"},{"speaker":"田中委員","kind":"質問","question":"報告というか、行政として議論を重ねてきたではなく、こういうふうにきちんと安全にできましたという言い方ですかね。報告がされるべきだと思うのですけれども、そこのところの考えを説明するよう求めました。","respondent":"提坂戸籍住民課長","answer":"事故があればすぐに報告しなければいけないと思うのですけれども、スムーズに運営されていますので、報告までには至らなかったという部分があります。","id":"exchange-016"},{"speaker":"田中委員","kind":"意見","question":"プロポーザルのことも聞きたかったのですけれども、プロポーザルで何社が手を挙げて、その結果どういうところが評価され、この富士ゼロックスシステムサービスになったのかということも説明を求めました。","respondent":"提坂戸籍住民課長","answer":"３社が応札というか、業務の手順書というのは、ほかの業者と比べても非常に緻密なものを持っているのですね。これは明らかな差があったので、今回同社を選定させていただいたという次第です。","id":"exchange-017"},{"speaker":"藤原委員","kind":"質問・要望","question":"そういうところから、品川区独自の施策というのでしょうか、２３区に比べて私は品川区のお給料はいいよとなってもいいと思うのです。今の時点で、２３区でトップのお金ですというのならいいけれども、その辺についてお伺いします。","respondent":"提坂戸籍住民課長","answer":"そういうときに、これで従業員の方が十分な賃金を払えるのかという疑義も当然出てきますので、そのようなときはもちろんします。それ以上こちらから指導するというのはなかなか難しい面があるのかなと思います。","id":"exchange-018"},{"speaker":"藤原委員","kind":"質問・要望","question":"いろいろなシステム等があると思うのですけれども、今各課が企画調整課に行って、予算要望とかをするではないですか。業者に指導ではなくて要望、いわゆる出すところからの要望として、私は要望していっていただきたいと思っているので。","respondent":"提坂戸籍住民課長","answer":"４月１日付で正式な契約になるので、平成３２年度以降、その辺の余地はあるかと思います。見積もりをもうちょっと詳細に出してもらうとか、その辺は研究する余地があるかと考えていますので、研究課題とします。","id":"exchange-019"},{"speaker":"藤原委員","kind":"質問・要望","question":"課題にしてください。ぜひ働いてくださっている方のことを思いつつ、施策をしていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"浅野副委員長","kind":"質問","question":"これは費用対効果というのでしょうか、あと利用数というのでしょうか、教えてほしいと求めました。","respondent":"提坂戸籍住民課長","answer":"平成３１年度の４月から申請書作成支援システムを導入する予定ですけれども、とりあえず今回認められたのは１台だけです。１台だけしかないということなので、お越しいただいたお客様の個人差があるのですけれども、１件当たり大体２分から６分ぐらいかかると考えています。","id":"exchange-021"},{"speaker":"浅野副委員長","kind":"質問","question":"その中で、マイナンバーカードなのですけれども、随分時間がたっていますけれども、発行状況というのは、この場で質問させていただいてもよろしいか尋ねました。","respondent":"提坂戸籍住民課長","answer":"１２月末で約６万２,０００枚発行させていただいて、人口比の１６％ぐらいです。","id":"exchange-022"},{"speaker":"浅野副委員長","kind":"質問","question":"出足が非常に厳しかったので、その後どうなっているかなということでお伺いしました。１６％ということで、それともなかなか見つからないのか、そこら辺の考え方を教えてほしいと求めました。","respondent":"提坂戸籍住民課長","answer":"申請書の作成の仕方とかのご説明をさせていただいたり、来月２会場をお借りしまして、新しい試みということで行います。ホームページや広報紙等でも引き続きＰＲに努めてまいります。","id":"exchange-023"},{"speaker":"おくの委員","kind":"質問","question":"そして、議論を聞いていて、現段階でのこの民間委託というのには私自身やはり反対すべきだなというふうに改めて思いました。公務員、委託して事故が起こった場合の対応というのは、どういうふうに考えられているのか尋ねました。","respondent":"提坂戸籍住民課長","answer":"事故があってはならないことなのですけれども、その辺を想定した上で、プロポーザル方式の中でもそういうお話を各業者から聞いてあります。","id":"exchange-024"},{"speaker":"おくの委員","kind":"質問","question":"委託契約そのものにのっとって、普通ですと契約上の損害賠償とか解除とかを考えられますけれども、そちらのほうはいかがか尋ねました。","respondent":"提坂戸籍住民課長","answer":"契約条項の第１５条というところに、不正な行為をしたとき、その契約を解除することができる」ということで明記されています。そこら辺で対応してまいりたいと考えています。","id":"exchange-025"},{"speaker":"おくの委員","kind":"質問","question":"職員が情報漏えいを犯した場合は、どういう対応になるのでしょうか、参考に。","respondent":"提坂戸籍住民課長","answer":"職員が情報漏えいを起こした場合は、処分の対象になることも。","id":"exchange-026"},{"speaker":"おくの委員","kind":"質問","question":"４０年か、１９８０年ごろからはやっていますから、やはりこれは強く反対しておきたいと私の意見としては思っております。そしてプラス、そういう根拠でもっとこの区民委員会、あるいは議会での議論の場が欲しかったという意見を表明して、質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"田中委員","kind":"確認","question":"関連して、情報漏えいのことがあったので、ちょっと確認で。前回の情報漏えいが起きたのは、直営でのことで、直営の中でも実態が何年後かにわかったということではないか尋ねました。","respondent":"提坂戸籍住民課長","answer":"そのときはすぐさま対応させていただいて、ご本人様のマイナンバーカードのパスワードをすぐ変更させていただいたというのと、事故が起こったら即座に対応するということに変わりはございません。","id":"exchange-028"},{"speaker":"田中委員","kind":"意見","question":"前回のときは、情報の共有がきちんと職員間でされていなかったということもあったと思うのです。の対策として今どのようなことがされているのかというのを、多分されていると思うので、しっかりと説明してほしいと求めました。","respondent":"提坂戸籍住民課長","answer":"内部での研修、こちらの要望も踏まえた研修をきっちりやっていただいていると思いますので、その辺は安全だと思います。実際に証明書を出すときに、それは疑義が発生したと判断して、そのときはすぐさま区のほうに引き継いでいただくような体制をとってあります。","id":"exchange-029"},{"speaker":"田中委員","kind":"質問・要望","question":"これは要望でいいので、しっかりと、しっかりと見てというのも変ですよね。そういう意識を常に持っていてほしいというのはちょっとお伝えしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"のだて委員","kind":"質問","question":"最後に１点だけ、先ほどの藤原委員の質問の中で、契約する際に給料が低過ぎる際には、区のほうからも指摘をするというお話でしたけれども、今回の業者は、つまりは低過ぎないと、委託業者の働く方たちの処遇が担保されていると区は考えているということでよろしいのか、伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"応札した他の２業者と比較しましても、金額的にそんなに非常に低かったとか、そういうことはございませんでしたので、適正な価格だと判断させていただきました。","id":"exchange-031"}]},{"id":"topic-03","title":"文化センター等の休室および貸し出しの休止予定","agenda":"文化センター等の休室および貸し出しの休止予定","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"これは既に剥離をしたということでの対応なのか、それともそれを起こさせないための工事ということなのか、その状況を伺いたいと思います。障害児者総合支援施設の開設が延期したことによって、こちらに移ってきたということで貸し出しを休止するということでよいかということを確認したい。","respondent":"立川文化観光課長","answer":"そうしたことで緊急に工事を実施するものです。続きまして、こみゅにてぃぷらざ八潮ですが、こちらは、委員ご案内のとおりの理由です。","id":"exchange-032"},{"speaker":"のだて委員","kind":"質問","question":"機械室の天井剥離は、何か誰かがけがをしたとか、そういった事故というのはなかったのかということを伺いたいと思います。","respondent":"立川文化観光課長","answer":"特に何か落下したとか、そういうことではございませんで、亀裂が生じているという状況です。","id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"まだ落下したわけではないということだったので、今後もそういったところを点検していただいて、そういったことでトラブルが、事故等がないようにしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/776686?Template=document&Id=2830#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":28618,"voices":98}},{"id":"r01-20190121-7","meetingId":"r01-cm01","date":"2019年1月21日","dateIso":"2019-01-21","committee":"厚生委員会","time":"午後 １時００分～午後 １時４７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件整理しています。","topics":[{"id":"topic-01","title":"品川区在宅医療検索（医療機関等名簿デジタル版）の開設","agenda":"品川区在宅医療検索（医療機関等名簿デジタル版）の開設","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"訪問看護ステーションまであるのですが、この８０３件全部に調査をかけたというか、どこまでできるのかという調査をされたのでしょうか。それで、その調査をされたのはどこなのか、区も一緒になったのかというのを説明するよう求めました。","respondent":"大串福祉計画課長","answer":"それから、今申し上げた訪問看護ステーションの１件も含めてですが、未回答ということで２４０件、こちらにまだ回答が来ていないといったところです。その未回答の理由につきまして、今後ともそういったところについては情報公開の呼びかけをしていきたいと考えています。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"介護のほうから入ると、連絡先とか住所だけで、しかもどういう方に対応できているというのも医療の部分で介護のほうから入ると見えないのですよね。やはり医療を介護から見る方もいるので、そうしたほうがいいのではないかと思うのですけれども、そういうのはすぐにできるようなものなのか尋ねました。","respondent":"大串福祉計画課長","answer":"今回在宅医療のサイト、これまでの介護と障害福祉情報といったところに改めて付加をしたような形をとっております。そうした関係で、そこにつきましては、このウエブの管理事業者と調整しながらなるべく最新の情報にかえられるようにしていきたいと考えています。","id":"exchange-002"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"介護の分野にも医療依存度の高い方をこういうふうに受け入れていますよみたいなところまでぜひ拡大していただきたいなという要望です。例えば、また在宅酸素をやっているのだけれども、在宅介護支援センターの方がいろいろと一つ一つ電話してやってもらえますかと確認している状況です。","respondent":"大串福祉計画課長","answer":"薬剤師会等々を含め、あるいはまた訪問看護ステーションを含め、かなり時間をかけて検討させていただいた経過があります。そのためには在宅支援ですとかあるいは民間の居宅関係の事業者さんともいろいろお話をしながら進めていくものだと思っています。","id":"exchange-003"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ぜひよろしくお願いしたいと思います。ちょっとインターネットでというのはよくわからないのですけれども、ぜひそういう方向でご検討いただいて、実現していただけたらなと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"}]},{"id":"topic-02","title":"品川区立障害児者総合支援施設の開設日変更に伴うサービス提供","agenda":"品川区立障害児者総合支援施設の開設日変更に伴うサービス提供","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今日説明していただいたところで若干質問させていただきたいのですけれども、事業名を教えていただきたいのと、あと定員数と登録者数を教えていただけたらと思います。","respondent":"飛田障害者施策推進担当課長","answer":"今八潮で実施している児童学園に関しましては、児童等に係る相談および指導・助言をしています。保健センター等で実施している健診等で気になるお子さんがいたときに、そこと連携しながら相談に乗るという事業をやっているところです。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"定員数が八潮の発達支援事業のほうが２０名で登録は３０名弱と。は定員というのは設定されていないのか尋ねました。","respondent":"飛田障害者施策推進担当課長","answer":"すみません、漏れていました。未就学のところでは１０名、放課後等デイサービスで１０名という設定をしております。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"ここは既存事業からの変更はなくて、業務委託の契約もそのままですね。同じ場所で４月からのこうした委託金だったり事業の拡大というのはされないのか、そういう検討等をされているのか伺いたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"グローの地域拠点相談支援センターでは、地域割り等ありまして引き継ぎ等も今現在行っているところです。現在人数は３人程度というところで、また事業を拡大して、１０月オープンに向けて行っていこうと考えております。","id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"質問","question":"これで事業所なんかはやっていけるのかなというところを伺いたいのと、あと、それで１２人を確保したということでした。４月からこの総合支援施設にはならないわけで、こうした新卒の新たな職員への補償とかはどうなるのかというのを改めて伺いたいです。","respondent":"飛田障害者施策推進担当課長","answer":"その後１０月からは正式に就労継続支援Ｂ型と生活介護両方とも１０名というところで、１０名、合計２０名ということで都に申請をする予定です。研修みたいな感じになるかもわかりませんけれども、１０月に向けてスムーズにつなげるよう進めていければと考えております。","id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"質問","question":"事業所のほうを今質問させていただいたのですけれども、この行き場がどうなるのかなというのを改めて伺いたいです。この３月に卒業する方の中で就労継続支援Ｂ型と生活介護が必要な方の人数というのは把握されているのか伺いたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"今のところ、新施設を希望されている方が約６名から７名ほど、就労継続支援Ｂ型と生活介護合わせていらっしゃいます。そういうところはこの間学校等、また相談のところで利用調査とか希望調査等させていただきまして、今のところ把握している数になります。","id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"１０人でとりあえずは大丈夫だということで１０人ということになったということで確認させていただいていいのかということと、その後もまたほかの。職員体制がどれくらいで始まるのかということについても説明を求めました。","respondent":"飛田障害者施策推進担当課長","answer":"定員は１０名ということで、基本的には卒業生というところで今のところ考えております。今施設運営予定の事業者がその方々の実態を学校に見に行ったり、ではどういう人員体制が必要かというところも今考えているようです。","id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"広さは、両方合わせると１２８m2になるのですか。１０月から始めるとしても、１０月から一気に拡大するとしたら、１０月からの開設ということも含めてお聞かせいただけたらと思います。","respondent":"飛田障害者施策推進担当課長","answer":"今回の代替施設のところは想定では１０名と考えておりまして、その中には車椅子を必要な方が今２名ほど入っていると聞いています。","id":"exchange-011"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"これは１０人というのが生活介護と就労継続支援Ｂ型ということなのですが、この方は生活介護、そういう登録ということになっていくのでしょうか。その仕組みのところも教えていただけたらと思います。","respondent":"飛田障害者施策推進担当課長","answer":"今回、こちらは区の独自の事業ということで実施を考えておりますので、今のところ就労継続支援Ｂ型の利用者は１名ほどいらっしゃいます。","id":"exchange-012"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"区の独自の事業ということで、法内の施設として報酬を請求するというのではなくて、区の独自で、区が全部財政を賄いながら中身としては生活介護と就労継続支援Ｂ型の中身でやると、そういう事業になるということなのか尋ねました。","respondent":"飛田障害者施策推進担当課長","answer":"本当に仮施設の場所というところなので、そういう法内給付とかそういうことはもう受けずにということになります。ただ、そうはいえども１０月につなげるということで、生活介護とまた就労支援Ｂ型相当になる方をこちらのほうで見ますということになります。","id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/312511?Template=document&Id=3528#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":13533,"voices":47}},{"id":"r01-20190121-8","meetingId":"r01-cm01","date":"2019年1月21日","dateIso":"2019-01-21","committee":"建設委員会","time":"午後 １時００分～午後 ４時３８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を63件整理しています。","topics":[{"id":"topic-01","title":"羽田新飛行ルート案に関する国の今後の対応","agenda":"羽田新飛行ルート案に関する国の今後の対応","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"具体的な工事の中身を教えていただきたいのと、なぜ書かないのか、書けない理由が何かあれば教えてください。それと、対象施設の地域の範囲の選定基準なのですが、飛行ルートや、あるいは高度、あるいはＬｄｅｎ等の関係で、どうなっているのか伺います。","respondent":"鈴木都市計画課長","answer":"説明を行って、これも公設民営になりますが、ひがしやつやま保育園というところが施設名です。想定音を設定して、区内の対象施設を全部拾って、まず対象かどうかというところで選定をかけているです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"確認","question":"それと、なっていないところがあるということだと思うのですけれども、それは全施設で想定される音というのが出ているということでよろしいですか。そして、いくつ以下だったら対象にならないとか、そういう基準があるのか尋ねました。","respondent":"鈴木都市計画課長","answer":"設置後の、例えば電気代ですとか、そういったランニングコストにつきましては、補助の対象とはなっていないです。それから、対象となる音の大きさですが、Ｌｄｅｎ５７を超えるというところが助成の対象です。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"幾らでもできると思いますので、マスコミの取材も受け付けるように改善を求めたいのですが、いかがでしょうか。その後のメディアの取材の依頼などはどれぐらい来ているのでしょうか、来ていないのでしょうか、伺います。","respondent":"鈴木都市計画課長","answer":"基本的にはマスコミ対応は、先ほどご説明した趣旨から、３回目まで実施していますが。国では説明会を実施して、事後あるいは事前にブリーフィングという形で取材を受けるという形での対応は、国では行っているです。","id":"exchange-003"},{"speaker":"安藤委員","kind":"提案","question":"私の提案したようなやり方でプライバシーに配慮しながら対応することは可能だと思うのですが、いかがですか、伺います。毎回の質問とその回答というのをホームページで掲載すべきではないかと思うのですけれども、どのようなお考えでしょうか、伺いますとの意見を述べました。","respondent":"鈴木都市計画課長","answer":"マイクを向けて取材している姿も見られましたし、そういった意味では、状況というのは一定把握していただけるのではないかという認識です。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"しっかり区の責任として、ホームページに特設ページでもつくって、タウンミーティングなどでも区できちんとやりとりを残しているではないですか。そういったこともありますので、国にお任せというのではなくて、区として区民にお知らせするという立場で、質問と回答を掲載してほしいと思います。","respondent":"鈴木都市計画課長","answer":"これは、説明をして答える側がしっかりまとめて、地域の方、区民の方にお知らせすると。区が答えを聞き取ったものを一つ一つまとめて、これをやるべき主体は、やはり国なのだという認識です。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回新たに発表された４カ所ですか、そこは大井第一地域センター管内なのに、なぜなのかを伺いたいと思います。十分に質疑ができるような環境を用意することが最低限必要だと思いますので、改善を求めたいと思いますけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"説明会の会場の選定ですが、あるいは地域センターでも検討はあったのかですが、体育館を選定しています。今後もそういう予定ではありますが、できるだけ暖房にも配慮して留意して、今後の残りの地域について実施していきたいです。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"お伺いしたいのですが、やってほしいという意見、伺いたいと思います。現時点で品川区としては、区民の計画への受けとめをどう捉えていらっしゃるのか、お考えを聞かせてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"それから、これまで３回、地域説明会を実施していますが、発言者は１回目が８名、２回目と３回目が１０名。一定理解するが」という発言は２人ほどございましたが、どんどん進めてください」という意見は、質問者の中にはございませんでした。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"実際、進めてほしいという人はいないわけですし、ぜひその区民の声といいますか、実感に即して、区も計画に対峙してほしいと求めました。この一連の説明会で出された意見というのを、品川区としてはどのように今後活かしていくのか、お考えを聞かせてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"教室型説明会も、教室型説明会だからオープンハウス型と違った意見が多く出るということはございませんので、今後も残りの地域説明会がありますが。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、意見を踏まえて考えるということにしていかないと、だめだと思います。ですから、そこは区としてもしっかり認識を持って、動いてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"筒井委員","kind":"質問・要望","question":"確認なのですけれども、具体的にこの法律施行令の第何条なのかということをお知らせいただきたいのと示すよう求めました。","respondent":"鈴木都市計画課長、小林環境課長","answer":"当然ながら建物を所有している、対象となっていますということを区のホームページ等でお知らせする考えは、今のところはございません。改めて区のホームページ等で公開、公表していくという予定は、今のところはございません。 先ほど法改正があったのは第何条かというご質問があったかと思いますが、騒防法第１１条の規定に基づき、対象拡大が告示され、同法施行令の４条の中に、助成の対象となる具体的な施設用途等が示されております。","id":"exchange-010"},{"speaker":"筒井委員","kind":"質問","question":"わかりました。調査結果は、議会に対しても報告なさらないということなのか尋ねました。","respondent":"鈴木都市計画課長","answer":"失礼いたしました。２７施設という形で、民間は何施設ですという形でのご報告は、当然ながら行っていきたいと考えています。","id":"exchange-011"},{"speaker":"筒井委員","kind":"質問","question":"これは貴重なデータとなりますので、具体的に数だけではなくて、この施設がこういう数字だから防音措置が必要だということまでわからないと、我々は今後の話はできないと思うのですけれども、その点はいかがなものなのか尋ねました。","respondent":"鈴木都市計画課長","answer":"どういう形でご報告するかというのは、今後検討していきたいと思いますが、公共施設についてはしっかりご報告させていただきたいと思います。","id":"exchange-012"},{"speaker":"筒井委員","kind":"質問・要望","question":"それがＬｄｅｎ５７以上、決して騒音が発生しないということではなくて、同じようなレベルで騒音が発生するわけではないですか。ですから、区として積極的に国に対して要望してほしいのですけれども、その点はいかがお考えか尋ねました。","respondent":"鈴木都市計画課長","answer":"先ほどご説明したとおり、所有者の方の意向等を確認しながら検討していきたいと思いますが、検討はしていきたいです。結果、住宅が助成対象となる騒音量まで行っていないというところが、国が従前から示している内容だです。","id":"exchange-013"},{"speaker":"筒井委員","kind":"質問・要望","question":"国に対してはしっかりと、一般住宅についての防音措置も求めてほしいのですけれども、それについてはいかがお考えか尋ねました。","respondent":"鈴木都市計画課長","answer":"そうした意味で、なかなかこれを住宅まで広げていくのは難しいということは、担当者レベルでは聞いているところです。そうした意味では、さらに広げるような形での検討というか考えは、国はないというところで聞いているところです。","id":"exchange-014"},{"speaker":"筒井委員","kind":"質問","question":"もっと積極的にそうした事情を説明して、国に対して説得をしてほしいのですけれども、区のご見解はいかがなのか尋ねました。","respondent":"鈴木都市計画課長","answer":"騒音環境の軽減に向けた取り組みは、平成２８年に取り組みが公表されてきたという、区としての理解です。先ほどご説明したように国のほうは、受けとめ方としては、なかなか難しいという受けとめ方です。","id":"exchange-015"},{"speaker":"筒井委員","kind":"質問・要望","question":"区としては国に対して積極的に、一般住宅の防音措置までやっていただけるよう、引き続き粘り強く交渉していっていただきたいと考えております。ですから、区民の方に対してマスコミ報道の可否という確認をとってもいいのではないかと思うのですけれども、いかがお考えか尋ねました。","respondent":"鈴木都市計画課長","answer":"先ほどご説明したように、先ほどもご説明したように、今後もこういう形で個別の説明会は実施していきたいです。","id":"exchange-016"},{"speaker":"筒井委員","kind":"質問","question":"ですから、委縮するかもしれないという推測であって、区民の方は別にマスコミ報道を受けてもいいという方もいらっしゃるかもしれないので、そこは賛否をとるという試みもいいのではないかと思うのですけれども、いかがか尋ねました。","respondent":"中村都市環境部長","answer":"そういった中では、マスコミへの対応につきましても、説明に対する責任のある国のほうが、まず第一に判断をするというところもあります。国の対応に従って、引き続き国に対しては、こういった要望もあるということを伝えてまいりたいと考えております。","id":"exchange-017"},{"speaker":"筒井委員","kind":"質問・要望","question":"フィードバックしているのか、国の態度というのも問われることになると思うので、議事録というのはとっているのでしょうか。その確認をしたいと思います。","respondent":"鈴木都市計画課長","answer":"国でも議事録はしっかりとっているという認識です。","id":"exchange-018"},{"speaker":"筒井委員","kind":"質問・要望","question":"それの公表は、今のところ国は予定はしていないということなのでしょうか。非常に参考になるので、その辺のある程度の公開というのも求めていきたいと思っているのですけれども、区のご見解はいかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"区としてはその都度しっかり、その内容について区民の方に知っていただく上で重要なことということで認識しておりますので、お伝えしています。","id":"exchange-019"},{"speaker":"筒井委員","kind":"質問・要望","question":"あまり意味がある説明会だと思えないので、引き続き区としても、国に対して積極的に要望をお願いしたいと考えております。区としましては、国は丁寧な説明ができているのか、そして住民の理解というのは進んでいると思われますか尋ねました。","respondent":"鈴木都市計画課長","answer":"教室型説明会を開催して、今後１３地区で、より丁寧な説明を国は実施してきていただいているのかなです。今後、教室型説明会を１３地区でやっていただくのとあわせて、さらに理解を深めていただくような説明をしていっていただきたいと考えています。","id":"exchange-020"},{"speaker":"筒井委員","kind":"質問・要望","question":"住民の理解というのを進めるよう、区からも国に対して積極的に、ぜひ進めていっていただきたいと考えております。以上、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"あくつ委員","kind":"質問","question":"１１施設１０棟となっているのですけれども、品川区としてはどのようにお考えなのか、現段階での見解を伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"２ルートでございまして、２ルート案の直下に多く施設が固まっているなというところで、調査を進めていただきたいという認識でいるところです。","id":"exchange-022"},{"speaker":"あくつ委員","kind":"質問","question":"もし先ほどの質疑のやりとりの中でご提示があったのだったら恐縮なのですが、調査結果については大体いつぐらい、議会に提示してくれという話がありましたけれども、２月の末まで調査をして、どれぐらいに結果がこちらに提示をされるという、国からのサジェスチョンはあったのか尋ねました。","respondent":"鈴木都市計画課長","answer":"１月下旬から２月末に調査を行うというところでございまして、これぐらいの概算工事費が発生しますという金額も提示するということは聞いてあります。認識とすると、年度内にはお示しいただけるのかなという認識ではありますが、まだ聞いていないです。","id":"exchange-023"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ずっと要望してきたことですので、議会の要望が、１つ前進をしたなということは一定評価したいと思います。関連なのですけれども、これについては何らかの検討があったのかどうか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"国でしっかり検討するというところは、今後こうしていきましょうというところでの提示は、まだないところです。個別説明会の打ち合わせの中で、そうした検討状況についてはどうですかというやりとりはしていますので、しっかり行っていきたいと考えています。","id":"exchange-024"},{"speaker":"大沢委員","kind":"質問","question":"考え方でいいので私もお話を伺いたいのですが、ルートの発着回数が増えれば、おのずとゴーアラウンドが当然増えてきます。その辺のところはどういうふうに説明というか、行動を、区はしようと考えていらっしゃいますか。","respondent":"鈴木都市計画課長","answer":"個別説明会の実施についてというところで、その下に実施済みの八潮、明日予定ですが品川第二地域センター。昨年末から実施してきていただいている状況でございまして、しっかり国のほうで、今回の飛行ルート案については地区別説明会をやっていただくように。","id":"exchange-025"},{"speaker":"大沢委員","kind":"質問","question":"問題意識は幾らかこちらよりは薄いかと思うのですけれども、飛ぶということに関しては同じで、ゴーアラウンドは結構低く飛ぶのです。ゴーアラウンドはあくまで手動でやるのですか、それとも自動でナビで行くのですか、どっちなのか尋ねました。","respondent":"鈴木都市計画課長","answer":"ゴーアラウンドについてはナビではなくて、パイロットの判断で、当然管制官とのやりとりはありますが、機長の判断でルートを決めていくと。旋回するところを含めて決めていくです。","id":"exchange-026"},{"speaker":"大沢委員","kind":"質問・要望","question":"どこを飛んでくるかわからないわけです。上空を飛びますという地域に関しては、そこのところの意識を持ちながら国に交渉していただきたいと思うのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"新飛行ルート案の説明とゴーアラウンドの説明と、ゴーアラウンドの意味合いも含めて説明していただけるように、しっかり対応していただけるように。","id":"exchange-027"},{"speaker":"大沢委員","kind":"質問・要望","question":"しっかりとそのところは、今、課長がご答弁されたような文言で説明をしていただきたいと考えています。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"松永副委員長","kind":"質問","question":"先ほどの質疑の中でデモンストレーション、いわゆるテスト飛行を行うようなお話を伺ったのですが、いつごろ行われるのでしょうか。行うのであれば、区民の方に対する周知等は行うのかどうか、区の見解をお願いします。","respondent":"鈴木都市計画課長","answer":"今、そうした計器類が正確に作動するかどうかという確認のための検査飛行は、今後行っていく予定があるというところまでは聞いているところです。説明会の中でも質疑として出ておりましたが、国はその検査飛行を行った後で、検討していきたいという回答でございました。","id":"exchange-029"},{"speaker":"松永副委員長","kind":"質問","question":"その中で、先ほどの検査飛行を行う日程とか日時というのは、国からはいつごろだという形のご報告は今後あるのでしょうか。ぜひ区が把握して、周知をするべきだと私は思うのですが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"国は今回の第５フェーズの説明会の中でも、２０１９年の、今年中ぐらいにそれが行われるのではないかという認識です。聞いても、具体的に何月にそれを行いますという回答は、今出てきてございませんが、資料を見ますと、それぐらいのイメージかと思います。","id":"exchange-030"}]},{"id":"topic-02","title":"平成３１年２月都営住宅入居者募集","agenda":"平成３１年２月都営住宅入居者募集","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"都営住宅に関連してお伺いしたいのですけれども、２０１８年いっぱいでの退去というのが居住者の方に通告されていた東大井３丁目の都営元芝アパートというのは、現在、募集も含めて、募集は前からもうやっていないと思うのですけれども、どうなっているか、もし何かありましたら伺いたいと思います。","respondent":"森住宅課長","answer":"今年度当初から退去についての説明会等がありまして、現在は、先月の２６日付で解体工事の契約締結がなされたと聞いております。それが終わりましたら測量等が始まって、東京都で何かしら財産の移管であるとか、次の活用に向けて動きがあると聞いております。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問・要望","question":"これが廃止になってしまったわけですから、今後の住宅政策として見直しをかけていただきたいなと、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"}]},{"id":"topic-03","title":"北品川駅駅前広場都市計画案の説明会開催","agenda":"北品川駅駅前広場都市計画案の説明会開催","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"計画について伺いたいのですが、今回バスが乗り入れるものではないということの確認と、教えてほしいと求めました。図面上では凹凸の凹みたいになっていますが、これは駅高架の下も空間になるということでよろしいのか、その辺をお伺いします。","respondent":"東野まちづくり立体化担当課長","answer":"何点かご質問をいただきましたので、順番に回答いたします。あいている空間となりますので、こちらにつきましては、歩行者が優先的に通るような広場という位置づけになります。","id":"exchange-033"},{"speaker":"安藤委員","kind":"確認","question":"ちょっと確認なのですが、区画街路第７号線というのは、取付道路部分という赤の部分の名前だという理解でよろしいのかなと。第一京浜にまた出るということだと思うのですけれども、東側に行くことはないということなのか、その辺を確認したいと求めました。","respondent":"東野まちづくり立体化担当課長","answer":"赤い取付道路の部分から南下してきまして、少し膨らんでいるところを抜けて、国道に垂直に出るような形の道路を考えてあります。こちらのところを抜けて、東側へ行くことはできます。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問","question":"した上の計画なのか、伺いたいと思います。この支障というのはどのくらいあるのか、伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"現地調査でいきますと、データとしてとっているところでは、１日１２時間当たり、約４０台の乗降があったというデータがあります。実際、交通の支障になるというところが考えられるということになりますので、１つの課題ということで載せしています。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問","question":"新たな立ち退きが発生するような計画になっているのですが、それは問題ではないのですか、伺いたいというのが１つ。結果として、大事なところというのは変わらないのではないかという危惧があるのですが、その辺はいかがか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"こちらにつきましては、駅前広場の計画につきましてご理解をいただくように、区として対応を求めていきたいと思ってあります。前にも委員会の中でも説明させていただきましたが、国道側にベイ型を設けるということは交通安全上支障があるということで、警察とも協議済みです。","id":"exchange-036"},{"speaker":"安藤委員","kind":"質問","question":"そういった修正では、私は地元の方々の思いには応えられないと思いますけれども、それで理解されると考えていらっしゃるのか伺います。だから、しゃくし定規にだめだということは、私はないと思うのですけれども、その辺が理解できないので、なぜだめなのか、もう一度お伺いしたいです。","respondent":"東野まちづくり立体化担当課長","answer":"地元に理解されないのではないかという点ですけれども、こちらは説明会の前に、地元の各団体と意見交換をさせていただいてあります。そういったところから、また別の考えを持って計画をしたものです。","id":"exchange-037"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから区としては、再開発地域にアクセスする道路づくりというのは、断念したということでよろしいのですか。その辺ははっきりとお伺いしたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"再開発協議会というものが立ち上がりまして、今、地域の皆様が検討しています。は国道との接続といったところで、再開発計画とあわせて今後考えていくものだということで、整理をしています。","id":"exchange-038"},{"speaker":"安藤委員","kind":"質問","question":"品川区においては、一度出された案というのが修正されて、もう一回出されたということがあったのかどうか。あれば、もし代表的なところがあれば、こういった例ですというのを説明するよう求めました。","respondent":"東野まちづくり立体化担当課長","answer":"私が知っている限りでは、こういった変遷を経た計画というのはないと認識しています。こちらの変更に当たりましては、地域の皆様のご意見を事業にどれだけ反映させられるかというところで、計画を見直したです。","id":"exchange-039"},{"speaker":"あくつ委員","kind":"質問・要望","question":"意見書等が出てくるのでしょうか、私の要望といたしまして、その形が変わってしまうことに対しての懸念があるということはおっしゃっていました。要望としましては、ぎりぎりまで耳を傾けてほしいと求めましたが、いかがか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"協議会の皆様とも事前に意見交換をさせていただいてあります。それがどういう形で払拭できるかという部分は、区として十分考えて、協議会の皆様とも今後も情報共有を図っていきたいと思ってあります。","id":"exchange-040"},{"speaker":"筒井委員","kind":"質問","question":"通行の取付道路は、車がその取付道路から来て、交通広場にそのまま車が入っていくという感じになるのでしょうか。交通の安全上、どのような配慮というのがなされているのかなと思いまして、その点、お伺いします。","respondent":"東野まちづくり立体化担当課長","answer":"タクシーの乗りおり場というものを設けまして、その先は国道のところへ結びつけて、車が抜けていくという形になります。車と人ができるだけ交錯しないようにということで、この計画を立てておりますので、安全上もきちんと精査されたものと認識しています。","id":"exchange-041"},{"speaker":"筒井委員","kind":"質問","question":"広く整備されていることなので、そこに車が突っ込むようなことがないように、そうした取り組みを行ってほしいと考えております。横町にかからないように、もうちょっと削っていくというような方策というのは、考えられないのか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"垣根をつくったり、それから案内板をつくったりというところで、広場とは区別していきたいと考えています。ここまでが横町だったというところがきちんとわかるように、そういったものも今後、仕立てとして考えていきたいと考えています。","id":"exchange-042"},{"speaker":"筒井委員","kind":"質問","question":"ぜひ地元の方の理解を得て進めていってほしいと考えておりますけれども、途中、技術的にその工事というのは可能なものなのでしょうか。工事の難易度というか、そういったことをお聞きしたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"そうしたところで、東京都と、この用地の買収につきましては、今後調整をとりながら進めていく形になります。建物全体を移転していただくという補償も考えられるところですので、そういったところで今後、東京都とも連携しながら進めていきたいと考えています。","id":"exchange-043"}]},{"id":"topic-04","title":"京浜急行本線連続立体交差事業の用地測量等説明会開催","agenda":"京浜急行本線連続立体交差事業の用地測量等説明会開催","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"進めるべきではないということになるのですけれども、影響がある区民の方の世帯と人数をどう把握していらっしゃるか、伺います。それと、区民の生活再建策などについては、東京都なども一緒に、どのように取り組むつもりなのか伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"それから、生活再建ということなのですけれども、生活再建は区民にとって必要だと区でも考えてあります。こちらにつきましては、東京都の事業ですが、十分な補償といったものをもとに、生活再建に必要な策を東京都と一緒に考えていきたいと思っています。","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問・要望","question":"２５棟ということだと思うのですが、これは品川区内だけの話ということでよろしいのか伺いたい。申請自体も地権者の納得と理解を得てから行うべきだと思っていまして、都にそのように要望してほしいのですが、いかがか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"先ほどの２５棟という部分につきましては、正確には、品川区と港区にまたがって２５棟ということになります。こちらにつきましては、この場では申し上げられないのですけれども、ある程度進んできた段階というところでご理解いただきたいと思います。","id":"exchange-045"},{"speaker":"安藤委員","kind":"意見","question":"ある程度進んだ段階で、ある程度裁量権があるということだと思うのです。進めていくべきだと思いますし、申請自体も、ぜひよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"横山委員","kind":"確認","question":"こちらなのですけれども、具体的にはどのような感じで行われているのでしょうか。今回は品川区や港区と一緒に説明会を行うということで、このサービスが行われているのかというところも確認させていただけたらと思います。","respondent":"東野まちづくり立体化担当課長","answer":"こちらは、港区や品川区と一緒だからということではなく、東京都のスタンスとして、託児保育サービスを行いますというご案内です。この説明会に限らず、ほかのいろいろな住民説明会の中で、東京都がとっている対応です。","id":"exchange-047"}]},{"id":"topic-05","title":"戸越五丁目１９番地区市街地再開発組合の設立認可","agenda":"戸越五丁目１９番地区市街地再開発組合の設立認可","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"事業費が１４６億円ということで、こちらに公共施設管理者負担金というのが入っているのか、それが幾らなのかというのをお伺いします。この区域内には地権者が何人いらっしゃって、組合認可申請に同意した地権者はそのうち何人なのか、伺います。","respondent":"東野まちづくり立体化担当課長","answer":"地権者につきましては、２１人の地権者がいるうちの２０人は合意をとれております。９０％強です。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問","question":"その認可申請の前提となります事業計画の公告・縦覧について伺いたいのですけれども、周知方法はどのようにしていたのか、その期間を伺います。それと、意見書提出があったのか、何件あったのか、どんな内容の意見が提出されたのか、それぞれ伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"１０月１１日から１１月７日までとっておりまして、そこで出された意見書につきましては、３件あったと聞いてあります。うち２件につきましては不採択、１件につきましては無効ということで、東京都から聞いてあります。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういった機会があるのだということをしっかりと、広報の扱い方もそうですし、もう少しＰＲして周知していただきたいと要望いたします。それは、誰にとって相応しく合理的で健全なまちづくりなのか、伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"２９号線について、この戸越地区で継続的に、居住者の確保というものが必要になってくると考えています。戸越公園周辺を発展させていくために、定住者というものを確保していく、そういうものがこの地域には必要だと考えています。","id":"exchange-050"},{"speaker":"安藤委員","kind":"質問・要望","question":"ディベロッパーですとか、そうしたところにとっての合理性なのではないかと思いますが、いかがでしょうか。それと、人口の話ですけれども、２９号線道路というのが二重三重にも地域を壊しているということを、今の答弁を伺って感じざるを得ません。","respondent":"東野まちづくり立体化担当課長","answer":"ただ、再開発ということで、地域の方みずからが計画し、地域のために計画を進めていくという部分では、必ずしもディベロッパーだけでは進みません。こういった再開発を進めるということに当たりまして、かつ業者の力も加えながら、再開発事業が進んでいくものと考えています。","id":"exchange-051"}]},{"id":"topic-06","title":"東京都城南地区河川流域浸水予想区域図","agenda":"東京都城南地区河川流域浸水予想区域図","exchanges":[{"speaker":"横山委員","kind":"質問・要望","question":"どうしたらいいのかというところが、どのように受けとめたらいいのかというところを教えていただきたいというのが、まず１つお願いしたいと思います。そのくらいの感覚なのかなと思うのですが、このあたりも、もしおわかりになりましたら教えていただけたらと思います。","respondent":"古巻防災課長、持田河川下水道課長","answer":"ご自宅の２階、３階にという考え方でしたけれども、またそういったものに合わせた考え方に合わせていく必要があるのかなと考えているところです。なかなか行動には移せない部分があるとは認識しておりますので… おそらくこの１５３mmという雨の考え方の部分なのかなと思ってあります。東京につきましては、関東という地域の中で、１時間１５３mmという数値がございまして、これをもとに東京都がシミュレーションしたといった形です。","id":"exchange-052"},{"speaker":"横山委員","kind":"確認","question":"平成３１年度ということなので、ぜひお願いしたいと考えていますので、機会を捉えて進めていただけたらと思います。今のデータによると、この１５３mmというところは超えることはないということで都が発表されているということで、確認したいと求めました。","respondent":"持田河川下水道課長","answer":"今の１時間当たりの雨量の設定、想定し得る最大雨量は、地域ごとに異なる数値です。こういった形で、基本的にはこれを超えるものというのはなかなか考えにくいぐらいの、こういったものが想定し得る最大だと設定されているところです。","id":"exchange-053"},{"speaker":"安藤委員","kind":"質問・要望","question":"その辺はぜひ、もう少し解像度も含めて、わかりやすいものにしていただきたいと思うのですけれども、いかがでしょうかというのが１つです。今回の想定を１０cm以上にしたのはなぜかということも書いているのですけれども、区として説明してもらえるとありがたいということが２点目です。","respondent":"古巻防災課長、持田河川下水道課長","answer":"１点目について、あまり意味がありませんので、その辺はしっかりわかりやすいデータを使っていきたいと考えております。急遽年内にということで東京都で予定が早まったということもございまして、現状で… このＱ＆Ａにある１０cmだの２０cmだのというところの説明です。今回の説明なのですが、簡単に言うと１０cm以上浸水するところにつきましては、着色をして示していくというふうに方針を変えたと聞いてあります。","id":"exchange-054"},{"speaker":"安藤委員","kind":"質問","question":"２０cmを１０cmにすると、考えられる限りこうした想定をしていくということは、すごく重要だと考えています。この２つの情報の周知方法について、現時点としての区の周知方法についてのお考えを伺いたいと思いますし、あわせてお伺いしたいと思います。","respondent":"古巻防災課長","answer":"発災時はさまざまな手段を用いて、いかに迅速に正確に住民の方に情報を届けるのかということを、さらに進めていきたいと考えております。","id":"exchange-055"}]},{"id":"topic-07","title":"平成３０年度区内一斉防災訓練および各地区総合防災訓練の実施結果等","agenda":"平成３０年度区内一斉防災訓練および各地区総合防災訓練の実施結果等","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"普及させたいという訓練は、こういう中でどの辺だと感じているのか、伺わせてほしいと求めました。そういった、そういうのはすごく参考になるところもあるのではないかと予想しているのですが、その辺はいかがか尋ねました。","respondent":"冨澤災害対策担当課長","answer":"その中での効果的な取り組みというお話ですが、長期間避難所で生活をするということも考えられますので、それの設置の訓練。総合防災訓練につきましては、地域の方々がそれぞれ初期対応ということで、災害に対応する力をつけていただく訓練です。","id":"exchange-056"},{"speaker":"安藤委員","kind":"質問・要望","question":"Ｑ５にも具体的に意見が出ているわけですけれども、反映していくというお考えがあるのか、伺いたいと思います。参加者をより多く増やしていただきたいという自由意見もありますが、区としてどのようなことができるのか、伺いたいと思います。","respondent":"冨澤災害対策担当課長","answer":"参加者同士の交流という回答が２６％あるのですけれども、進め方の中に、交流する時間がなかったというご指摘もございました。一斉訓練の中でできるかどうかは今後検討が必要ですけれども、防災訓練に関心を持っていただいて、参加につなげていきたいと考えております。","id":"exchange-057"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これはぜひ議会で言ってほしいということが幾つかあったので、質問をさせていただきたいのですけれども、うちの町会ではなっていました。そういったところがどうしても一律の訓練になると、この４点、お伺いをいたします。","respondent":"冨澤災害対策担当課長","answer":"続いて３点目ですが、それなりに体制を整えないと、なかなかできない訓練になると考えています。マンションの方々にはご説明して、またマンション訓練、また地域の訓練へご参加をしていただければと考えています。","id":"exchange-058"},{"speaker":"あくつ委員","kind":"提案","question":"よく考えられている、練られていると、今回は本当に思いました。そういったことを、ぜひ区からも提案してほしいと求めましたし、地域からも提案していきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"横山委員","kind":"質問","question":"どういう料理でやっていくと、どうしても訓練には参加できないという方に向けては、そういうステップというのがあってもいいのかなと思います。若い方にも来ていただいたり、今後どのように考えていくといいのかというところ、区のお考えをお聞かせいただけたらと思います。","respondent":"冨澤災害対策担当課長","answer":"これにつきましては、継続して参加をしていただく、また反面、固定化しているという面もあります。若い方、または地域の方々、多くの方々が参加できるような訓練を目指して研究してまいりたいと思います。","id":"exchange-060"},{"speaker":"横山委員","kind":"質問・要望","question":"どの世代の方も、より参加しやすいようにといったところで、ぜひ研究を進めていっていただけたらと思います。何度かご要望というか、そのあたりも検討していっていただきたいと思うのですけれども、ご意見をお聞かせいただけたらと思います。","respondent":"古巻防災課長","answer":"学校の避難所におけます水の活用につきましては、教育委員会の施設管理の担当と、現状の設備等についての意見交換をしています。教育委員会としっかり連携して、よりよい、使いやすい設備ということで進めていきたいと考えております。","id":"exchange-061"},{"speaker":"筒井委員","kind":"意見","question":"これを、どうやってマンション住民の方に、訓練に来ていただけるようなモチベーションを高めていただくかという工夫が必要だと考えています。マンション向けの訓練もやられていくということがありましたけれども、具体的に現時点でどのようなお考えがあるのかというのを説明するよう求めました。","respondent":"冨澤災害対策担当課長","answer":"各マンションに合った材料を見つけていただいて、それぞれのマンションに合う対策を講じていただければと考えています。ご支援をしながら、こういう訓練をやったほうがいいですよという形のヒントを、区から発信していきたいと考えています。","id":"exchange-062"}]},{"id":"topic-08","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"何名か同じ名前がいらっしゃったのか、何名ぐらいの方がニーナというのをつけたのか、お伺いします。どうしても山手線の新駅の話が話題になってしまっていますので、お伺いしているのですけれども、あわせてお伺いします。","respondent":"溝口公園課長","answer":"３番ぐらいになるのですけれども、僅差で５つぐらいの名前が候補に挙がっておりまして、その中から最終的に選んだものです。さまざまな観点で検討した結果、総合的に勘案して、ニーナという名前に決定したと聞いているものです。","id":"exchange-063"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/876969?Template=document&Id=4254#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":61358,"voices":172}},{"id":"r01-20190121-9","meetingId":"r01-cm01","date":"2019年1月21日","dateIso":"2019-01-21","committee":"文教委員会","time":"午後 １時００分～午後 ３時３６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件整理しています。","topics":[{"id":"topic-01","title":"平成３１年度新入学の学校選択希望申請理由調査結果","agenda":"平成３１年度新入学の学校選択希望申請理由調査結果","exchanges":[{"speaker":"石田（し）委員","kind":"質問・要望","question":"アンケート配布枚数が５,１４６枚で、アンケート対象者は１,４４６名というぐあいに、５,１４６枚配る意味というのはあるのですか。実際多分そういったケースというのはなくはないのかと思うので、その辺がどうなって中学校に上がれるのかというのを説明するよう求めました。","respondent":"篠田学務課長","answer":"それから、義務教育学校以外の小・中学校の連携の関係についてですけれども、当然その時点でもう一度希望申請をしていただくと。その中で、一部の連携校については優先順位が設定してあるものもありますけれども、そうでない場合には通常と同じ扱いをしていくという形になります。","id":"exchange-001"},{"speaker":"石田（し）委員","kind":"質問","question":"そんな中で小学校は学区外で入れたけれども中学校になったら急にだめですよと言われるのはなかなか難しいのかなと。子どもたちにとってはなかなか難しいシステムではないのかと思うのですが、その辺の何か考えというのはお持ちか尋ねました。","respondent":"篠田学務課長","answer":"逆に言うとそこで中学校、後期課程に進む段階で外してしまうということでは考えていないということです。あきがあれば入れますという制度になってありますので、制度上はあくまでその配慮まではしていないというものです。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"流れを教えてほしいのと、あと大体傾向的に同じだと思うのですが、これから何を導き出して活かし続けるのか、その辺のことを一点教えていただきたい。こういった意味で、この辺の傾向から何を導き出しているのかというのを説明するよう求めました。","respondent":"篠田学務課長","answer":"例えば学校へとフィードバックできるものがあるのかないのかというところをどうやって活かしていくかといったことで参考にしているものです。それから、全体で４６校のうちの６校ですから、全体の選択数から行けばどうしても低くならざるを得ないと考えているところです。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"よい面とか悪い面とかいろいろあるかと思うのですけれども、どこがどう受け入れられてどう受け入れられてないのかといった点も、その点が１点です。待機者の総数は増えたり減ったりしているのですか、傾向的にどうなのかというのと、また今年の待機者の今後の見込みがつかめていたら説明を求めました。","respondent":"篠田学務課長","answer":"要は、毎年アンケートの結果を受けて学校運営等も考えていますので、一定程度は同じものをやっていく必要があるかなと考えています。これは今申し上げたとおり、全体の区内の就学人口の増加に伴いまして、そういった形が出てきているものと考えているところです。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"これから数カ月の推移を教えてほしいのです。東海中学校とか日野学園は、その予定クラスに大体収まっていくものなのかどうか、ちょっとその辺の推移も説明を求めました。","respondent":"篠田学務課長","answer":"状況によってはいろいろな形で対応ができるやり方、そういった中で対応していただければと思っています。ただ、そういった場合でも必ず学区域のお子さんは受け入れられるように対応していくです。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"意見","question":"学校の対応も、教員を増やさなくてはいけないのかどうかというのもすごく負担があって、毎年このご説明を受けるたびに感じているのです。なくしてほしいなという思いが一つ強くあるのと、教える側の教員にとってどうなのかと、課題が非常に大きいなという感想を持ちますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"渡部委員","kind":"質問・要望","question":"アンケートのほうなのですが、ここはちょっと質問しますけれども、これは複数回答ではないですか。一番下に、「お選びいただいた中で特に気になされた点はどれですか」という項目を設け番号を１個書いてもらうと、そういうことができるかどうか。","respondent":"篠田学務課長","answer":"検討してまいりたいと思います。ただ、積極的にやはり書きづらいということで、項目があればというご提案だと思いますので、こちらについても検討をさせていただければと思います。","id":"exchange-007"},{"speaker":"渡部委員","kind":"質問","question":"もし可能であれば用紙等にナンバーを振っておいて、この地域からこういう声が多いのだとかというのも、せっかくだから拾えるとよいのかなと思います。そうしますと、よりどういう形で選択をされているのかというのを評価したり、質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"その点をちょっと今までのご質問を聞いて余りよくわからなかったので、改めて伺いたいと思います。それから、今までとってきたアンケートと今回のアンケートの違いがあるとしたら、それは何かということを教えてほしいと求めました。","respondent":"篠田学務課長","answer":"自分たちのそれまでの対応などが評価されているものと考えるでしょうし、それぞれ学校現場の運営に活かされていると考えているところです。内容的に大きく入れ替えているところはございませんので、特段大きな変化はないと考えているところです。","id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"どこがどういうふうになっているのかがつかめないまま、正副委員長にもその辺の取り計らいについてはぜひよろしくお願いしたいと思います。そういうのはつかんでおく必要があると思っているのですけれども、改めてその辺の議会に対しての報告の必要性の見解、認識を伺いたいと思います。","respondent":"篠田学務課長","answer":"こちらのアンケートのとり方ですけれども、要は無記名でどなたが回答されたかわからない状態で、実はこれ以上の分析というのはしていないです。実は校長会としてもこのレベルで報告しているというものですので、これ以上の分析についてはされていないといったものです。","id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"随分改善されたのかと思って伺っていたのですけれども、やはりそういう時期はできるだけなくしていかないといけないのではないかと思っているのです。この時期こういう形をとるということについて教育委員会としてはどういうふうに考えておられるのか、それについて伺いたいと思います。","respondent":"篠田学務課長","answer":"中学校に関しては、そちらの結果が最終的に決まります時期を考えますと、やはりどうしても２月末より前にするのは難しいかなと考えているところです。","id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"私立というのはご自分が選択をして入られるわけですから、私はさっきも申し上げたような理由で好ましくないのではないかと思うのです。これは私の意見ですけれども、そのところも受けとめながら、これからの対策、対応に検討、改善を求めていきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"高橋（し）委員","kind":"確認","question":"確認なのですけれども、３５名足す３６名で７１名なのですけれども、そういうふうな形で受け入れるのか。３５名を超えた形も実際行われる、希望するお子さんのためにはそういうことも起こり得るのでしょうかという確認です。","respondent":"篠田学務課長","answer":"クラス数の設定につきましては、あくまで学区内のお子様の数が基本になります。ぎりぎりのところで悩ましいところが出てくるのですけれども、あくまで原則自体は崩さないような形での対応を考えているところです。","id":"exchange-013"},{"speaker":"石田（し）委員","kind":"質問","question":"１点だけ。この集団接種に関して現状品川区教育委員会としてはどのように考えているのか説明を求めました。","respondent":"篠田学務課長","answer":"現状ではインフルエンザの予防はあくまで任意でという形になってありますので、学校におきまして呼びかけをするにとどまっているところです。今のところ学校内での接種を実施するといったことは考えていないところです。","id":"exchange-014"}]},{"id":"topic-02","title":"平成３１年度 品川区立学校教育職員採用候補者選考の結果","agenda":"平成３１年度 品川区立学校教育職員採用候補者選考の結果","exchanges":[{"speaker":"高橋（し）委員","kind":"質問","question":"この内定された方の中に、例えば品川の公立小・中学校で何か非常勤とかそういうかかわりがあった方がいらっしゃるのかということと、あと合格者の小・中学校の免許の内容というか、教えてほしいと求めました。","respondent":"熊谷指導課長","answer":"それから、免許なのですけれども、１名が小学校全科・中学校英語、そしてずっと他県で特別支援をやってこられたエキスパートの方がおります。それからもう１名が小学校全科と中学校の保健体育を持っているということで、そういった状況です。","id":"exchange-015"},{"speaker":"つる委員","kind":"質問","question":"今のご答弁の中で１名、わかる範囲で結構なので、これまでの過去の方も含めてもう一回その辺わかれば。当然それは意識しながら外に行ってまたこういう固有の教員の採用があるかどうかというのもあると思うのですが、この辺の考えがあれば説明を求めました。","respondent":"熊谷指導課長","answer":"そうした品川が非常に好きで愛着を持って一生品川でという方が今後も増えていくように、さまざまかかわっていきたいと思っています。ちなみに、品川の教員に選ばれた方もおりますので、これからもまたそうした品川愛の深い教員が育っていけばいいなと考えているところです。","id":"exchange-016"},{"speaker":"鈴木（博）副委員長","kind":"質問","question":"毎年辞退者が出るみたいなのですけれども、最終的に４名とって１名辞退者が出たら７５％しか採用できなかったことになりますから、毎年辞退者が出るということに関して何か手を打つとか何かいい方法があるとか、あるいはこれはしょうがないことだと思っているのか、この辺はどうお考えなのか尋ねました。","respondent":"熊谷指導課長","answer":"東京都の今年度の小学校の倍率は１.８倍ですので、せっかくこれだけの倍率、私どもとしてはぜひ品川に残ってほしいという思いはあります。次年度以降もできるだけ辞退者を出さないように対応していきたいと考えてはおります。","id":"exchange-017"}]},{"id":"topic-03","title":"南ゆたか児童センターの休館","agenda":"南ゆたか児童センターの休館","exchanges":[{"speaker":"南委員","kind":"質問","question":"２年間のかなり長期と認識するのですけれども、改築の中身について１つ伺いたいです。どのくらい、どういうふうな状況でこれからの考え方があるのか、ちょっとそれを説明するよう求めました。","respondent":"高山子ども育成課長","answer":"２点ご質問をいただきまして、１点目の新しい施設の概要という点で申しますと、そうした専用の相談室などもしつらえてまいりたいと考えております。","id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/211588?Template=document&Id=4962#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":24859,"voices":65}},{"id":"r01-20190121-5","meetingId":"r01-cm01","date":"2019年1月21日","dateIso":"2019-01-21","committee":"総務委員会","time":"午後 １時００分～午後 ３時１８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を54件整理しています。","topics":[{"id":"topic-01","title":"「」を聴取いたします。 まず、(1)品川区長期基本計画の策定状況","agenda":"「」を聴取いたします。 まず、(1)品川区長期基本計画の策定状況","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"この点について、区はどう考えているのか伺いたいと思います。主な意見はどういう基準で区は資料に出しているのか、申しわけないのですけれども思えないので、この点についても伺いたいと思います。","respondent":"大野計画担当課長","answer":"それから２点目の主な意見についてですけれども、区内関係団体からいただいた主な意見というような形でまとめさせていただいているところです。全てのご意見等々につきましては、現在、要旨を作成中ですので、そちらのほうには記載をする予定です。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"議事録をなぜ要旨にしなければいけないのか、全文公開にすべきだと、どう考えているのかについて伺いたいと思います。品川区はこういう取り扱い要領で適していると思うのか、その点についても伺いたいと思います。","respondent":"大野計画担当課長","answer":"２点のご質問で、まず要旨でよいのかですけれども、一部簡略化した要旨という形で区としてはやっていきたいと考えているところです。確かに時代の流れ等々の中で、この部分につきましては、この形のまま進めさせていただければというふうに考えているところです。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"経過を残すためにも、全文の議事録を原則とすべきだと思いますけれども、その理由について伺いたいと思います。この考えを今後とも続けていくというのであれば、ぜひそこは再検討してほしいと求めましたが、改めていかがか尋ねました。","respondent":"大野計画担当課長","answer":"言葉の語尾ですとか、そういった不要な部分についてとっていくような形ですので、基本的には要旨という形で進めさせていただきたいと考えております。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"策定委員会で確認されたことは私も知っていますけれども、例えば、これについてはぜひ見直していただきたいと要望しておきたいと思います。最後に１点確認ですけれども、委員会の冒頭で確認せずに初めから傍聴できるのか、その点を確認したいと求めました。","respondent":"大野計画担当課長","answer":"第１回策定委員会で傍聴に関する規定を確認いただきましたので、第２回目以降は、２時の開催時刻から入っていただけます。入退室については、基本的に、議事を妨げない範囲で途中の入退室も構わないです。","id":"exchange-004"},{"speaker":"いながわ委員","kind":"質問・要望","question":"これは確認なのですけれども、おのずと高齢者も増えてくるわけですから、そこの視点も必要ではないのかと。例えば、議員がいろいろな場所でいろいろ要望をしていて、それはどういう形でここに反映されていくのかということをお聞かせいただきたい。","respondent":"大野計画担当課長","answer":"あるいは障害者としての意見ですとか、高齢者の視点が抜けてしまっているということはなく進められているのかなというふうに考えているところです。","id":"exchange-005"},{"speaker":"いながわ委員","kind":"質問・要望","question":"６５歳以上の大学の教授なのか、協働というのでしょうか、なぜですかということです。高齢化ですから、それでも私たち議員なり何なりが間接的に入っているわけですから、どうお考えかということを示すよう求めました。","respondent":"大野計画担当課長","answer":"団体のアンケートという形で、高齢者クラブ、それから障害者団体等々からアンケートという形でご意見は伺っているところです。そういったところの意見をしっかりと踏まえて、たたき台を作成し、策定委員会を進めていきたいというふうには考えてあります。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"この公募の区民の方たち５名が、どれくらいの応募の中で、どういうふうに選考されたのか。固有名詞だと特定されてしまいまずいと思うのですけれども、この５名がどういった方であるかも教えてほしいと求めました。","respondent":"大野計画担当課長","answer":"皆様に、「私が考える将来の品川区」というような内容の作文を書いていただきまして、それについて選考したです。一定程度、やはり年齢ですとか、居住地域ですとか、そういった部分も踏まえた上で５名を選考させていただいたものです。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問","question":"結果的に、どういう方が選ばれているか説明を求めました。","respondent":"大野計画担当課長","answer":"５名についてですけれども、２０代の方が１名、この方につきましては、地方から品川区に移り住んできて、まだ居住歴の短いという方。そのうち２名につきましては子育て世代の方で、残りの２名につきましては、地域でさまざまな活動をしていらっしゃる方です。","id":"exchange-008"},{"speaker":"吉田委員","kind":"質問・要望","question":"何が何でも発言を求めて、１回は意見を言うようにしてきたのだけれども、せいぜい１回意見を言うだけなわけです。なので、いつぐらいからこういうパブリックコメントがあります、その辺についてはいかがか尋ねました。","respondent":"大野計画担当課長","answer":"ちょっと時間がですけれども、委員長も可能な限り公募区民の方、委員会の進め方の中で検討していきたいと考えております。パブリックコメントについてですけれども、パブリックコメントに至るまでの周知の方法等については、しっかりと検討してまいりたいと思います。","id":"exchange-009"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから、要旨になるかわかりませんけれども、それが公開されていることの周知もぜひ早め早めに対応していただけるようにお願いしたいと思います。これは要望でとどめします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問","question":"その辺については、やはりすごく変化が激しいですから、やはり変化に対応するような基本計画を考えてつくり上げていってほしいというふうに思います。意見だけ申しあげます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-02","title":"のシティプロモーションの取組について（ＷＥＢマガジン）","agenda":"のシティプロモーションの取組について（ＷＥＢマガジン）","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"２カ月に１回の更新では、年間６組というのは、結構重たいＷＥＢマガジンという認識でいいのですか。いつ、どこで、どういう取材をしていくのかということをお聞かせいただきたい。","respondent":"木村報道・プロモーション担当課長","answer":"いわゆる深掘りをしていくようなイメージで考えておりまして、それを考えますと、このぐらいのペースになるのかというところで考えております。そういう形も考えておりまして、何か方法を限定してこうやるというのではなく、柔軟に対応してまいりたいと考えています。","id":"exchange-012"},{"speaker":"いながわ委員","kind":"質問・要望","question":"町会は町会で地域の活性化のために頑張ってやっているわけですから。そういうことをもしやるのであれば、そういった部分をどう考えてこの事業を進めていくかという全体像を最後にお聞かせほしいと求めました。","respondent":"木村報道・プロモーション担当課長","answer":"それから、先ほど、例示として挙げられたようなおもしろい取り組みをされている方に着目した形でもやっていきたいと考えています。","id":"exchange-013"},{"speaker":"いながわ委員","kind":"質問","question":"では、資料の周知のところにもあるように、いろいろな形で行っていくと思うのですけれども、その周知をする際の説明文といいますか、区民の方が間違った解釈をしないよう、ちゃんとした説明文を載せてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"後世につなげていく、こういうことがあって今の品川区はあるのだなとうなずけるような内容も必要ではないかと思うのですけれども、いかがでしょうか。５年、１０年と続けていくのか、予算と今後の展開についても概要をご説明ほしいと求めました。","respondent":"木村報道・プロモーション担当課長","answer":"２つご質問をいただきまして、いわゆる時系列、時間軸みたいなところも捉えつつ考えてまいりたいと考えています。そのときどきの状況を見ながらという形になると思いますが、しばらくは続けてまいりたいと考えております。","id":"exchange-015"}]},{"id":"topic-03","title":"庁舎食堂の営業休止","agenda":"庁舎食堂の営業休止","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"どういう契約で、ガス、売り上げの何％を品川区に入れてくれという話なのかというところを詳しく知りたい。そこは今後考えていかなければいけないと思うのですが、最初の前段の部分を教えていただきたいです。","respondent":"黒田人事課長","answer":"光熱水費は２分の１負担ですが、黒字経営になっていない、会社の経営判断として契約の継続は難しいというところで解除の通知があったというものです。当初の覚書では、平成３３年３月までということではありましたが、途中での解除というものです。","id":"exchange-016"},{"speaker":"いながわ委員","kind":"質問・要望","question":"通常であれば、家賃が免除で光熱水費の負担も２分の１となると、非常に待遇のいい、私は素人ですから、すごくいいのではないかという思いがある。味はどうなのだとか、対応はどうなのだと考えると、そういう私案というものはお持ちなのか尋ねました。","respondent":"黒田人事課長","answer":"午前１０時から午後４時までの範囲で条件に合う提案をしていただきたいということで、少し営業的に厳しいため今回の提案条件を変更しております。現時点では、提案条件を変えて、どのような提案がでてくるかというところで少し運営について見ていきたいと思っているところです。","id":"exchange-017"},{"speaker":"いながわ委員","kind":"提案","question":"アクセスが悪いところに人はなにげにおいしければ集まったりする部分があるわけですから、それは別にしても、そういう考え方も必要ではないですか。私、今、提案してしまっていますけれども、どう思いますかとの意見を述べました。","respondent":"黒田人事課長","answer":"それなりにニーズがありますので、できるだけ休止期間を短くするため、簡易型プロポーザル方式で行って事業者をまず決めていきたいです。その辺も勘案しながら、また今後、事業者が出す提案のヒアリング等々において聞いてみたいと思ってあります。","id":"exchange-018"},{"speaker":"いながわ委員","kind":"質問・要望","question":"会社側からするとそれが１つのメリットになって赤字でもやるということがあるかもしれないですけれども、置いておいてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問","question":"改めて庁舎の食堂が福利厚生であり、どういう位置づけで運営を行っているのか、その点を伺いたいと思います。今後、簡易型プロポーザル方式をとるということですけれども、どういう視点で選んでいくのか、そこを伺いたいと思います。","respondent":"黒田人事課長","answer":"プリペイドカードは、新たな提案の中では、より区民サービスのほうに重点を置いた提案が出てくればいいなというふうに思っているところです。入り口、厨房機器などの中で、いいものを事業者からご提案いただきたいと思っているです。","id":"exchange-020"},{"speaker":"須貝委員","kind":"質問・要望","question":"庁舎の食堂がありますとどこにも書いていないわけですから、その中で競争しろと言っても、これは本当に不平等な競争です。その辺は、区民サービスの一環から何とか業者が頻繁に変わらないように、長くやっていけるような支援をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"須貝委員","kind":"質問","question":"業者とすれば、そんなに人員を要するような機械設備工事とは思えないのですが、それでもできないのでしょうか。人員がたくさんいらっしゃるような気もするのですが、人員不足ということは、ここの会社に普段からほとんどいらっしゃらないということなのか尋ねました。","respondent":"立木経理課長","answer":"何とも説明しがたいところではあるのですが、なかなか配置が間に合わないということもありますので、おそらくはそういうことなのだろうかというふうには考えてあります。","id":"exchange-022"},{"speaker":"須貝委員","kind":"質問・要望","question":"品川区は、多くの事業者が的確に適正に工事をされているのですから、もうちょっと入札に参加してくださる事業者を増やしていただきたい。意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"}]},{"id":"topic-04","title":"工事等請負契約に係る前払金の限度額拡大","agenda":"工事等請負契約に係る前払金の限度額拡大","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"限度額拡大の理由はオリンピック・パラリンピックの影響ということですけれども、今回の限度額拡大は、いわゆる時限立法なのか、２０２０年の東京オリンピック・パラリンピック後についての対応は、その状況を見て判断するのか、ご説明ほしいと求めました。","respondent":"立木経理課長","answer":"今回の件に関しましては、契約事務規則の改正ということになりまして、当面はこの形になります。オリンピック・パラリンピックのいわゆる建設ラッシュが終わった後の対応については、また検討するということになろうかと思います。","id":"exchange-024"},{"speaker":"須貝委員","kind":"質問","question":"お聞きしたいのですが、土木工事、建設工事、整備工事が対象なのですが、一般的に、民間での支払いはどのような形が多いのですか。このような形をとっているのか尋ねました。","respondent":"立木経理課長","answer":"私も具体的に調べてございませんので、何とも言いがたいところではあるのですが、やはり前払金で一定程度、資材購入とかの準備金を渡している。中間払いもありますので、その都度、施工の完成度に合わせて必要な資金をお渡ししていく形が一般的ではなかろうかと考えております。","id":"exchange-025"},{"speaker":"須貝委員","kind":"質問","question":"そういうところに依頼して、さらにこういうふうに多めに前払金を渡すというのは、逆に不安に思うのですが、どうなのですか。これから民間との格差もどんどん出てきているということを考えると、いかがなものかなという気もするのですが、説明を求めました。","respondent":"立木経理課長","answer":"逆の考え方をいたしますと、工事が最後まで履行されるというような部分もあると考えられますので、こういった制度が必要なことではなかろうかと考えています。","id":"exchange-026"},{"speaker":"須貝委員","kind":"意見","question":"区の仕事を請け負ったという契約書を見せれば、おそらく銀行でもお金を貸していただけるはずだし、そんな高金利な状況ではないので、民間との格差がどんどん広がってきて、どうなのかと思いますし、我々も不安に思うので、意見だけ言わせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"吉田委員","kind":"質問","question":"こういうことに不案内で基本的なことを伺いますけれども、着手のときに払われて、その後は完成のときに支払われるという理解でよろしいのか尋ねました。","respondent":"立木経理課長","answer":"中間前払金がございまして、土木工事等の場合ですと、契約金額の２割を超えない範囲内で、１億５,０００万円を限度としております。","id":"exchange-028"},{"speaker":"吉田委員","kind":"質問","question":"そうしますと、最終的に払う額は契約金額で決まっているわけだから、最初の支払いが重くなるという理解でよろしいのか尋ねました。","respondent":"立木経理課長","answer":"建設工事に入る前に、いろいろ資材の調達等の準備等もありますので、最初にかかるお金は当然多くなる可能性があります。は出来高に従いましてお支払いをするという形になってあります。","id":"exchange-029"}]},{"id":"topic-05","title":"契約の適正な履行の確保と労働環境の整備に配慮した調達方針","agenda":"契約の適正な履行の確保と労働環境の整備に配慮した調達方針","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"賃金の確認があったので、確認ですが、それがまず１点。私どもが関係ある連合とか、そういった団体もこの「等」の中に含まれるのか、その３点をお伺いします。","respondent":"立木経理課長","answer":"一応、一定程度、対応をきちんと職種ごとに１日当たりの賃金等を全ての下請けの事業者からも取得するというような形を今のところ考えております。まだ具体的にどのような団体かはこれから検討しますが、総合的に検討させていただければというふうに今のところ考えてあります。","id":"exchange-030"},{"speaker":"いながわ委員","kind":"質問・要望","question":"２０項目あるというのは、建設現場をつくっていただきたいという思いがありますので、よろしくお願いします。実際に品川区は２,０００万円以上の公共工事とかを含めて、２,０００万円以下はどれぐらいあるのか、。","respondent":"立木経理課長","answer":"これから初めて取り組んでいくことですので、来年度、条例等の検討をさせていただければと考えています。それから、委託に関しましては、１,８５０件中１５５件、こちらのほうは母数が多いので８.４％です。","id":"exchange-031"},{"speaker":"いながわ委員","kind":"意見","question":"そのチェックシートの２０項目というのは、何を基準につくるのか。そうではなく、そのチェックシートを利用されるのかは別にして、各団体を呼んで意見交換を何回かやるという流れでいいのかどうなのかとの意見を述べました。","respondent":"立木経理課長","answer":"チェックシートの項目に関しましては、既に先行してやっている他区の事例や関係法令等を勘案いたしまして、内部で検討したものを載せする予定です。","id":"exchange-032"},{"speaker":"中塚委員","kind":"確認","question":"それと、実際に支払われている金額とチェックシートで提出されているものが同じであることの確認はどうするのか。逆の言い方をすると、事実と異なるものが提出されることを防ぐため、どのような仕組みをとるのか伺いたいと思います。","respondent":"立木経理課長","answer":"実際に出していただいたチェックシートの金額が、正しいものかどうかについては、私ども、それを信じるような形になります。例えば労働者の方から何か申し入れがあった場合には、私どももきちんと契約先の事業者に調査に入るというような形をとることになるかと思います。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問・要望","question":"ちょっとよくわからなかったのでご説明いただきたいのと、そこの賃金と合っているかという区の判断基準はないということなのか伺いたいと思います。正確なものかどうかということですけれども、その会社が幾らですよという金額は公表されるということでよろしいのか、あわせて伺いたいと思います。","respondent":"立木経理課長","answer":"最低賃金について説明がうまくいっていなくて申しわけございませんでした。これは労働契約の部分の話になってございまして、私どもがこうしてくださいと強制することはできない部分があります。","id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"ただ、その改善を求めるのは、いわゆる最賃と呼ばれるものを下回らなければ区は改善を求めないということでよいのか確認したいと思います。もう１つは、労働者の報酬下限額を設定することを求めてまいりましたが、いかがか尋ねました。","respondent":"立木経理課長","answer":"最低賃金を下回らなければ、それに対して発注元であります区のほうから賃金を上げてくださいというような申し出はできないと考えております。","id":"exchange-035"},{"speaker":"中塚委員","kind":"質問・要望","question":"結局は、法律が定める最低賃金を下回らなければ改善を求める内容ではないというならば、この間。つまり、報酬下限額の設定が必要だと思うのですが、その考えはない公契約条例の検討を行うのか伺いたいと思います。","respondent":"立木経理課長","answer":"それを上回る賃金下限を設定したという場合、それだと二重の基準になってしまうという部分があります。そういったことが果たしていいのかどうかということも含めまして検討をしていくということになろうかと考えています。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問・要望","question":"最低賃金はあくまで最低額ですから、生活の保障のために、報酬下限額の設定を強く求めておきたいと思います。指定管理者制度の契約も対象となるということなのか、それとも工事のみということなのか、要綱の中身をご説明ほしいと求めました。","respondent":"立木経理課長","answer":"(1)、予定価格が２,０００万円以上の工事請負契約と予定価格が２,０００万円以上の委託契約ということで、業務委託の部分も含んです。ただし、指定管理者制度は今回含んでおりません。","id":"exchange-037"},{"speaker":"中塚委員","kind":"質問","question":"税金を投入する契約について、例えば年収２００万円を下回るワーキングプアをつくってはいけない、質の担保と労働者の雇用の改善が主眼だと思います。そういう意味では、指定管理者制度も対象にすべきだと思うのですが、最後にいかがか尋ねました。","respondent":"立木経理課長","answer":"指定管理者制度に関しましては、モニタリング等の制度もありますので、そちらのほうで一定程度カバーできるのかなというところで考えてあります。今回の要綱に関しましては、２,０００万円以上の工事請負契約、それから委託請負契約にする予定です。","id":"exchange-038"},{"speaker":"吉田委員","kind":"質問","question":"今、今のご答弁と矛盾がないようにしていくためには、モニタリングの中で労働環境についてチェックされるというふうに理解してよろしいのでしょうか。それがないと、制度上、矛盾が出るかなと思うのですけれども、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"指定管理者制度に関しましては、労働環境チェックを今、試行しているのですけれども、それを正式に進めていきたいということで検討しています。今、準備しているといった状況です。","id":"exchange-039"},{"speaker":"吉田委員","kind":"質問・要望","question":"それからもう１つ、このチェックシートの２０項目なのですけれども、その内容についてぜひ知りたいと。ぜひ条例化の方向で進めていただきたいのですけれども、その内容の改善とか、そういうことはどのように今考えておられるのか伺いたいと思います。","respondent":"立木経理課長","answer":"条例を検討するに当たりまして、適さないとか、そういったこともあります。ヒアリング、意見聴取等の中で、そういったものも含めていろいろ検討をさせていただければと考えています。","id":"exchange-040"},{"speaker":"吉田委員","kind":"提案","question":"私も今、具体的な提案ができなくて残念なのですけれども、考えていってほしいと求めました。もし何かその点についてご見解があれば伺いたいと思いますとの意見を述べました。","respondent":"立木経理課長","answer":"ご意見については所管のほうにお伝えいたします。","id":"exchange-041"},{"speaker":"須貝委員","kind":"確認","question":"その下請けまでも管理して、直接賃金を支払わない限り、そこに親会社から適正な賃金が払われているということが確認できないというふうに思うのです。ここまで長年つくってこられた建設業の産業構造の中で、抜本的な改革をするのはなかなか難しいのではないかと思うのですが、いかがか尋ねました。","respondent":"立木経理課長","answer":"今回、要綱で記載していますのは、一定程度の抑止力をもちろん私どもも期待しての今回の要綱になってあります。信頼関係でいろいろ話を聞きながら詰めするというような形になっているかと考えています。","id":"exchange-042"},{"speaker":"須貝委員","kind":"質問・要望","question":"確かに事業を請け負っているところの中には、それなりの収益を上げているようですけれども、なかなかそうなっていない。どこまで区が踏み込めるかは難しいと思うのですけれども、何とかそういう方たちにも目を向けてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"}]},{"id":"topic-06","title":"債権の放棄","agenda":"債権の放棄","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"１から９の生活保護に関して、そうした場合は、品川区に通知が来るのか尋ねました。","respondent":"齋藤会計管理者","answer":"いなくなった時点で生活保護は廃止になる。生活保護は受けられますので、その間の自治体間の連携がどうなっているかについては、私は承知しておりません。","id":"exchange-044"},{"speaker":"中塚委員","kind":"質問・要望","question":"ちょっと言葉の定義を教えていただきたいのですけれども、いわゆる「執行停止」と「債権放棄」というのはどう違うのですか。どう違うのか、ご説明いただきたいと思うのですけれども、いかがか尋ねました。","respondent":"齋藤会計管理者","answer":"私債権等の管理に関する条例では、一旦状況を見て、１年間、様子を見る。状況が変わらなかったときに、初めて債権を放棄する、こういう取り扱いになっているので、執行停止して１年たって放棄するという形になります。","id":"exchange-045"},{"speaker":"中塚委員","kind":"質問","question":"１年たって状況の改善が見込めないときに債権を放棄するというお話ですけれども、国保料だったり、どういう取り扱いになっていらっしゃるのか。大体、生活保護の関係がいつも主だったというふうには記憶しているのですけれども、単純な疑問から聞きますが、ご説明いただけますか尋ねました。","respondent":"齋藤会計管理者","answer":"区で差し押さえ、換価処分もできますので、各所管で対応しております。ですから、各所管で報告があるかどうか、私は詳細はわかりませんけれども、私が所管しておりますのは、あくまで私債権といわれているものです。","id":"exchange-046"},{"speaker":"中塚委員","kind":"質問","question":"その執行停止が行われていると思うのですけれども、区民税としては、いわゆる債権放棄としての手続きを行った実績は過去にないということなのか尋ねました。","respondent":"伊東税務課長","answer":"区民税関係のことに関しては、当然、執行停止ですとか債権放棄がありますので、それは決算の段階で決算書に数字を載せさせていただいて報告をしています。","id":"exchange-047"},{"speaker":"中塚委員","kind":"質問","question":"ここの資料は私債権のものですか。よくわかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"}]},{"id":"topic-07","title":"平成３１年４月２１日執行 品川区議会議員選挙執行計画","agenda":"平成３１年４月２１日執行 品川区議会議員選挙執行計画","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"１０連休はなかなか読めない部分がありますので、よろしくお願いしたいと思いますが、いかがか尋ねました。","respondent":"秋山選挙管理委員会事務局長","answer":"２月１５日の立候補予定者説明会では、いつ予約をしていただきたいというような日程等をお示ししていこうというふうに考えております。当然、こちらへ来ていただく日程等を事前に予約していただけるようなことを考えてあります。","id":"exchange-049"},{"speaker":"いながわ委員","kind":"質問","question":"１点。それも含めて６日まで、１５日以内とするということか尋ねました。","respondent":"秋山選挙管理委員会事務局長","answer":"収支報告書の提出は１５日間というふうに公職選挙法で決められておりますけれども、例えば電話代とかが後から請求が来たりということがあるので、これで一次の受付を完了させていただいた上で、修正、それから後からの報告書等も受け付けるという形で今までもやってあります。","id":"exchange-050"},{"speaker":"中塚委員","kind":"質問・要望","question":"なかなかやりとりしていると間に合わなかったという話をよく伺うのですけれども、ここに書いてある４月１７日水曜日までに請求をするには、何日までに交付のための申請をすればいいのかご説明ほしいと求めました。","respondent":"秋山選挙管理委員会事務局長","answer":"実際的には、郵便投票の申請について許可書が手元に行くまでにある程度時間がかかりますので、それについては早めにお願いするということで毎回お話をしています。","id":"exchange-051"},{"speaker":"中塚委員","kind":"確認","question":"郵便でやりとりしている間に１７日を過ぎてしまったという話が、告示日より前に交付のための申請ができるということなのか、そこを確認したいと求めました。","respondent":"秋山選挙管理委員会事務局長","answer":"要介護５の方などは、今のうちから請求をいただければ、郵便投票の証明書をお渡しします。区議会議員選挙の投票用紙の請求は４月１７日までという形になってありますので、そのようにお願いいたします。","id":"exchange-052"},{"speaker":"吉田委員","kind":"質問・要望","question":"２０日まで、原則そういうことなのでしょうけれども、なるべく早く配っていただきたい。何かコメントがあればほしいと求めました。","respondent":"秋山選挙管理委員会事務局長","answer":"なるべく早期に配布できるようにということで事業者とは話をしております。開始の１５日の朝から配布しておりますので、間に合わない方は期日前投票所で言っていただければ、選挙公報をお渡しできるようにしております。","id":"exchange-053"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"候補者一覧が点字でなかなかすぐには届かない時間がかかるということを伺っているのですが、できるだけ大きな文字で候補者名の一覧をつくっていただくなど何か対応策があるのかどうかお伺いしたいのですが、いかがか尋ねました。","respondent":"秋山選挙管理委員会事務局長","answer":"委託等でつくっておりますので、これもなるべく早く期日前投票所に配備できるように、こちらのほうも用意していきたいと考えています。","id":"exchange-054"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/993969?Template=document&Id=2128#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":40904,"voices":146}},{"id":"r01-20190122-14","meetingId":"r01-cm01","date":"2019年1月22日","dateIso":"2019-01-22","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ４時４５分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を11件整理しています。","topics":[{"id":"topic-01","title":"区有施設・公有地等活用に関することのうち、国・都有地等の有効活用","agenda":"区有施設・公有地等活用に関することのうち、国・都有地等の有効活用","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"質問としましては、これまで消防署の移転については近隣住民にどのような説明が行われてきたのか伺いたいと思います。それと、消防署の移転も含めた計画案について、近隣住民へ説明する機会というのを、改めて持つべきだと思うのですけれども、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"今後の計画も含めて、区といたしましては地元の方々にも説明会と言いますか、説明する場面をつくっていきたいと思ってあります。そういった中で、どういった形でお話の機会をつくるのがいいのかということも含めて相談をしながら進めていければと考えています。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"こういう計画、考えを持っているのだということは伝えていかないと、なかなか理解を得がたくなってしまうのではないかという危惧があります。その際には東京都ともしっかり連携をとって、このことも含めて住民の方にお知らせしてご意見をいただくような形にしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"須貝委員","kind":"質問・要望","question":"過去にさかのぼってお聞きしたいのですが、本当に私は立派なことだと思いますし、区民の要望も多いと思います。そちらのほうにも広いところがあると思うのですが、いろいろ検討された中で、なぜここに決まったのか、その辺の経緯も説明を求めました。","respondent":"柏原企画調整課長","answer":"さまざま検討する中で、道路づけが一番よいところ、位置的にはこの場所がよろしいのではないかという検討をしてきたというところです。そのタイミングということで、秋に都市計画審議会の説明というのが入ってきたという流れです。","id":"exchange-003"},{"speaker":"須貝委員","kind":"確認","question":"今回１２月１６日に国有地の取得を東京都等に対して認めるということで、町会には説明はされたということでいいのでしょうか。なかなか地元の住民の皆さん、その辺はやはり、そちらまで手が回らなかったのかどうなのかという確認したいと求めました。","respondent":"柏原企画調整課長","answer":"それを今後、計画の説明をするに当たって、このような流れになっているのだというところで理解しております。委員のご質問の中に、どういった説明をされたのかとか、そういったところのやりとりが確かあったというふうに記憶しております。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"なかなかどうしろということは言えませんが、できるだけ配慮して、私は進めるようにお願いしたいと思います。どうのこうのとは言いませんので、皆さんから来た要望に対して、できる限り区としても対処してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"木村委員","kind":"意見","question":"この３カ所を区が取得して、それをつくることによって、道路を拡張するような話も聞いております。そういう中で、これをやることによって、住民の皆さんにどういう影響があるのか、そのお考えをお聞かせほしいと求めました。","respondent":"柏原企画調整課長","answer":"例えば火事等があったときに、そういった車両が入って消火活動や救護活動が行いやすくなるというのが、やはり大きなところと考えています。それは、東側のところで区が取得を予定しております土地の部分、道路部分も同じような形です。","id":"exchange-006"},{"speaker":"木村委員","kind":"質問","question":"そういうところに対して、区はどのように区民の皆さんにそれを納得させるのですか。そして、交通事故の問題にしてもこれから多発してくると思うのですけれども、その点もお伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"委員から納得させるかというお話もあったのですが、ご理解をいただけるように、そのことに関しましてはお話をさせていただきたいと思います。そういったことも含めて、では区としてそこに対して何ができるのかということも含めてお話をする必要があるかと思います。","id":"exchange-007"},{"speaker":"木村委員","kind":"質問・要望","question":"本当に行政として住民の皆さんと両輪のような関係であるわけですから、ぜひその点をしっかりと住民の理解を得るように努力をしていただきたいと考えていますし、計画を進めていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"}]},{"id":"topic-02","title":"特定事件調査のまとめ","agenda":"特定事件調査のまとめ","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"１点だけ。今回の返礼品の見直しもそうですが、記述すべきではないかと思うのですが、意見だけ言わせていただきます。","respondent":"中塚委員長","answer":"まとめにどのように反映できるか正副で検討させていただきたいと思います。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"今回、視察で渋谷区役所に行きますが、これは何のために行くのか明示されていないのですね。行財政改革特別委員会は特定の事件を調査するために設置されているのですが、今回は何のために行くのかを説明するよう求めました。","respondent":"中塚委員長","answer":"区有施設・公有地等活用に関することの調査項目のうち、庁舎のあり方について調査するため、渋谷区役所の新庁舎の現状について視察を行います。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問","question":"ということは、向こうの区役所の職員の方とお話できる、議論できる場があるというふうに考えていいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/990135?Template=document&Id=6064#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":9410,"voices":41}},{"id":"r01-20190123-18","meetingId":"r01-cm01","date":"2019年1月23日","dateIso":"2019-01-23","committee":"オリンピック・パラリンピック推進特別委員会","time":"午前 ９時００分～午後 ０時３０分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件整理しています。","topics":[{"id":"topic-01","title":"の２の特定事件調査","agenda":"の２の特定事件調査","exchanges":[{"speaker":"大倉委員","kind":"確認","question":"私が発言したのですが、東京都だと１８歳以下がボランティアできるものがなかったのかなと思ったので、高校生とかというのは入れられないでしょうか。確認で、１８歳以下はたしかボランティアはなかったですよね。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"大会組織委員会と東京都で募集している大会ボランティアと都市ボランティア、こちらは１８歳以上ということで、高校生は対象外となっております。","id":"exchange-001"},{"speaker":"大倉委員","kind":"意見","question":"私がこれを申し上げたときも、子どもたちがというところでいうと、高校生とかも入ってくるのかなと思うので、小中学生だけでなく、高校生とかも入れていただいたほうがいいのかなという意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"田中委員","kind":"意見","question":"区独自の取組みの（９）なのですけれども、どうなっているのかということと、同施設の営業期間終了後も区内で同等の環境が維持できるよう検討することということについての説明を聞きたいですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"スポル品川大井町に対してだけ、（９）は賛同しかねるという思いがしますので、これを除いていただけないかなという思いがあるのですけれども。そういうところは１２月までの期限に出していなければ、この場では出せないということになるのか尋ねました。","respondent":"いながわ委員長","answer":"正副で取りまとめをしていますけれども、いろいろな視点の中で必要性があるものと考えていますので、その中でお願いをしたいと。大きな修正というのは、１２月２１日締め切りということでございましたので、そこはぜひご理解を賜りたく存じます。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"それで全会一致というところなので、今、田中委員からもありましたので、（９）については賛同しかねるということで、除いていただけたらなと。全会一致で決めていくということになると思いますので、ぜひお願いできたらなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問","question":"それをここでまた覆すとなると、資料も出して、何かあれば１２月２１日までにといったのですから、それはだめではないですか。そこはよく理解して、運営をしてほしいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"つる委員","kind":"意見","question":"（１０）にパラアリーナも参考とすることとあるのですが、ここは鍵括弧をつけるかどうか含めて、そこだけ検討していただけますかとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問","question":"前回のときに出されたのは主な意見で、今回、まとめの案が出されたのは初めてだという認識なのです。今回議論して、次回まとめていくのかなという認識だったのですけれども、そこのところを伺いたいです。","respondent":"いながわ委員長","answer":"１２月２１日までに全体的にこういう意見が出ましたということを主軸に、今回、このまとめの案が出されたということです。〔「書式がちょっと違う」と呼ぶ者あり〕 書式はあれですが、それを見た中で、もし何かありましたらということで申し伝えたと私は記憶しておりますので、ご理解いただきたいと考えています。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問","question":"意見についての是非どうこうということではなくて、委員会の進め方というのですか、それを前提に皆さんで議論をしていくと。まとめの案が示されたのは今回初めてだということで、それを今回話し合って決めていくということだと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"南委員","kind":"意見","question":"それはそれとしてわかるのですけれども、私の受けとめは、確かに１２月２１日までに出してくれというのは記憶しています。〔「前、まとまりましたよね」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"南委員","kind":"質問","question":"だから、そういう意見をもって、先ほども意見を言ってきたわけです。そういう理解ではないのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"南委員","kind":"確認","question":"これで本当に皆さんいいですかと、今日、意見を言えるのだと思っていたわけです。そういう確認する場を持たなくていいのかということなのですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"南委員","kind":"意見","question":"それぞれの会派から出したから、もう少しみんなの意見を平場で聞ける、そういう対応があっていいのではないかなと思います。〔「全然違う」と呼ぶ者あり〕との意見を述べました。","respondent":"いながわ委員長","answer":"１回、決定していきたいと考えていますので、よろしくお願いします。","id":"exchange-013"},{"speaker":"南委員","kind":"質問","question":"、そういう采配を振るっていただいて。先ほど２会派から出ている区独自の取組みの（９）については、そういった意見も含めて正副で検討していただけるという理解でいいのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"南委員","kind":"意見","question":"２会派から出ているということは、やっぱり一定程度の重みがあるので、ぜひ前向きに受けとめていただける方向で検討を、全会一致できるような内容でまとめていただければということを申しわけありませんけれどもあえて申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"ＪＲ東日本スポーツ株式会社に対してということで、これは多分品川区からの利用料の補助についてということですよね。〔「違いますよ」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"あくつ委員","kind":"提案","question":"私も提案者の１人なのですが、そういうことは言っていないですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"あくつ委員","kind":"質問・要望","question":"区民からあった意見をこちらに伝えて出しているわけですから、２会派の意見が重いならば、１人の委員の意見も重いわけです。それを簡単に削除してほしいとかと勝手に言う神経を私は疑います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"区民割引を行うよう補助するという、そういうふうな、割引について協議をするようにという文言に変わるのであればそこら辺のところも。〔「意味がわかったのなら変えなくていいのでは」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"私はここのところでは、そういうのであれば違和感があるなという思いがしたので、先ほどの意見を申し上げたのです。そこのところが意味が通るような形での文言にしていただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"あくつ委員","kind":"質問","question":"今、鈴木ひろ子委員、また、ほかの委員からもあったとおり、文言修正すればこれはいいということでよろしいのですかね。では、文言修正についてはお任せしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"鈴木（真）副委員長","kind":"質問・要望","question":"まとめの中でこれで確認をとらせてほしいと求めましたが、そのまま進めさせていただきたいと、副委員長の立場ではお願いしたいです。","respondent":"いながわ委員長","answer":"先ほど正副で１回預かるということだったのですが、決定していきたいと思いますが、よろしいでしょうか。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問","question":"（１）のところで、選手の方はあまり存続を望んでいないのではないかという声をお聞きしたので、そういった当事者の方々の意見も聞きながら進めていくようにというふうにお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"石田（秀）委員","kind":"質問","question":"私は、今の話は、１人の方からかどうかわからないですけれども、私の知っている団体では、あれをずっと残してほしいと言っている人がいます。それだったら、このままでまず働きかけなければしようがないのですから、大きな判断のときに、その１行を入れる必要はないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"いながわ委員長","kind":"質問・要望","question":"日本財団や東京都にそういった存続を求めていくことは大切ではないかと意見が出されたのですが、この文章を見ると、私もそう理解しております。意見が２つに分かれていても、逆に、のだて委員には（１）のままでいくということをご理解いただきたいなと思うのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"私が意見を聞いたのはお１人の方なのですけれども、私も城南地区に障害者スポーツの拠点をつくるというのはぜひやっていただきたいと考えています。文言修正は必要ないということですので、修正しない中でも、ぜひ利用者の声はちゃんと反映してほしいと求めましたので、そのことを要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今日のまとめの案の文章なのですけれども、机上配布だったので、できれば資料とともに２日前にぜひこれを配付していただいて、軽微なところについてでも検討できるようにということで、今後、机上配付ではなく、事前に配付していただきたいということを要望させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/985009?Template=document&Id=6550#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":11188,"voices":74}},{"id":"r01-20190124-10","meetingId":"r01-cm01","date":"2019年1月24日","dateIso":"2019-01-24","committee":"議会運営委員会","time":"午後 １時００分～午後 １時２４分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を8件整理しています。","topics":[{"id":"topic-01","title":"全国伝統工芸品振興市議会協議会","agenda":"全国伝統工芸品振興市議会協議会","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"特に積極的に加入をするという意見は出ませんでした。持ち帰りということで、今日の結論ということだったのかもしれないのですが、今日の議論の推移を見守らせていただきたいというのが率直なところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"共産党としても会派で検討をいたしました。伝統工芸については、ほかの会派の皆様と同じような形で、積極的に参加をしていくということではなくていいのではないかとなりましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"石田（し）委員","kind":"意見","question":"我々としても、現時点では参加を見送って、今後またさまざまな場面で参加または不参加というのは決定していけばいいのかと考えています。会派としては、参加を見送るということで結論が出ましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"防災訓練の件なのですけれども、避難所訓練のところに1)から16)ぐらいまで具体的に書かれているものがいろいろあるではないですか。そこの最後の部分、答えの部分はどうなったかという改善の方法とかを、何かどこかで考えたほうがいいのではないですかということだけです。","respondent":"久保田区議会事務局長","answer":"これを防災課のほうに報告して、事務局としてはそのような形で防災課のほうに報告はさせていただきたいと思ってあります。防災課のほうと協議しなければなりませんので、報告ということに関しては、議会運営委員会の中でご確認いただければ可能だと思います。","id":"exchange-004"},{"speaker":"石田（し）委員","kind":"意見","question":"ぜひそこは皆様認識を新たに持っていただいて、次のステップに行けるように考えていくべきではないかなと。意見だけですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問","question":"今のお話はせっかく言っていただいたので、避難所訓練と防災訓練とかは我々も出たりするではないですか。例えば今これを見ると、城二なんて、こんなものは早くやったほうがいいのではないかと普通にぱっと見ると思うではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"意見","question":"我々が今どういう体制なのか、「ちゃんと個別対応は町会とうまくやってください」ぐらいでいいのではないのか、防災課には。出すなら出してもいいけれどもとの意見を述べました。","respondent":"渡部委員長","answer":"次年度の訓練内容については、改めてそういうわけで検討を進めていければと考えていますので、引き続きよろしくお願いいたします。ほかにその他ですか。","id":"exchange-007"},{"speaker":"あくつ委員","kind":"質問・要望","question":"一応確認で、これは別に今すぐやってくださいということではないのですが、ぜひこれは俎上に上げていただきたいということの確認です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/201447?Template=document&Id=5312#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":8847,"voices":34}},{"id":"r01-20190219-10","meetingId":"r01-cm02","date":"2019年2月19日","dateIso":"2019-02-19","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時５０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"議会費で１点だけお伺いしたいのですが、本会議録原本電子化経費が３月末で終了ということですが、どういうことなのかもう少し説明を求めました。","respondent":"久保田区議会事務局長","answer":"こちらについては、昭和２２年から平成２年までのものが紙でしか保存されておらず、昭和２０年代、３０年代のものも大分傷んできていますので、この機会に電子化、ＰＤＦ化して保存する経費です。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/201447?Template=document&Id=5314#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":7035,"voices":25}},{"id":"r01-20190222-3","meetingId":"r01-c-budget","date":"2019年2月22日","dateIso":"2019-02-22","committee":"予算特別委員会","time":"午前１１時０２分～午前１１時０９分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/778040?Template=document&Id=1088#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":1988,"voices":17}},{"id":"r01-20190225-6","meetingId":"r01-cm02","date":"2019年2月25日","dateIso":"2019-02-25","committee":"区民委員会","time":"午前１０時００分～午前１１時２７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件整理しています。","topics":[{"id":"topic-01","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"報告ですから、相手方の住所とかお名前とか、こうして公の場に出てくるではないですか。ただ車をとめていたわけですから、氏名がこういう形で出てくるのはいかがなものかと思うのですけれども、その辺のお考えについて説明を求めました。","respondent":"伊崎地域活動課長","answer":"前段で説明を申し上げましたように、議会の指定議決に基づいて行います専決処分で、このような形でご報告をするというルールで来ております。今この場で私のほうからこの様式についての是非等については申し述べることはできないということでご了承いただければと思います。","id":"exchange-001"},{"speaker":"藤原委員","kind":"質問・要望","question":"本人に確認していないわけですよね。ぜひ伝えていただいて、そういうのは役所の中で議論していただくというのもありだと思うのですけれども、その辺についてはいかがか尋ねました。","respondent":"堀越地域振興部長","answer":"相手方の氏名、住所等もしっかりと確認をするという意味で、しっかりとご報告するという意味で記載をさせていただいています。そういう部分については名前は隠した形で、あとはそのほかの部分についてはそういうふうな対応をしっかりとするということになっております。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"今、７２万円の内訳の中で、評価損というのがあったのですけれども、これがどういうものなのか教えていただけませんか。","respondent":"伊崎地域活動課長","answer":"事故車扱いとなってしまうということで、こちらの車両について１０万円の評価が下がるということで、そこの補償です。骨格の部分まで破損がありましたので、事故車扱いになってしまうため、この１０万円の評価損が保険会社によって算定されたです。","id":"exchange-003"},{"speaker":"浅野副委員長","kind":"質問","question":"区としてはそういうような訓練も含めた車の運転に関するところをどのような形で注意喚起を払いながら、事故が起きないようにしているのですか。教えていただければと思うのですが、いかがか尋ねました。","respondent":"伊崎地域活動課長","answer":"区全体としましては、運転者講習会などを実施して、運転技術の維持向上を図っているところです。所長および私のほうから運転についての注意、自分の技量をきちんとわかった上でやることというようなことも含めまして、指導を行っているところです。","id":"exchange-004"}]},{"id":"topic-02","title":"オリジナル出生届の配布","agenda":"オリジナル出生届の配布","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"２つともすばらしいと思うのですが、こういうのは誰がデザインするのか尋ねました。","respondent":"提坂戸籍住民課長","answer":"シナモロールを随所にデザインするということで、これは業者にいろいろなデザインを考えていただきました。いろいろ一生懸命デザインを考えて、公園については公園課のいろいろなアドバイスも受けながらデザインを考えさせていただいたという次第です。","id":"exchange-005"},{"speaker":"大倉委員","kind":"確認","question":"確認なのですけれども、１年間の子どもが生まれる数から逆算してそのようになったのか、どういうふうになっているのか。例えば、１年さかのぼってということなので、１年前に生まれた方たちにもうまく回るような数なのか、その辺の数の考え方等、説明を求めました。","respondent":"提坂戸籍住民課長","answer":"もう１種類は、もう１種類は違う系統の色がいいだろうということで、結局この２種類で決定させていただいたという次第です。５,０００部つくればとりあえず１年間もつだろうということで、また来年、十分足りる部数ということで判断させていただきました。","id":"exchange-006"},{"speaker":"大倉委員","kind":"質問・要望","question":"ああ、寄り添っていろいろつくっていこうという思いがあるかなというところは見受けられると思うので、ぜひやっていただきたいなと思っています。ぜひ欲しいという人たちがいたらあげられるのかというところを教えていただきたいのと、あとは３月３日、その辺の考え方についても説明を求めました。","respondent":"提坂戸籍住民課長","answer":"先ほどの説明で、おおむね１年以内ということでご説明はさせていただきましたけれども、申し出があれば差し上げる形で実施したいと考えております。","id":"exchange-007"},{"speaker":"大倉委員","kind":"質問・要望","question":"せっかくこういうのをつくったので、その辺もやっていただきたい、考えていただければと思っています。保管というところでも、保管、飾るというところでいうクリアファイルやケースを差し上げるという考え方はいかがか尋ねました。","respondent":"提坂戸籍住民課長","answer":"配布当初はクリアファイルは添付しませんけれども、今後のそういったご要望なども踏まえて、今後検討させていただきたいと思います。","id":"exchange-008"},{"speaker":"渡辺委員","kind":"質問","question":"それをどう活用してもらうかというところで、もう二声ぐらい力を入れていいのかなというぐらいに、実際に実物を見て思いました。区長のお言葉ではないですけれども、幸せを広げるという点ではものすごくいいツールだと思ったので、その辺の担当としての抱負をまず説明を求めました。","respondent":"提坂戸籍住民課長","answer":"広報やホームページで周知するのは配布開始のときだけではございませんで、また定期的な周知を図ってまいりたいと思います。お配りした際に、また何年後かには見直しをしますので、その辺でまたよりよいデザインをつくってまいりたいと考えております。","id":"exchange-009"},{"speaker":"渡辺委員","kind":"質問","question":"公園にしろ、遊べるところにしろ。その辺で、抱負的な話になりますが、それを伺って終わります。","respondent":"提坂戸籍住民課長","answer":"行政がつくるパンフレットなどにかたいものが多いとよく言われますけれども、これについては、新しく誕生した赤ちゃんに対してのものなので、なるべくソフトで温かいようなものを追求し続けて参りたいと考えております。","id":"exchange-010"}]},{"id":"topic-03","title":"しながわ文化プログラム推進事業助成","agenda":"しながわ文化プログラム推進事業助成","exchanges":[{"speaker":"田中委員","kind":"質問","question":"前回のしながわ文化プログラム推進事業助成と内容が変わった理由を説明するよう求めました。","respondent":"立川文化観光課長","answer":"改定の理由ですが、まず対象団体を拡大したかったということでございまして、また支援内容を充実させたかったということです。これまで上限額が２分の１で２００万円となっておりましたけれども、助成率と助成額ともに上げすることで、こういった改定をしたところです。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問","question":"条例のときだと議論の場があるではないですか、委員会でも。ここで根拠となる要綱も、この資料の中で書いていていただけると助かると思いますが、いかがか尋ねました。","respondent":"立川文化観光課長","answer":"こちらはいわゆる行政のほうが適正な手続きで事業を進めるという、一番の目的としましては安定的に事業を推進するために設けるというところです。","id":"exchange-012"},{"speaker":"大倉委員","kind":"質問・要望","question":"どのぐらいの団体が申し込んでくるのかという見込みがあれば教えていただきたいのと、逆に増え過ぎるということがあったりするのかと。そういうところで、例えば地域の人たちが主催してやっていきたいものに対して、その辺の考え方についてはどういうふうにお考えか教えていただきたい。","respondent":"立川文化観光課長","answer":"実際の見込みという話ですが、今年度よりは増えるだろうと見込んでおります。予算額の範囲内で適正な、いわゆる審査基準を設けておりますので、すぐれたプログラムを採用していきたいと考えております。","id":"exchange-013"},{"speaker":"大倉委員","kind":"質問・要望","question":"そういったところの判断はどういうところでやっていくのか改めて確認をしたいのと、例えば、産業等との連携促進の視点が盛り込まれていること」と。どういうことをイメージしてやられているのかというのを教えていただきたいのと、１,５００万円、その辺について教えてほしいと求めました。","respondent":"立川文化観光課長","answer":"既存の文化芸術と、実際に事業を実施する際には、そういった広がりというものを持ってもらいたいということで盛り込んだところです。予算につきましては、すぐれた応募がたくさんあった場合には、財政当局とも相談してどうにかしていきたいというふうには考えております。","id":"exchange-014"},{"speaker":"大倉委員","kind":"提案","question":"そういうところも含めてアドバイスというのができるのでしょうかというところと、アドバイスができる方がまさに専門家として入っていらっしゃるのかどうかというのを教えていただきたいのと、こういうふうになったらいいなという品川の思いなどがあれば教えてほしいと求めました。","respondent":"立川文化観光課長","answer":"今回２０２０大会を契機に文化芸術活動を盛んにやってもらおうということですが、一番考えているのが、そういった機会になればいいのかと。それによって、後継者に承継をしていただけるというふうになるのかと考えていますので、その辺は意識してやっていきたいと考えています。","id":"exchange-015"},{"speaker":"大倉委員","kind":"意見","question":"なかなか今、団体で行っている事業のもう少しバージョンアップを目指すというところで言うと、関係とか連携とか書いてあるとおりかなと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"田中委員","kind":"質問","question":"先ほど教えていただいた要綱なのですけれども、今回新しくＢ助成で１０分の１０の助成ということなのですけれども、この助成になったのか。はこの予算額が予算書のどこに当たるのかということと、先ほどもしかしたら答弁があったかもしれないのですけれども、内訳を説明するよう求めました。","respondent":"立川文化観光課長","answer":"委員ご指摘の見つからないですが、こちらにつきましては担当に確認をします。もし、ないですと、いわゆるアップの作業がうまくいっていないのかというところですので。","id":"exchange-017"},{"speaker":"田中委員","kind":"質問","question":"〔「そうですね」と呼ぶ者あり〕そうなのです。予算書のどこに載っているのかということなのですけれども、手元にないから答弁できないということだったのですけれども、どこなのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"田中委員","kind":"質問","question":"ここに載っているのは平成３０年度ですか。平成３１年度か尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"田中委員","kind":"意見","question":"要綱はどうなったのでしたか。まだ変わる前の、それが要綱の一覧のところになかったのは、今準備中だから掲載されていないということなのかどうかとの意見を述べました。","respondent":"立川文化観光課長","answer":"今年度の要綱がもう既にページにないということは担当に確認しますけれども、来年度の要綱につきましては現在改定作業を進めているところです。","id":"exchange-020"},{"speaker":"大倉委員","kind":"質問・要望","question":"広報が３月１１日号で、締め切りが５月７日というところで、これは第１次締め切りということなのでしょうか。そういったところは区としてもぜひアドバイスとか連携というところではしていってほしいと求めましたし、その辺についても説明を求めました。","respondent":"立川文化観光課長","answer":"来年度につきましては、応募の状況などを踏まえて２次募集ができるかどうか、その辺は検討していきたいと考えています。委員ご提案ありましたとおり、その辺については、ご相談があった場合には適宜対応していきたいと考えております。","id":"exchange-021"},{"speaker":"田中委員","kind":"質問","question":"審査のことなのですけれども、審査の委員も要綱改定で変わるのでしょうか。審査委員は。","respondent":"立川文化観光課長","answer":"今年度の事業は区の内部で審査するということですが、実際にどこまで書き込むかというのが現在検討しているところです。外部の委員も交えて審査するという形にしていきたいと考えていますので、要綱のほうに書き込むことについては検討したいと考えています。","id":"exchange-022"},{"speaker":"田中委員","kind":"質問","question":"先ほど、助成の金額が上がったりしたところで、利用したくてもできなかった方や、地域主体でこの事業ができるようにという答弁があったと思うのです。区民の方も傍聴できるような開かれた会になったほうが区民の参加がもっと進むのではないかと思うのですけれども、その辺はどうか尋ねました。","respondent":"立川文化観光課長","answer":"開かれた会ということで、今考えているのは、実際に企画内容が決まったときに、開催する方のみならず、区民の方も参加して報告会のようなことができればいいとは考えております。","id":"exchange-023"},{"speaker":"藤原委員","kind":"質問","question":"なぜ、しながわ文化観光プログラムにしなかったのかと思ったのですけれども、そこをお伺いしたいのが１点。いつも気をつけてくださいというようなことを区民の方に伝えていくというのは、私は大事だと思うのですけれども、その辺についてはいかがか尋ねました。","respondent":"立川文化観光課長、辻オリンピック・パラリンピック準備課長、菅生活安全担当課長","answer":"それから、また事業を実施する団体の側がこれを契機として成長につながる、そういったさまざまな観点から選定していきたいと考えています。… 現在ですと開始してから５０件近くにはなっているのですが、文化観光課と連携をとりながら、今年度スタートしたところです。… いろいろな防犯を目的としたイベント等につきましては、例えば防犯マスコットのしなぼうを出動させて、そういったキャンペーン等を行っております。","id":"exchange-024"},{"speaker":"藤原委員","kind":"質問・要望","question":"何ら問題もありませんという答弁を伺ったので、それは伝統文化という意味で、これからいろいろな意味で助成等の要望をしていきたいと考えています。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"渡辺委員","kind":"質問・要望","question":"ここからは実務的に伺いたいのは、先ほど来質問があったように、所管を超えた品川区のメッセージだと思うのですね。２つ伺いたいのは、もう今は２月ですが、４月、５月、これは締め切りが７日だからあれなのですけれども、柔軟に対処できないか。","respondent":"辻オリンピック・パラリンピック準備課長、立川文化観光課長","answer":"２０２０大会に向かって取り組んでおりますので、オリ・パラ、私ども以外のところの事業についても積極的にグッズ等の提供は今のところもしています。今のところ、さらに積極的に… 年度をまたぐ事業については、区としても課題であると認識しております。新年度の４月、来年の４月、５月についてはイベントがスムーズに実施できるようなスキームを考えていきたいと考えています。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問・要望","question":"助成を受けた団体と受けなかった団体等の要望があって、今回改定をするというお話でしたけれども、もう少し詳しく教えてほしいと求めました。今年度６件助成されたということで、その６件がどういうイベントであったのか説明を求めました。","respondent":"立川文化観光課長","answer":"助成率の引き上げ、それから支援内容としまして、専門家によるアドバイスを実施したいというところが主なところです。こちらは社会福祉法人のトット基金が実施しているものでして、Ｏ美術館とも連携いたしまして、こういった内容です。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問","question":"この助成の対象になるのは活動実績があるところですから、全額助成ですから、そういったところを判断した理由を伺いたいと思います。","respondent":"立川文化観光課長","answer":"２分の１助成で申し込まれた団体というのは、今までやってきたイベントをベースとして、それを発展させるという形でやっていただいたところです。助成率を上げた狙いですが、高い助成率として、多くの団体に応募していただくことが必要と考えたところです。","id":"exchange-028"},{"speaker":"おくの委員","kind":"質問","question":"実例が６つということだったのですけれども、先ほど出てきたのが２つだったので、せっかくなのであとの４つも教えていただければと。","respondent":"立川文化観光課長","answer":"それから、トーキョーキャナルリンクス実行委員会というものがございまして、トーキョーキャナルリンクスという事業を実施していただきました。童謡１００周年、童謡と品川音頭でまちづくり、こういったイベントを開催しています。","id":"exchange-029"},{"speaker":"田中委員","kind":"質問","question":"細かいところになるのですけれども、先ほど予算書のページを教えていただきました。今度は要綱となるとどちらになるのかなとか、統一してほしいということを思うのですが、その辺の考え方を教えていただけたら。","respondent":"立川文化観光課長","answer":"平仮名に統一したいと考えております。","id":"exchange-030"},{"speaker":"田中委員","kind":"質問","question":"やはり、今のほかの方たちとのやりとりの中でも、前回の要綱と今回改定される要綱、条例改定のときでも新旧対照表が出されると思うのですね。それがあったほうがもう少しほかの議論もできたかと思うので、やはり要綱改定でもそのように提供していただけたらと思うのですが、いかがか尋ねました。","respondent":"立川文化観光課長","answer":"新年度の要綱につきましては今策定作業を進めているところですので、具体的に提出することが間に合わなかったというところです。新旧対照という考え方ですが、こちらにつきましては資料のつくり方で工夫していきたいと考えております。","id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/776686?Template=document&Id=2832#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":23603,"voices":105}},{"id":"r01-20190225-7","meetingId":"r01-cm02","date":"2019年2月25日","dateIso":"2019-02-25","committee":"厚生委員会","time":"午前１０時００分～午後 ４時１６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を106件整理しています。","topics":[{"id":"topic-01","title":"第２０号議案、品川区立高齢者住宅条例の一部を改正する条例","agenda":"第２０号議案、品川区立高齢者住宅条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"７万２,０００円にした理由を伺いたいのと、１３戸のうち、いらっしゃるのかということを伺いたいと思います。","respondent":"宮尾高齢者地域支援課長","answer":"７万２,０００円に改正する理由ですが、こちらの物件は新築から２０年が経過しているということで、事前に家主の方と協議を重ねてまいりました。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"わかりました。７万２,０００円から３万５,０００円前後にあたる差額、４万円ぐらいですか、都や国からも出るものなのかを伺いたいです。","respondent":"宮尾高齢者地域支援課長","answer":"実際に家主の方にお支払いする家賃と、居住者の方から実際に区に納めていただく使用料の差額につきましては、こちらのバンブーガーデンは、東京都のシルバーピアに準じた住戸となりますので、東京都からの補助金を頂戴している形になります。","id":"exchange-002"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この使用料というのは、前年の所得が何万円以下は幾らと決められている額ですよね。今回、３,０００円引き下がったことによって居住者の家賃が下がることはないということなのかを教えていただきたいのと、確認をお願いしたいです。","respondent":"宮尾高齢者地域支援課長","answer":"今回の使用料の変更、値下げとなりますが、こちらは家主に対しての引き下げを区としてお願いするような形になります。歳出額も少なくなることになりますので、補助金についても同様にそれに応じた形になりますので、入ってくる額も下がると想定しております。","id":"exchange-003"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"私が伺ったのは、相差の４万円というのは、そこのところを説明するよう求めました。","respondent":"宮尾高齢者地域支援課長","answer":"そして、東京都のシルバーピアの補助金につきましてですけれども、相差の部分が東京都から入ってくる、それは丸々全額ということではございません。東京都が定める基準に沿って、区に補助金が入ってくるという仕組みになっております。","id":"exchange-004"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"借上型も幾つかあって、それによって値段も違うではないですか。３万５,０００円だったり３万円だったり２万５,０００円だったりということで、それとも、そこのところをお聞かせいただきたいです。","respondent":"宮尾高齢者地域支援課長","answer":"ただいまの２つ目ですが、シルバーピアの基準がございまして、そちらにのっとってやらせていただいているものです。当然広さですとか立地条件ですとかいったところも加味していますので、そういったところで金額が物件ごとに異なってくるです。","id":"exchange-005"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"だから、その相差の分は丸々東京都から来るという考え方でいいのかということだけ、確認をお願いします。もし違うのだったら、その割合みたいなのもあるのか、そこら辺も説明を求めました。","respondent":"宮尾高齢者地域支援課長","answer":"割合がどのくらいというのは、丸々来ているということではなかったと思います。東京都が補助金の基準を定めておりますので、その基準に沿って、私どもから申請をして、補助金をいただくという流れになっていたと思います。","id":"exchange-006"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"そうすると、品川区もこの相差の分は出しているということなんですが、東京都が丸々ではなくて品川区も出している、品川区と東京都で相差の分を出しているという考え方なのか、その割合は今のところではわからないということなのか、その確認をお願いします。","respondent":"宮尾高齢者地域支援課長","answer":"最後、委員がおっしゃった相差の部分の一部を東京都から補助いただき、一部を区で負担しているということになります。","id":"exchange-007"}]},{"id":"topic-02","title":"第２１号議案、品川区障害者福祉手当条例の一部を改正する条例","agenda":"第２１号議案、品川区障害者福祉手当条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（真）委員","kind":"意見","question":"ごめんなさい、文言がごちゃごちゃでよくわからない状況なので、実際、この規定整備をしたことによって影響はどういうふうに出てくるか、そこだけとの意見を述べました。","respondent":"松山障害者福祉課長","answer":"これまでの対象者に影響がないように文言整備を行ってありますので、影響については、ございません。","id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"影響がないというのは、もともと障害者福祉手当というのは所得制限がありましたよね。それからあと、文言の「ならびに」と「および」というのがどう違うのかというのがちょっとよくわからないので、ここも教えてほしいと求めました。","respondent":"松山障害者福祉課長","answer":"２点目の文言につきまして、「ならびに」と「および」の法律用語の文言の整理ということで、「ならびに」というのは、比較的包括的な、大きいもの。法律用語の文言の整理です。","id":"exchange-009"}]},{"id":"topic-03","title":"第３０号議案、品川区国民健康保険条例の一部を改正する条例","agenda":"第３０号議案、品川区国民健康保険条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"東京都から品川区は今回これだけ納付してくださいということで納付金が示されると思うのですけれども、納付金が品川区の場合は幾らなのか。その納付金と所得割総額、均等割総額、そこら辺がわかれば教えていただきたいです。","respondent":"三ツ橋国保医療年金課長","answer":"一方、今回９５％として納付金を賦課総額として計算しておりますが、そちらに関しましては、品川区は賦課総額１０７億円となっております。所得割・均等割が６１対３９となっておりますので、所得割が約６４億円、均等割が４３億円となっております。","id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"平成２９年度は出されていましたし、ぜひそこの改善をお願いしたいと思うのですけれども、いかがでしょうか。賦課総額が１０７億円ということだったのですけれども、品川区の納付金は前回と比べたら下がっているのでしょうかということを伺いたいと思います。","respondent":"三ツ橋国保医療年金課長","answer":"資料につきましては、今後また工夫していきたいと思いますので、よろしくお願いいたします。納付金額に関しましては、昨年度は１２７億円となっております。","id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問","question":"わかりました。賦課限度額が６１万円に決まったということですけれども、所得が大体幾らぐらいの方が限度額になるのかを伺いたいのと、わかれば説明を求めました。","respondent":"三ツ橋国保医療年金課長","answer":"５８万円から６１万円に引き上げる部分ですけれども、申しわけありませんが、申し上げられません。","id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問","question":"わかりました。そうすると、平成３０年度は法定外繰入は幾らで、平成３１年度は幾らになるのかを伺いたいと思います。","respondent":"三ツ橋国保医療年金課長","answer":"法定外繰入金につきましては、平成３０年は１１.９億円、そして平成３１年につきましては１０億円となっております。","id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問","question":"１人当たりの保険料は、６１６円マイナスですよということで、所得割を変えずに均等割は下げるという判断をしていただけなかったのかなと。これだけ多子世帯は値上げになっているので、重くのしかかる均等割を軽減させるという考えが区としてはなかったのか、伺いたいと思います。","respondent":"三ツ橋国保医療年金課長","answer":"２３区としての将来的な方向性を出しておりますけれども、国保制度改革をするに当たってさまざまな検討をした中で、今のこの結果があります。そちらを中心に考えてきたものです。","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問","question":"２３区統一ということですが、統一ではなく、そこから抜けている自治体もあるかと思うのですね。区の判断、そこの判断に至らなかったのはなぜなのか、伺いたいと思います。","respondent":"三ツ橋国保医療年金課長","answer":"先ほど申し上げましたように、品川区は、同一世帯同一所得であれば同一の保険料という特別区の今までの考え方を継承し、賛同しております。したがいまして、そちらの考え方に基づいて保険料率を勘案しております。","id":"exchange-015"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"実際、この法定外繰入は６％までいかなくて、そこら辺の実態がどういう状況になっているのかということを教えてほしいと求めました。それからあと、今までと変わらない所得の人が限度額の額だけ上がるということでいいのかということの確認をお願いしたいと思います。","respondent":"三ツ橋国保医療年金課長","answer":"１１.９億円となっておりますが、増減がありますので、少なくなっております。それから最後の限度額８０万円ですが、所得は変わらないと考えております。","id":"exchange-016"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"これだけ減らしてきているわけですから、区独自に子どもの均等割の無料化をするなんていうのは、このことを考えただけでも容易にできると思うのです。２３区としても均等割をできるだけ上げないで、品川区からもそういう提案をして、その点の考え方についても説明を求めました。","respondent":"三ツ橋国保医療年金課長","answer":"５８対４２という大きな特別区の考え方に基づいておりますので、また、東京都の中で特別区は所得割の水準が高いというのが大きなものです。したがいまして、所得割が５８、均等割が４２という数値に基づいて算定しております。","id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それから具体的なところで、これは資料で見ると、１２ページの１０.９７億円というのが今回東京都が出した額ということになるのでしょうか。それが今回１０.９７億円しか出されなかったのかということもお聞かせほしいと求めました。","respondent":"三ツ橋国保医療年金課長","answer":"東京都の独自財政支援ですが、１４億円が来年度１７億円ということでしたけれども、都全体は１７億円と考えていいと考えています。ただし、被保険者数に応じておりますので、どうしても下がってしまうという部分があります。","id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"課長会とか区長会ですか、そういうところからも交渉して、増やすということをされたのかどうなのか。国保が破綻してくることにもつながってきますので、東京都の支援金ですか、最後に教えていただけたらと思います。","respondent":"三ツ橋国保医療年金課長","answer":"今回、東京都の激変緩和措置ですけれども、やはり区といたしましても、特別区全体で激変緩和措置の都支援金分は、引き続き要望はしています。","id":"exchange-019"},{"speaker":"若林委員","kind":"質問・要望","question":"何点か確認ですが、まず１点、確認をさせてほしいと求めました。毎年１％ずつ法定外繰入の解消・縮減ですか、所得割と均等割が６１対３９というところで、確認をさせてほしいと求めました。","respondent":"三ツ橋国保医療年金課長","answer":"もう少し伸びて３.６％だったかなと思うのですけれども、それは細かい数値が、今、手元にないのですけれども、同程度に伸びております。","id":"exchange-020"},{"speaker":"若林委員","kind":"質問・要望","question":"２３区の中でも大きな議論、５８対４２というところが、ベースになって推移しているというところは理解いたします。そこについては、さらに国に対しても都に対しても引き続きご要望をしっかりと言っていただきたいなということだけ、意見として言っておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１人当たりだから、１人当たりの納付金が減っているのに保険料が増えるというのはなぜなのかなという思いがするのですけれども、その点は何か。納付金が下がったのに、なぜ保険料が上がるのかというところの説明をしてほしいと求めました。","respondent":"三ツ橋国保医療年金課長","answer":"市町村を入れた部分を考えて、そのあたりを勘案してまいりますので、品川区は上がっております。追加して申し上げますと、医療費の伸びとともに被保険者数が下がってしまいますと、１人当たりの納付金が上がってしまうということになります。","id":"exchange-022"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"では、１人当たりの納付金額が５,０２９円減少したというのは、２３区には当てはまらないで、２３区としては１人当たりの納付金は上がっていると考えて、それ以外の市町村のほうで下がっていると考えるということなのか尋ねました。","respondent":"三ツ橋国保医療年金課長","answer":"私の手元にあります資料、これは２３区の資料なのですが、１人当たり納付金については３,７５４円上がっている資料となっております。","id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"意見","question":"やはり今の議論でもありましたように、それを区独自で判断してできるということにもなっていますので、ぜひ引き下げこそすべきだと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"}]},{"id":"topic-04","title":"第３１号議案、指定管理者の指定","agenda":"第３１号議案、指定管理者の指定","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"今までの委員会の中で指定管理自体は了解するものですけれども、この資料の中で、指定管理者候補者選定委員会が１月２３日に開催されて、今回の定例会の議案の最初のときに出ていなくて、追加議案で出てきたのですけれども、そこの理由だけ、説明をお願いします。","respondent":"飛田障害者施策推進担当課長","answer":"今回、愛成会から収支の疑義があり調整しており間に合わなかったため、議案の提出を一時保留させていただきました。","id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"意見","question":"細かい詰めというのは、最終的でしょうけれども、それ以前の段階でいろいろなお話がされていた中で、なぜかなと。そこら辺が、事業自体はいいのだけれども、何かすっきりしないところが、もうちょっと理解できればというところがあるのですけれどもとの意見を述べました。","respondent":"飛田障害者施策推進担当課長","answer":"重度障害などはさまざまなケースの対応のため、職員配置の人件費ですね、特にそこのところの見直しが必要となると考えております。愛成会としては品川区民の期待に応えるような事業を展開するということを確認しておりまして、今回、議案を提出させていただきました。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問","question":"調整はついたという判断というのですか、収支の必要性もあるでしょうから、それは大丈夫だということでお答えをいただいていいのか尋ねました。","respondent":"飛田障害者施策推進担当課長","answer":"指定管理料が決定したらそのまま継続して行うようで、このままの指定管理料が継続されるかという確認がありましたので、愛成会と詰めていって。そこで、一緒にやるということで、今回、議案を提出させていただいたということです。","id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ここで詰めたということでいいのでしょうけれども、その辺、しっかりとこれからも連携をとっていっていただきたいということで状況はわかりました。結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"提案","question":"それぞれの職員体制がどうなるのか、確保策や工夫点などについて提案してくださいというのがありますので、ここをお聞かせいただきたいです。教えてほしいと求めました。","respondent":"飛田障害者施策推進担当課長","answer":"資格としましては、保育士、また、児童指導員等が入りまして、こちらは正規の方が２名、準職員の方３名ほど配置する予定と聞いております。こちらも常勤１名と非常勤３名の配置予定だというふうに、今のところ、このような情報を得ております。","id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"質問","question":"今、品川の中でのお話をしていただいたのですけれども、品川だけではなくて、グローとゆうゆうと愛成会はほかでも法人としてやられていると思うのですが、法人全体としての離職率がわかれば伺いたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"平成２９年度、こちらはグローです、正規職員２２５名、採用数２４名、離職者数１３名で、離職率は５％となっております。そして平成３０年度、正規職員２３０名中、離職者７名で離職率は３％と聞いております。","id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問","question":"今はグローのだけですよね。ほかのゆうゆうと愛成会はどうか尋ねました。","respondent":"飛田障害者施策推進担当課長","answer":"すいません、今、手元にすぐ出る資料がないのですけれども、ゆうゆうも愛成会も大体グローと同じような感じというのは聞いておりまして、比較的安定した運営が図られていると感じております。","id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"質問","question":"法人が全体として離職率が高くないのかどうなのかというのをお聞きしたかったので、伺いました。この間、今日の資料では訪問系サービスはゆうゆうになっているのですが、変わったのですかということをお聞きしたいです。","respondent":"飛田障害者施策推進担当課長、石田（秀）委員長","answer":"今までも訪問系サービスを実施するのはゆうゆうというふうにご説明しておりますが……、資料を確認いたします……。 平成３０年１月の、これは私も見て覚えているけれども、就労継続支援Ｂ型２０人と訪問系サービスは愛成会となっている。レストランカフェ愛成会… すいません、これは真ん中に愛成会と来ていますが、これは就労継続支援Ｂ型が愛成会で、訪問系サービスがゆうゆうとなります。これは本当にミスです。","id":"exchange-032"},{"speaker":"石田（ち）委員","kind":"質問","question":"わかりました。指定特定相談支援事業所になっていくわけですけれども、児童のほうはどうなるのかというのを、グローがやられるのかというのを伺いたいです。","respondent":"飛田障害者施策推進担当課長","answer":"今の仮のところがそのまま移動して、こちらの事業に入るということになります。今後、児童のほうも含めまして、相談に対応をできればと考えております。","id":"exchange-033"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"総合支援施設の（１）から（５）までの中で、総勢で正規はどれぐらい、非常勤はどれぐらいというのがわかったら教えていただけたらと思います。それともう１つ、訪問系サービスがゆうゆうでされるということなのですけれども、これは本当に求められているところだと思うのです。","respondent":"飛田障害者施策推進担当課長、松山障害者福祉課長","answer":"今後、こういった事業所を少しでも多く増やすということは必要だと思いますので、今後の検討になるかと思います。まだ継続してやっていますので、今まさに検討しているところですので、決まり次第お知らせというふうに考えております。現在、当事者からのヒアリングや相談支援センターのご意見等を踏まえて、相談支援部会でまさに検討しています。","id":"exchange-034"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"既に運営している施設に従事する過去３年間の常勤・非常勤ごとの離職率を明記してください、そこに沿って多分この３法人が出されていると思うのです。出されている中身がわかれば教えていただければ、募集要領に書かれている中身がわかれば、教えていただけたらと思います。","respondent":"飛田障害者施策推進担当課長","answer":"すいません、今回、離職率の手持ちの資料、グローしか持ち合わせがなかったため、申しわけございません。ゆうゆうにしても、ほかの事業所に比べれば離職率は低いと認識しております。","id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"今後に向けて、そういう報告ができるようにというところで、よろしくお願いしたいと思います。そこら辺がどういう経過でこうなったのか、また、これが今後に向けてどうなっていくのかというあたりをお聞かせいただけたらと思いますとの意見を述べました。","respondent":"大串福祉計画課長","answer":"今回、委員会の資料ということで、選定委員会等でも使っていただきました指定申請者に係る説明資料をつけさせていただきました。今後、このスタイルを続けていくかどうかについては、まだこれからの検討となります。","id":"exchange-036"},{"speaker":"若林委員","kind":"質問","question":"そうだったんですかという問題では、昨年の１月２２日の議事録、さっき委員長からご提示があったＡ４の説明資料をもとに担当課長がご答弁されている。担当課長のご答弁も皆さん了解しているわけですので、先ほどの担当課長のご答弁に何か訂正があれば、おっしゃってほしいと求めました。","respondent":"永尾福祉部長","answer":"今、平成３０年１月２２日の資料の件についてのご質問がございました。そこについては大変申しわけなかったと考えていますけれども、担当課長もそういう説明をしておりますので、その当時と現在とでは変更はございません。","id":"exchange-037"},{"speaker":"若林委員","kind":"意見","question":"例えば２階の就労継続支援Ｂ型と訪問系サービスに愛成会と書いてありますと。１つ１つ、失敗がありましたというのを重ねるのはあまりよくないのかなと思ったので、もう１回……との意見を述べました。","respondent":"飛田障害者施策推進担当課長","answer":"確かに当時、そういうところで検討していたため、そのような答弁となりました。訪問系サービスはゆうゆうが行うということで、よろしくお願いいたします。","id":"exchange-038"}]},{"id":"topic-05","title":"平成３１年請願第６号、国保料引下げと子どもの国保料無料化を求める請願","agenda":"平成３１年請願第６号、国保料引下げと子どもの国保料無料化を求める請願","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この請願は、先ほども条例審査したところでは、所得の比較的低い多子世帯には値上げという重くのしかかる負担増になったわけです。共産党としても求めてきているのですけれども、私は一般質問でも取り上げさせていただきましたが、区としての考えを改めて伺いたいと思います。","respondent":"三ツ橋国保医療年金課長","answer":"区独自の子どもの均等割無料化につきましては、その負担をさらに一般財源で賄うこととなり、非常に困難と考えております。","id":"exchange-039"},{"speaker":"石田（ち）委員","kind":"質問","question":"一般財源から入れていくのは非常に困難というのは、この間も一般質問のところでありましたけれども、公平性の観点から見ても国保の子どもの均等割に一般財源を入れるのは困難だという、その公平性の観点というのは、何なのかを伺いたいと思います。","respondent":"三ツ橋国保医療年金課長","answer":"ほかの被用者保険の方の財源も入っておりますので、公平性の観点から、一般財源から賄うことは非常に困難と考えております。区といたしましては、引き続き特別区長会および全国知事会を通じて、国に求めてまいります。","id":"exchange-040"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それが公平性なのではないかと思うのですけれども、区としてはいかがでしょうか。国に求めていくということなのですけれども、国には要望するけれども区の財源は入れられないという、そこも説明を求めました。","respondent":"三ツ橋国保医療年金課長","answer":"引き続き求めてまいります。国保料で賄えなかった部分、例えば収納率の部分ですけれども、そこにつきましては一般財源から投入しています。","id":"exchange-041"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"国が国保法をつくって国保を国民皆保険にしていくと進めていますが、国保料を軽減させていくというところは区も求めているわけではないですか。なので、子どもの国保料を無料にしていくというところについては、区としては国に求めていくという姿勢なのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この間、２３区で差し押さえ率２位という状況だったと思うのですけれども、平成２９年と平成３０年の差し押さえ件数を伺いたいと思います。封筒の色の検討はされたかどうか、伺いたいと思います。","respondent":"三ツ橋国保医療年金課長","answer":"平成３０年度は、直近ですが、２１０件です。引き続き封筒の色につきましては工夫してまいります。","id":"exchange-043"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"減った理由を伺いたいのと、封筒の色は工夫していくということですけれども、これはすごく区の姿勢が出るなと思うのです。工夫をされているのはいいのですが、あの真っ赤な封筒はやめていただきたいなと思いますけれども、いかがか尋ねました。","respondent":"三ツ橋国保医療年金課長","answer":"差し押さえ件数が減った理由といたしましては、まだ年度途中ということもありますけれども、個々により丁寧に応じているという考え方です。封筒の色につきましては、ほかのお知らせなどとは異なる趣旨のものなので、目立つようにしております。","id":"exchange-044"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"差し押さえを何件やったら３,０００万円とか、これがなくなったのか、なくなってきた経緯がわかれば教えてほしいと求めました。","respondent":"三ツ橋国保医療年金課長","answer":"国の保険者努力支援制度がございまして、ひとつ、大きく挙げられておりました。区から差し押さえ件数によって交付しないようにという要望は特に上げられていないという認識です。","id":"exchange-045"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"生活困窮や突然の病気、そういったところに個々に応じていくことで、生活再建をしていける対応にぜひ大きく変えていただきたいなと。欲しいといった方には直ちに交付していただきたいなと思いますけれども、最後、いかがか尋ねました。","respondent":"三ツ橋国保医療年金課長","answer":"国民皆保険制度という相互扶助の考え方に基づき、この制度が維持・継続できるよう、事務の執行に当たってはさまざまな取り組みをしてまいります。引き続き、国保の財政基盤安定化のために取り組んでまいります。","id":"exchange-046"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"真っ赤な封筒は今でも続けているのか、やめたのか、また目立つ封筒の工夫で違う色になったのか。やめてほしいというのは、それはぜひやめていただきたいと思っているのですけれども、説明を求めました。","respondent":"三ツ橋国保医療年金課長","answer":"封筒の色につきましては、その都度、工夫しているところでございまして、今でもという部分につきましては、必要に応じて考えておりますので、ほかのお知らせなどとは異なる趣旨のものとして対応しております。","id":"exchange-047"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"では、本当におどすような色だと私なんかは感じるような真っ赤な封筒なのですけれども、目立つということではこれからも使い続けていくということはあり得るのか、その点はいかがか尋ねました。","respondent":"三ツ橋国保医療年金課長","answer":"封筒の色につきましては、ほかのお知らせなどとは異なる趣旨のものですので、目立つようにしてまいります。今後検討してまいりますので、今、はっきりと明確にお伝えすることはいたしません。","id":"exchange-048"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"本当にもらったときにびっくりして、どきっとする色なので、ぜひやめていただきたいということを強く要望しておきたいと思います。それから、国保というのはそもそも国保に入っている人の保険料で賄うべき、そういうふうに考えられているということなのか尋ねました。","respondent":"三ツ橋国保医療年金課長","answer":"全員の方が自主納付をされているのであれば収納率は１００％となりますので、国保に入っている方の保険料で賄っていけると考えております。その考えに基づいてお伝えした部分です。","id":"exchange-049"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"国保の保険料と税金の投入という、そこのあり方として、税金は投入しないで国保料だけで全部国保を賄っていくべきと考えられているのか。国保料と税金のそこのところの考え方をとの意見を述べました。","respondent":"三ツ橋国保医療年金課長","answer":"したがいまして、私が申し上げましたのは、原則自主納付という考え方に基づいて伝えている部分ですので、税金からの投入は依然としています。","id":"exchange-050"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"だけど、今、課長からのご答弁はそういうふうなことで確認をさせていただいてよろしいでしょうか。だから、今回の子どもの均等割の無料化は、この決算補填等目的の法定外繰入には当たらないということは確認させていただいていいですよね。","respondent":"三ツ橋国保医療年金課長","answer":"軽減の部分でございまして、決算補填等目的以外の法定外繰入金ですけれども、そちらに関しましては減額という部分だと認識しております。財源の確保につきましても、国庫負担金の引き上げを国に対して要望してまいります。","id":"exchange-051"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私が伺ったのは、決算補填等目的の法定外繰入という、国が求める削減すべき法定外繰入には、子どもの保険料減免は当たらないということで確認させていただいていいかと、このことを伺ったのです。","respondent":"三ツ橋国保医療年金課長","answer":"それはやはりできない、法に抵触する可能性があると言われた場合には、それは区としてできないものと考えております。","id":"exchange-052"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"解消すべき法定外繰入金には当たらないと。この確認を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"解消すべき法定外繰入ではないということで、そこのところの確認をしたいということなのですけれども。","respondent":"三ツ橋国保医療年金課長","answer":"この部分に関しましては、区といたしましては、保険者政策等と考えておりますため、決算補填等目的の法定外繰入金に含まれるものと考えております。","id":"exchange-054"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"区の考え方として、保険料の減免額に当てるということをお考えはないのですというのであれば、それで納得いくのです。今、ありませんと言うのだったら、そういうことなのかということなのですとの意見を述べました。","respondent":"三ツ橋国保医療年金課長","answer":"減免の部分ですけれども、区といたしましては、子どもの均等割軽減の無料化には当てない、当たらないと考えております。","id":"exchange-055"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"既に１０分の１ぐらいになってしまっているわけですから、３０億円ぐらい減らしてきているわけですから、財源は十分あるわけです。そういうことで、ぜひご検討いただきたいということで、強く要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"若林委員","kind":"質問・要望","question":"結論を出すで、不採択です。各種の低所得の方も含めた対策をしっかりと丁寧に行っていただきたいという意見を添えまして、不採択で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"石田（ち）委員","kind":"提案","question":"１人当たりの国保料は、協会けんぽの１.３倍、組合健保の１.７倍と、同じ医療保険の中でも著しく重い負担を強いる不公平な制度になっています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"}]},{"id":"topic-06","title":"平成３１年請願第７号、特養ホームと老健施設の増設を求める請願","agenda":"平成３１年請願第７号、特養ホームと老健施設の増設を求める請願","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ここで求められているのは特養ホームと老健施設ということですけれども、この間、地域密着型で進めていくという検討がされているというところです。林試の森公園隣の公有地にできる特養の定員数を増やすという形で今から検討し直すことは可能なのか尋ねました。","respondent":"大串福祉計画課長","answer":"地域ニーズの高いものもあわせてというところで、今、検討しているものです。それ以外にも、児童の施設、保育園であったり、あるいは障害者の施設、こういったものもあわせて検討しています。","id":"exchange-059"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"こうした特養ホームの増設等を求める請願というのは、ほかの議員の方の質問で、今後は地域密着型を中心に進めていくという方針を区は持たれているということなのか尋ねました。","respondent":"大串福祉計画課長","answer":"地域包括ケアといった観点からも、やはり今住んでいらっしゃる近隣にそういった施設を多くつくっていくべきではないかと考えているところです。大規模な１００人規模の特養をどんというところではなく、こういった地域密着型の施設を多くつくっていきたいと考えているところです。","id":"exchange-060"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"林試の森公園の隣は大きな土地なので、大きな土地が出てこないというのは、都心にある品川だけの問題ではないかなと思うのです。下の請願項目にもあるように、それを出せる形にしていただきたいなと思うのですが、そこはいかがか尋ねました。","respondent":"大串福祉計画課長","answer":"そうしたことに応えていくためにも、一定の施設の整備は必要だと認識しています。施設のあり方あるいはそれ以外のソフト支援のあり方、品川区の高齢者施策、高齢者福祉の充実を図っていきたいと考えているところです。","id":"exchange-061"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"サービス提供量なんかを見ても、これも数字で見える形にすると、品川区は２３区で最低レベルなのです。今、これを整備計画として出していただきたいと思うのですけれども、最後にいかがか尋ねました。","respondent":"大串福祉計画課長","answer":"住みなれた我が家でというのを一番の大きな目標とはしておりますけれども、やはりそうした中での施設のあり方も一定必要なものと認識しております。","id":"exchange-062"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"その地域密着ということで、特養ホームも地域密着であれば、何平米ぐらいだったらできるのでしょうか。どんどん地域密着の２９ベッド程度の、ほかのところとも合築になるのかもしれないのですけれども、そういう考え方だということでいいのか尋ねました。","respondent":"大串福祉計画課長","answer":"そのときの区民の皆さんのニーズに対応するという形になりますので、必ずしも、何ともというところかと思います。それに応じた形で施設の整備、また、有効的な活用の仕方については検討していきたいと考えています。","id":"exchange-063"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私が伺ったのは、いろいろな施設の要望、区民の要望というのはさまざまあると思うのですね。だから、計画を持って増設をしていくことが必要なのではないかということなのですけれども、そこのところについてお聞かせほしいと求めました。","respondent":"大串福祉計画課長","answer":"特養という施設の重要性、必要性は認識しています。こちらのほうでは認識していますので、総合的な判断といった言葉になってまいりますけれども、政策的に考えていくべきものと考えています。","id":"exchange-064"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これがもっともっと高齢者はどんどん増えていくわけですから、その点についてもどう考えておられるのかということをお聞かせいただきたいのと。そういう状況というのはどう考えられますか尋ねました。","respondent":"大串福祉計画課長","answer":"後段で出されたようなケース、本当に難しいところかなと考えています。そういった中で、どういった対応ができるのかというのは、こちらのほうでもご相談しながらといったところになろうかと思います。","id":"exchange-065"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"整備率が最下位というのは、何とか脱する計画というのを私は持つべきなのではないかなと思うのです。そこもあわせていかがか尋ねました。","respondent":"大串福祉計画課長","answer":"さまざまな形で施設の整備も行ってまいりますし、また、ソフトの展開といったところでもさまざまな施策を展開していきたいと考えているところです。","id":"exchange-066"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうところで言えば、品川の財政から言えば、５００人の待機者をゼロにするということは、できないことではないと思うのです。待機者ゼロにという増設計画をつくって、増設していただきたいということを強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"鈴木（真）委員","kind":"質問","question":"理由としては、理事者の説明もありましたけれども、さまざまな形で推進を図っているというのは大前提であります。例えば1)の林試の森というところで見ると、この内容として受けるわけにはいかないと思いますので、不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"若林委員","kind":"意見","question":"結論を出すで、不採択で結構だと思います。引き続き、林試の森公園の特養ホーム等の高齢者の施設充実をしっかりお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-069"},{"speaker":"石田（ち）委員","kind":"意見","question":"要介護３から申し込みという制限をされている中でも、５００人以上が待機されているという状況で、それを一気に解消できない状況ではないと思います。ですので、待機者ゼロを目指して、２３区で最低の整備率を脱する整備計画をつくるべきだと思いますので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-070"}]},{"id":"topic-07","title":"健康増進法の改正および東京都受動喫煙防止条例の制定","agenda":"健康増進法の改正および東京都受動喫煙防止条例の制定","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"陳情の中で条例の早期制定に関する陳情とありますけれども、区として条例化というのは、今、説明に入っていましたか。その辺はまだ答えはないのか尋ねました。","respondent":"川島健康課長","answer":"都条例と改正法の説明のみで、区の考え方等はお話ししてございませんでした。条例を制定して何かやっていくという必要がないものですので、法と、それから都条例に基づきまして適切に事務を行っていくように準備をしています。","id":"exchange-071"},{"speaker":"石田（ち）委員","kind":"質問","question":"約２割の方が喫煙されているという状況で、喫煙者を少なくしていくための取り組みというのは、評価していく立場なのでしょうか。喫煙率は下がっていくわけですので、年齢別には統計はとられていないか、伺いたいと思います。","respondent":"川島健康課長","answer":"その辺ももう少し区民の皆さんにお知らせを強化するですとか、いろいろとそういった取り組みを総合的にやっていく必要があると考えております。４０、５０代ぐらいがピークになって、下がっていくという形になっております。","id":"exchange-072"},{"speaker":"石田（ち）委員","kind":"質問","question":"その３カ所は、明日、総務委員会で報告されるということなのですけれども、今ここでは教えていただけるのでしょうか。やっぱり受動喫煙防止という観点からは、どこに設置されるのかなというのは気になるところなので、ぜひ伺えたら伺いたいと思います。","respondent":"川島健康課長","answer":"正式には明日の総務委員会の報告を待っていただければと思いますが、今、聞いているところですと、議会棟と第３庁舎の間の部分と、それから第２庁舎の駐車場の階段脇の部分、それから第３庁舎の６階、講堂のある階のテラス部分と聞いてあります。","id":"exchange-073"},{"speaker":"石田（ち）委員","kind":"質問","question":"そういったところでは、品川区内のコンビニの前とか駅の近くとか、そうしたところを区として規制できるというものはつくらないのか。必要なのではないかなと思うのですが、いかがか尋ねました。","respondent":"川島健康課長","answer":"健康課の職員など、それから地域活動課の生活安全担当のほうで対応させていただいているのですけれども、職員が行ってお願いをしているところです。","id":"exchange-074"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、加熱式たばこというのは、ここではどうなっているのでしょうか。伺いたいと思います。","respondent":"川島健康課長","answer":"国の考え方ですけれども、今後の研究や調査を継続していくことが必要ということで、罰則の適用にはなっていないということです。確かに規制が少し緩くなっているですので、国は、健康影響については科学的知見の蓄積を行っていきますと言っているところです。","id":"exchange-075"},{"speaker":"芹澤委員","kind":"確認","question":"確認で、場合によっては改善の支援とかをしていくことになると思うのですが、そこのすみ分けをこれからどういうふうにされるのかという考えだけ伺えればと思います。","respondent":"川島健康課長","answer":"それから、関係者は相互に連携しながら取り組んでいくことになっております。先ほど言った管理権原者の支援ですとか啓発、特別区、それから保健所設置市区が行うものというつくりになってあります。","id":"exchange-076"},{"speaker":"芹澤委員","kind":"確認","question":"すいません、もう１回だけ確認で、総合的・効果的にというお話は、都の責務でも書いてあるけれども、基本的に区市町村に権限がおりてきているので、メインは区が持っていると考えてよろしいか尋ねました。","respondent":"川島健康課長","answer":"委員のおっしゃるとおり、実働部隊というか、現場に一番近いところでいろいろな取り組みを実施するという規定になってあります。","id":"exchange-077"},{"speaker":"鈴木（真）委員","kind":"意見","question":"そうすると、例えば、受託事務は通常都の財源で入ってくるけれども、こういう人がかかったようなケースの場合の財源はどうなってくるか。所管が違う部分になってしまうかもしれないけれどもとの意見を述べました。","respondent":"川島健康課長","answer":"交付税措置をされると言われておりますので、特別区に限ってはあまり実入りがないというか、そういうような説明を聞いてあります。算定をして、仕事の中身が決まって、いろいろと仕事がおりてくるような形になると聞いてあります。","id":"exchange-078"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"財調算定にしていくのかどうか、そこら辺も頭に入れておいて調整してもらったらいいのではないかなという、これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"「区有施設の対応」について伺いたいのですけれども、（２）に、それ以外のところで喫煙室を撤去していくというのはどういう施設が考えられるのか。出口のところでみんなが吸っているといった感じになっていると思うのですけれども、ああいうのは今後どうなっていくのか尋ねました。","respondent":"川島健康課長","answer":"多分第一種施設、行政機関の事務を取り扱う施設という分類になるだろうというところで、７月１日までに対応をとる必要があるのではないかです。第一種施設の施行日が７月１日と迫っているということで、適切な対応をしていく必要があるです。","id":"exchange-080"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"わかりました。中学校ぐらいになるのですかね、そこら辺の健康課と教育委員会との連携がどうなっているのかについて、説明を求めました。","respondent":"川島健康課長","answer":"その仕事の中で、普及啓発含めて、どうしていくかというところは大事なところだと考えているところです。","id":"exchange-081"},{"speaker":"鈴木（真）委員","kind":"質問","question":"それから陳情の第６号、第７号、第８号に関しては、継続でお願いします。もう少しどうとるかということもあったので、会派として結論を出さないで継続でということで判断させていただきましたので、お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"若林委員","kind":"意見","question":"陳情第６号、第７号、第８号については、継続でお願いします。しっかりと推移を見守りながら、今後さらに何か手だてが必要なのかどうかも含めて、継続して見守ってまいりたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-083"},{"speaker":"石田（ち）委員","kind":"意見","question":"第７号、今から規制をしていくべきだということなども入れながら、さらに規制をしていくという修正案を出しています。第６号、第７号、第８号は不採択ということで主張しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-084"},{"speaker":"木村委員","kind":"意見","question":"第５号は結論を出すということで、これは不採択でお願いします。そして、第６号、第７号、第８号は継続という形でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-085"}]},{"id":"topic-08","title":"平成３１年陳情第３号、東五反田事件について相談支援の対応に問題がなかったか検証を求める陳情","agenda":"平成３１年陳情第３号、東五反田事件について相談支援の対応に問題がなかったか検証を求める陳情","exchanges":[{"speaker":"石田（ち）委員","kind":"提案","question":"そして障害者のいる家族を孤立させないように対応を求めるということですけれども、これはなぜ報告されなかったのでしょうか。わかれば教えていただきたいのと、福祉サービスを利用するよう提案したのは、どこが提案したのかとの意見を述べました。","respondent":"松山障害者福祉課長","answer":"こちらの方は報道されており、個人情報の部分にかなり当たることになりますので、あまり詳細な実態を申し上げることができません。ここに書かれている記事のところでお伝えしたいと考えています。","id":"exchange-086"},{"speaker":"石田（ち）委員","kind":"提案","question":"厚生委員会でも報告がされてもおかしくはないのではないかなと思うのですけれども、なぜ報告をしなかったのか、伺えたらと思います。福祉サービスを利用するように提案したけれども拒否をされている、こういうことが、答えられる範囲でお答えいただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-087"},{"speaker":"石田（ち）委員","kind":"質問","question":"区がどういうふうにして対応するのか、区としてはどういうふうに対応するのかという形でだったら、お答えいただけるということでいいでしょうか。障害者福祉の窓口に相談に来た場合に、どういった場合に相談支援センターにつなげるのかを伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"その支援の中で、共有のもと、どういう方向性で支援していくかというのを模索していくということになろうかと思います。こういった方の場合、見守りながら支援を継続していく、その状況を把握していくというのが通例です。","id":"exchange-088"},{"speaker":"石田（ち）委員","kind":"提案","question":"もっとこうしてほしいとか、次々というか、提案をしていくというふうになるのか。拒否された場合の対応はどうされているのか尋ねました。","respondent":"松山障害者福祉課長","answer":"拒否された場合の対応についてですが、拒否をされる背景にはさまざまな理由があります。そういった配慮ができるようなスキルの向上を目指して、研修などを通じて、努めてまいります。","id":"exchange-089"},{"speaker":"石田（ち）委員","kind":"質問","question":"わかりました。大体どんなスパンで訪問なりされているのか、ケース・バイ・ケースだと思いますけれども、わかれば説明を求めました。","respondent":"松山障害者福祉課長","answer":"例えば相談支援センターが訪問するのがいい場合もありますし、この対応をすればよかったというものは、難しいと思います。日々、日常的に見守りを継続しながら、そして方向性を見定めながら支援を繰り返していくというのが実態です。","id":"exchange-090"},{"speaker":"石田（ち）委員","kind":"質問","question":"いろいろな専門職が集まって、ケース検討会議みたいな場というのは、区の中にそういう仕組があるのか。どんな場合にそういったケース会議が開かれるのか、あれば伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"区の中の仕組みというか、日常的に既に行っているものです。やはりスピードを持って対応しなければならない事例や、継続的に見守り、支援が必要な事例につきましては、定期的に行っております。","id":"exchange-091"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、日常的に行っているというケース会議は、どうなるとケース会議につながるというのはあるのですか。ケース会議にいくまでの経緯があるのか、伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"相談支援センターからの提案もありますし、区から相談支援センターに呼びかけてという両方あります。できるだけスピードアップして、緊急で集まるというケースもありますし、ケース・バイ・ケースになっています。","id":"exchange-092"},{"speaker":"こんの委員","kind":"質問","question":"あるいはどういったサービスが必要なのか、ご家族、ご本人に寄り添った形で進めていくということをされていると伺いました。その点はどういう形で今は行われていて、いろいろな人とチームで情報共有をするけれども、そこら辺の相談体制はどうなっているのか尋ねました。","respondent":"松山障害者福祉課長","answer":"必ずそこが主になって、ただ、やはり医療的な面については保健師の力をおかりしながら動くという状況です。ただ、その中で中心になって足りないところをメンバーとして活用していくというところのチーム体制が必要だと思っています。","id":"exchange-093"},{"speaker":"こんの委員","kind":"確認","question":"一部分かかわってくださった方の感覚というのでしょうか、そこは非常に難しいところなのだけれども、そこが非常に必要だなと思うのです。それもまたどうかなと思うので、そこら辺をどうされていくのかというのがもう１点確認と、そこら辺はどんなふうに考えますか尋ねました。","respondent":"松山障害者福祉課長","answer":"お互いに共有しながら、相談員も自分の対応を振り返るということは常日ごろからやっておりますので、課題だと考えています。障害者を抱えるご家族の支援も必要なことだと考えていますので、今後、どういう支援が必要かという視点というのは非常に重要だと考えていますので。","id":"exchange-094"},{"speaker":"こんの委員","kind":"質問・要望","question":"最初の第一歩の窓口の職員の方、どうかそういったところもあわせて大変と思いますけれども、そこはお願いしたいと思います。今もしてくださっていますが、さらにお願いしたいなと、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そこから何を教訓にして、二度としない対策をどうとっていくのかというのが、現場で仕事する者が一番学ばなければいけない部分だと思うのです。どういう対応をとるべきだったか検証したいということで話しているにもかかわらず、そういう点では、その理由をお聞かせほしいと求めました。","respondent":"松山障害者福祉課長","answer":"繰り返しになりますけれども、２０１５年当時、課内では対応状況を振り返り、議論はしたと聞いております。ただし、その話した内容、議論の内容については、検証結果として文書は作成していないと聞いております。","id":"exchange-096"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"これだけのことですから、これだけの事件が起こりながら、教訓にされなかった。職員に対してこれを教訓としてまとめて、みんなの意識の中で共有するという作業はされなかったのか、その点についても説明を求めました。","respondent":"松山障害者福祉課長","answer":"この事例のみを検証して、この対応をすればいいというのは、非常に難しいかと考えています。日々、そこからステップアップしていくものというのは、相談支援員たちも課内の職員も常日ごろから研さんを積んでいるところです。","id":"exchange-097"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"なぜこういうことが起こったのか、ひとつひとつのその時々にしていく、それでみんなの中で共有していくという作業がすごく大事だと思うのです。こういう陳情が出されたということを受けて、ぜひともやっていっていただきたいと思うのですけれども、その点ではいかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"支援ができるような体制づくりを具体的にするように、力を入れて、相談支援センターあるいは課内の職員と情報共有しながら検討しています。あるいは相談支援のマニュアルも含めて、具体的に包括的な支援体制の構築に向けて、検討しています。","id":"exchange-098"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"では、区民の皆さんがさまざまな困難を抱える中で、大変な状況というのはこれからも皆さん抱えられていくことになっていくと思うのですね。寄り添って、大事にならないような対応の体制を構築できるようにということで、ぜひよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-099"},{"speaker":"若林委員","kind":"確認","question":"一度も議会で取り上げられることもなくと陳情者の言葉が書いてあるのですけれども、この陳情の内容の事例は、議会に報告する事柄だったのか。２０１５年当時の仕組み、今の取り決めの中でお聞きしたいのと、どのようになされているのかなというのを確認したいと求めました。","respondent":"松山障害者福祉課長","answer":"なので、報告の仕方として、どのような報告が適切だったのかというのは、議会と相談しながらがよろしいかと思います。相談支援体制ということで、普遍的なことをご審議いただくということであれば、議会への報告というのは必要なことだったかなと考えています。","id":"exchange-100"},{"speaker":"若林委員","kind":"質問","question":"そうすると、この陳情の事例は極めて個別の事例なので、今、陳情者はこういうふうにおっしゃっているけれども、行政側としては、これは委員会に挙げる報告には当たらないだろうという判断だというご答弁だったという認識でよろしいか尋ねました。","respondent":"松山障害者福祉課長","answer":"報道に取り上げられているようなことも考えますと、ひとつひとつ、真摯に相談をしていきたいと考えています。","id":"exchange-101"},{"speaker":"若林委員","kind":"質問・要望","question":"４年後、それは要望というか、終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-102"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"事件と言っていいのか、この件は、確かにニュースになっていたというのは記憶にあります。どう取り上げるかは別にして、考え方として、趣旨採択ということにさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"},{"speaker":"若林委員","kind":"質問・要望","question":"結論を出すで、趣旨採択に値するかなと考えています。拡充、充実、課題があれば解消に向けて取り組んでいただきたいという趣旨です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-104"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今からでもわかる範囲でやっていただきたいですし、後々も共有していけるものに、そして教訓にしていくべきではないかなと思います。どういうサービス、地域で自立した生活を送れるのかというのをさらに充実させていっていただきたいなという思いからも、私たちは採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-105"},{"speaker":"木村委員","kind":"意見","question":"本当に人の命がかかった大変大事な、品川区の事件というか、出来事だったと思います。もし自分がその立場だったらどうなるのかなということを考えると、こういうことが二度と起こらないように、趣旨採択でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-106"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/312511?Template=document&Id=3530#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":78446,"voices":313}},{"id":"r01-20190225-8","meetingId":"r01-cm02","date":"2019年2月25日","dateIso":"2019-02-25","committee":"建設委員会","time":"午前１０時００分～午後 ４時４７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を124件整理しています。","topics":[{"id":"topic-01","title":"の第２２号議案 品川区手数料条例の一部を改正する条例","agenda":"の第２２号議案 品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それと、改正3)ですけれども、こちらは適用される地域はどのような地域でしょうか。区内で言えば、どこが該当して、将来の拡大などはあるのかないのか伺います。","respondent":"長尾建築課長","answer":"１枚目の資料の1)番、住んでいる方に対して、計画内容を説明するための説明会を行いますという通知をまず事前にポスティング等で配布いたします。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"改正1)と2)ですけれども、目的ということで伺ったのですが、そこだけ聞きたいのでお答えほしいと求めました。それと、例えば保育園に一部転用した場合などで、今回の規制緩和ということで安全性が低くなってしまうということはないのか伺います。","respondent":"長尾建築課長","answer":"先ほどご説明したとおり、用途変更したい部分以外についても、用途変更がやりやすくなるというところをねらっているものと思います。すぐさま保育園等を用途変更の建物に入れる際に、安全面で心配が出てくるというふうなことにはならないような運用を区としても検討しております。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"改正の5)、6)のほうですが、以前の内容と比較してどのような緩和になるのかということを改めてご説明いただきたいというのが１点目です。政令ですとか省令が出ていないということなのですが、今定例会にこういった手数料条例を上程する区の理由、それも伺いたいと思います。","respondent":"長尾建築課長","answer":"今回、手数料条例の改正を出させていただいたことにつきましては、改正法の施行予定が本年６月２６日までの間になっております。それまでに政・省令ができる予定にはなると思いますが、今回は手続が政省令の施行日に間に合うようにというところで、今回の日程で出しています。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"わかりました。改正4)のところでお伺いしたのですけれども、こういった改正4)のような現行の規制があるということで、そこだけ最後にお伺いします。","respondent":"長尾建築課長","answer":"実績といいますか、事前のご相談等につきましては、こちらについては特にまだないので、あとは、そういった実例といいますか、そういった実態があるというところは、現時点では情報としては把握しておりません。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問・要望","question":"確認をさせていただきたいのですが、2)のところの用途規制のところで、先ほど、コンビニエンスストア、第一種低層住居専用地域で２件とおっしゃったのは、昨年度、今年度と、それぞれ年間で２件あったということか尋ねました。","respondent":"長尾建築課長","answer":"事例として２件ほどあると申しましたのは、第一種低層住居専用地域の中でコンビニエンスストアをつくる場合というわけではなくて、この法律の４８条の許可にかかわるものということで、２件ほど、直近の二、三年の間であったように記憶しております。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１個増えて、１３種類あると思うのですが、そこら辺のイメージとして教えてほしいと求めました。","respondent":"長尾建築課長","answer":"建てようとすると、必ず今までですと、この許可を受けてからではないと建てられませんでした。そういった意味では、この許可手続であったり、建築確認は必要がないということです。","id":"exchange-006"},{"speaker":"あくつ委員","kind":"意見","question":"実際のコンビニエンスストアとか、自動車修理工場であるとか、学校給食センターはそもそも品川区にはないのかと思うのですが、国レベルで法改正という中で定めるということですので、品川区ではおそらく適用例はないのかと思いつつ、法の趣旨は理解いたしましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"大沢委員","kind":"質問","question":"別表２－１の改正の内容というところで、1)、2)、3)も全て合理化ということですけれども、合理化によって改正の内容の中で申請のながれという図表がありますけれども、合理化することによって、どのぐらいの期間が短縮できるのか、おわかりになったら説明を求めました。","respondent":"長尾建築課長","answer":"1)番、2)番の公開意見聴取の手続に必要となる期間としましては、おおむね１カ月半から２カ月程度あります。ですので、そういった期間が短縮されるという効果があります。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"公園のほうの占用料以外の部分は、必要な改定かと思います。大体どのような方が負担しているのか、その割合がわかれば、道路と法定外公共物および公園それぞれについて伺えればと思います。","respondent":"今井土木管理課長","answer":"割合については、件数、金額ともそちらの義務的占用と申すものがほとんど９割近くを占めるものと思います。ただ、メインは占用企業者といわれる事業者です。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問・要望","question":"品川区の資産価値が果たして下がっているのかどうか、１５.４％で平均よりも上がっているというように聞こえたのですけれども、そこについて確認をさせてほしいと求めました。","respondent":"今井土木管理課長","answer":"こちらは地方税ですが、市町村長が決めるものですが、東京都の特別区では都知事が近隣の路線価をもとに決定していくものです。平成２７年から平均いたしますと、１５.５％、評価額が上がっているというふうなデータを持っております。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"意見","question":"人を惑わすような、そういう人心をあおるような、不安に陥れることはやはり避けたほうがいいのではないのかという感想をもちましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"横山委員","kind":"質問","question":"２の(1)の建築面積の割合の中で、建築面積の割合を上限５％とする改正を行うということで、この下の３つの公園ということなのでしょうか。その辺を詳しく教えていただけたらと思います。","respondent":"溝口公園課長","answer":"その中で１,０００m2未満の公園につきましては、今、現状の男女別々のトイレだけを設置するのでぎりぎりの状態になっているところです。今後さらなるバリアフリー化を考えますと、だれでもトイレの設置をしていかなければいけないと考えております。","id":"exchange-012"},{"speaker":"大沢委員","kind":"質問","question":"第２５号議案関係資料のほうで、つまり、条例の目的のところですけれども、「公園の健全な発達」というのは、これは何を言っているのか尋ねました。","respondent":"溝口公園課長","answer":"今回、公園条例につきましては、１つは、公園施設の設置の関係もありますし、今後の公園をどのように管理していくのか。遊び、１つの表現として「公園の健全な発達を図り」というところで、条例の目的に書かせていただいているところです。","id":"exchange-013"},{"speaker":"大沢委員","kind":"質問","question":"先ほど来、課長が、だれでもトイレを設置する、この部分では、だれでもトイレ、またはトイレの改修ということは具体的なものとして上がっているというような認識でいいのか尋ねました。","respondent":"溝口公園課長","answer":"身障者だけでなく、お子様連れのご家族が利用できる、利用しやすいトイレというものができてくるというふうに考えております。そういったことも受けながら、公園改修をしっかり進めていきたい、そういった思いで今回の条例改正を提案するところです。","id":"exchange-014"},{"speaker":"大沢委員","kind":"質問","question":"では、ここの条例の目的として、公園の健全な発達というのは、先ほどおっしゃったようなだれでもトイレ等々の誰でも使いやすいような設備を設置するということが主眼になっているというふうな認識でよろしゅうありますか尋ねました。","respondent":"溝口公園課長","answer":"委員ご指摘のとおり、誰もが利用しやすいような施設にしていく、そういったところが目的ということになっておりますので、そのようにご理解していただければと考えています。","id":"exchange-015"},{"speaker":"筒井委員","kind":"質問","question":"占用料の改定で、基本的に全体的に上がるようなことになっているかと思うのですけれども、こうした占用料の改定については、やはりこれまでも品川区は行政としては固定資産税の評価額が変わって、上昇した場合はやはり占用料も全体的に上げていくということが慣例なのか尋ねました。","respondent":"今井土木管理課長","answer":"やはり２３区全体で検討する必要があるということで、この占用料の額の決定につきましては、２３区の特別区の課長会で種々協議しております。ですので、今後も、先ほど申しましたとおり、区民の方の負担を適正に確認した上で占用料を決定していく形になります。","id":"exchange-016"},{"speaker":"筒井委員","kind":"質問","question":"今、全体的に上がっているふうに見受けられるのですけれども、それは個別の項目については上げないとか、そういったことで決めているのか尋ねました。","respondent":"今井土木管理課長","answer":"個別のところについては上げないということは、道路占用料については、この条例上では行っておりません。２m2以下の場合には道路占用料については免除ということになっておりますので、免除基準などを活用して区民の皆さんの負担を軽減しています。","id":"exchange-017"},{"speaker":"筒井委員","kind":"質問","question":"なぜこういった質問をさせていただいたかというと、据え置きなりすることはできるのかなどと思ったのですけれども、その点はいかがお考えなのか尋ねました。","respondent":"今井土木管理課長","answer":"例えば共催事業などの場合には、先ほど申しました公園ロケーション料、または写真撮影料が免除になる場合もあります。占用料のところでの免除規定ではなくて、あくまでも文化観光課がフィルムコミッション事業の中で確認したものに対してということになっております。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"どのように対応、解決しているのか伺いたいと思います。航空機の低空飛行による低周波音の影響を区はどのように考えているのか伺います。","respondent":"小林環境課長","answer":"対応方法としましては、その音が我々が持っていく測定器で低周波音かどうかを判断できる機械を持っておりますので、それを測定して確認をしています。","id":"exchange-019"},{"speaker":"安藤委員","kind":"確認","question":"そういう対応をしていると思うのですけれども、航空機からの低周波音はどれくらい出ているのかというのは区は把握しておられますでしょうか。その出席者数の中に地域外の方はきちんと入っているのかお伺いします。","respondent":"小林環境課長、鈴木都市計画課長","answer":"区としても同じ考えです。ジェット機単体で低周波音の把握についてはなかなか困難であるというふうに認識しています。 地域への説明会に出席された方の人数ですが、先ほど、６３３人というところでご説明差し上げましたが、その中に地域外の区民の方の人数も含まれているというようなところです。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"１日の低周波音の合計時間量、１年間の低周波の合計時間量について説明をしてくださいとありますが、その把握についてはいかがということが１点。この請願項目の５番にあるような、そこら辺は私は国に求めていく必要があると思うのですけれども、いかがか尋ねました。","respondent":"小林環境課長","answer":"それらとあわせて、引き続き、区としてもしっかり国が責任を持って検証して、その結果を丁寧に説明するものだろうというふうに考えてあります。","id":"exchange-021"},{"speaker":"安藤委員","kind":"提案","question":"品川区としても国にさまざまな、この新ルートに対する影響の中の１つの大事な観点だと思いますので、ぜひ求めていってほしいと求めました。あるいは代表質問でも提案させていただきましたけれども、区は、住民の意向の確認なしに回答をするつもりなのか尋ねました。","respondent":"鈴木都市計画課長","answer":"教室型説明会がようやく昨年末から行われてきているというところで、１３地区全てにおいて説明会を実施していただくように求めてきたわけですが。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"私が伺ったのは、住民の意向は別に関係ないという、そういう立場なのでしょうか。伺います。","respondent":"鈴木都市計画課長","answer":"そうした説明会、多様な手法を活用した説明会、説明手法をお願いしていますので。今、そこをしっかり見据えながら、国にこうした理解を深めるための取り組みをさらに進めていただきたいです。","id":"exchange-023"},{"speaker":"安藤委員","kind":"確認","question":"まず確認するということをなぜやらないのか、区民投票の実施とアンケートの実施は、これはやっぱり請願でも出されています。こういう意向の調査、実施、区民投票、こういったものはやるべきだと思うのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"教室型説明会という形で、地域のほうに説明していただいているというところでございまして、区民の方に直接しっかりご説明していただいて。行われているわけですので、その中でしっかり答え、あるいは理解を深めていただく取り組みをしていただくというのが区の考えです。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"やはり区民がこの計画に対してどういう判断をするのか、思いを持っているのかということを、区として把握すべきだと言っているのです。区がやらない理由といいますか、それは何なのかお伺いします。","respondent":"鈴木都市計画課長","answer":"区民の方の不安、あるいはご疑念に対して回答すべきは、これはもう間違いなく国です。そうした意味では、今その取り組みが進められているわけですから、区がそれにかわって何かを行うということではございません。","id":"exchange-025"},{"speaker":"安藤委員","kind":"確認","question":"区民の意向が無視されて、品川区として住民意向を確認する何らかの、請願ではアンケートと書いています。そうしたことを確認することすらしないというのは、一体品川区はどういう考えなのか、もう一度伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"ご疑念に答える、そういった声も説明会では出ているということは、私も同席しておりますので承知しています。そうした声に今後もこの教室型説明会、そうした中で回答していっていただくというところは、全く考えてございません。","id":"exchange-026"},{"speaker":"安藤委員","kind":"確認","question":"まさに国が住民の意向を無視して、住民の意向すら確認しないというのは、私は本当に民主主義を何だと考えているのかというふうに思わざるを得ません。私ばかりしゃべってもあれなので、一旦やめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問・要望","question":"その３時間、４５デシベルを上回る音、区として健康被害についての実態調査などを国に対して求めるお考えはあるのでしょうか。国に対してしっかり健康被害についてどう考えているのかを求めていっていただきたいのですけれども、その点、いかがお考えか尋ねました。","respondent":"小林環境課長","answer":"非常に個人差があって、まだまだ研究段階であるというところは、いろいろなところで言われているところです。今、一定研究が進められている中ですので、もうしばらくその辺の動向を注視しながら必要な対策を求めていきたいというふうに考えているところです。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問・要望","question":"非常に大変なことになると考えておりますので、後々になって後悔しないように、これはしっかり国に対して求めていっていただきたいと考えております。区としても国に対して要望をしてほしいのですけれども、その点、いかがお考えなのか尋ねました。","respondent":"鈴木都市計画課長","answer":"教室型説明会のマスコミへの公開といいますか、取材の対応ですが、１回目の説明会の打ち合わせの当時から国には申し入れてきたところです。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひこれを求めていただいて、気になるのは、それに対して国の回答だと思います。それに対する国の回答をぜひ聞いてきてほしいのですけれども、その点、いかがお考えか尋ねました。","respondent":"鈴木都市計画課長","answer":"マスコミについては、ちょっと嫌だとか、そういった声もあるのは事実です。今ご紹介いただいたエリア分けをするとか、そういったところも含めて、国のほうにはしっかり伝えていきたいです。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"その状況も当然国土交通省の職員の方もとらえて、そうした圧倒的多数の参加区民の反対という状況を受けて、国はどう考えているのでしょうか。区として、そうした質問をしたことはあるのか尋ねました。","respondent":"鈴木都市計画課長","answer":"その中でおおむね１０名程度の方から質問をいただいて国が答えるという形で行われてきてありますが、あるいは、先ほどご紹介しましたように。あるいは、さまざまな別の機会も捉えてですが、国のほうには求めてきているというようなところです。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問・要望","question":"国はそうした区民の反対の声を聞いて、どう考えているのかということを知りたいので、何か国土交通省の職員の方など国側の意見は聞いているのか。聞いていましたら、ぜひそれを教えていただきたいのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"その場でも国は答えていますが、やはり今、この整備が完了しないうちは実機を飛ばすことができないという回答です。具体的に区がこれまで要望してきた取り組みにかかわるようなところについては、さらに掘り下げて国のほうにはお願いをしてきているです。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問・要望","question":"先ほど課長も求められているとおっしゃっていましたけれども、区民がどう思っているのか、賛否両論あると思います。区は求めているとおっしゃられましたけれども、国はそれに対してどう回答されているのか、ご存じでしたら説明を求めました。","respondent":"鈴木都市計画課長","answer":"国がアンケートの実施に対してどう答えているかですが、説明会の中で区民の方からそうした要望も上がってあります。それに対しての国の回答は、東京都あるいは自治体のほうと協議しながら検討していくという回答です。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問・要望","question":"教室型説明会実現ということに至ったわけですから、教室型説明会の実現に続いて、ぜひ国のアンケートをやっていただきたいと考えております。アンケートが実施されない、区民の賛否がわからないまま羽田新飛行ルートが強行された場合、これに区としてどう対応していくのか説明を求めました。","respondent":"鈴木都市計画課長","answer":"現在、全地域での教室型説明会も含めたさまざまな手法での丁寧な地域への周知を図っていただきたいとお願いしてきているところです。今後も説明会を通して、地域住民の理解を深めていただく取り組みを国に求めていくというのが区の今現在の方針というか、取り組みの姿勢です。","id":"exchange-034"},{"speaker":"筒井委員","kind":"質問・要望","question":"教室型説明会実現に続いて、国のアンケート実施をぜひやってほしいと求めましたので、ぜひ国のアンケートを求めていってほしいと求めました。改めて国のアンケート実施について、どうお考えなのか……。","respondent":"鈴木都市計画課長","answer":"区の求めに対して区民への丁寧な説明を国が進めていく中で、地域の理解をどう得たかというところにつきましては、これは事業主体である国が責任を持って考えて実施していっていただきたいというところが、区の今のスタンスです。","id":"exchange-035"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２点ほど確認をさせてほしいと求めました。今は新ルートを飛んでいない状況で、航空機の低周波音被害について区民の方から訴えがあったのか、そこの事実関係を確認したいと求めました。","respondent":"小林環境課長","answer":"昨年と今年あった実績の中身ですが、把握する限りでは、特に多かったのが室外機からの音についてです。","id":"exchange-036"},{"speaker":"あくつ委員","kind":"質問","question":"身近に存在しているとあるのですが、国の法律等においては、規制基準等は設けられていないということです。これから品川区で国が計画をしているような３時間どころか、当然私も伺っているのですが、何かそういうことがあったのかどうか説明を求めました。","respondent":"小林環境課長","answer":"それぞれ我々のほうでも国とか関係自治体に確認していますが、いわゆる低周波音が原因で健康被害があったという事例は、把握している限りではないというところが回答です。","id":"exchange-037"},{"speaker":"あくつ委員","kind":"質問・要望","question":"確認だけさせていただきました。さまざまなニュースレターみたいなものも出ているのですけれども、そういうものの中に反映をされていくのかどうかお聞かせほしいと求めました。","respondent":"鈴木都市計画課長","answer":"実施されてきております教室型説明会の議事録等ですが、国の回答といたしましては、先ほどご紹介いただいたニュースレターも含めて検討していきたいというところの回答はいただいております。","id":"exchange-038"},{"speaker":"安藤委員","kind":"確認","question":"地元の理解の確認のところなのですけれども、住民のこの計画に対する理解の確認がないままに、それに向けての都の連絡会が行われるわけですね。住民の理解が確認がないままに、この連絡会が開かれる、品川区が態度を問われるということになってもいいと考えているのか伺います。","respondent":"鈴木都市計画課長","answer":"まだ実施についての通知ですとか、どういう目的で、どういうことを協議するために開くといったところは全く現時点では連絡が来ていないところです。今、今後も落下物、騒音対策も含めた取り組みをしっかり国のほうに求めていきたいです。","id":"exchange-039"},{"speaker":"安藤委員","kind":"確認","question":"私が伺ったのは、住民の理解の確認なく連絡会が開かれますけれども、品川区はそれでいいのですか。賛否を表明しないという黙認、イコールそれは容認だと思いますけれども、そういったことも含めて態度表明するのか伺います。","respondent":"鈴木都市計画課長","answer":"国は教室型説明会を含めた説明会を今後やっていくですので、そうした意味での答弁をさせていただいたところです。仮定の話ではお答えできないといいますか、理解を深めるための取り組みをしていただいているというところでご答弁差し上げたところです。","id":"exchange-040"},{"speaker":"安藤委員","kind":"質問","question":"品川区としては、そこの態度表明に品川区民の、住民のこの計画に対する賛否の度合いを全く考慮することなく態度表明をするということなのでしょうか。それを当然、そこの場で代表として態度表明すべきだということが当然だと思うのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"実施時期が、国が設置する協議会に反映させるということは明記されておりますが、まだ何ら全く示されていないというような状況です。区としての考えを、対応方針について、区としてはしっかりお伝えするということは当然考えてあります。","id":"exchange-041"},{"speaker":"安藤委員","kind":"質問・要望","question":"２０１８年１０月のガイドライン改訂で示された生じるおそれがあるという健康被害ですけれども、具体的に何を差しているのか伺いたいと思います。今回の新ルート下における品川区は、上回っている地域が生じるのか、Ｌｄｅｎ４５以上になるところは生じる地域があるのかどうか伺いたいと思います。","respondent":"小林環境課長","answer":"航空機だけのところを捉えて概要をご説明しますと、いらいら感等のところを評価したというところで、その中身の大きなところかと捉えてあります。区内でＬｄｅｎ４５の範囲はどうかということにつきましては、区としては把握しているところではございません。","id":"exchange-042"},{"speaker":"安藤委員","kind":"確認","question":"２０秒継続する最大騒音のレベル８５デシベルの騒音が毎晩発生しても、これまでの基準は、技術的事由によって基準値が緩和されていた経緯があります。伺いますけれども、Ｌｄｅｎ４５を上回る地域が品川区に生じるのですかということは伺ったのか、確認したいと思います。","respondent":"小林環境課長","answer":"説明会でも話がありましたように、今後、どういったことができるのかというところを取りまとめている最中です。引き続き、動向につきましては、国から情報をしっかり得ていくことが今の段階では必要だと思ってあります。","id":"exchange-043"},{"speaker":"安藤委員","kind":"質問","question":"今回の新ルートにとってどうなのかということを、区民の健康を一体どう考えるのかと思うのですけれども、これはすぐわかるものなのではないですか。伺います。","respondent":"小林環境課長","answer":"Ｌｄｅｎ４５が区内にどういうふうに広がるかというところにつきましては、実際、私どもが直接、区の職員が分析するわけでもございませんので、どれだけの作業が必要で、どれだけ時間がかかるかということにつきましては、区としてはお答えすることはできないと思ってあります。","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこら辺は強く、Ｌｄｅｎ４５の影響がどうなのかということを国に出すよう求めてほしいと求めました。私は、そういう説明会にしていくということを区が宣言して国に出席を求めるやり方を求めますけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"この教室型説明会の実施に当たっては、長い時間、区で国に強く求めていった中でようやく実現した取り組みです。継続して国には求めているですので、あと５地区残っておりますが、継続して国には求めていきたいというところが区の考えです。","id":"exchange-045"},{"speaker":"安藤委員","kind":"質問","question":"ですから、伺いたいのは、計画を進める国土交通省の側の都合でマスコミをシャットアウトという方針になってしまったのでしょうか。そういうふうに私は思うのですけれども、率直にいかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"やはり国がこの計画を説明して、それに回答するという場所ですので、何らマスコミの方が入っていただけない理由は見当たらないです。その対応を国に求めてまいりますし、あわせて教室型説明会の様子の公表、継続して求めてまいるです。","id":"exchange-046"},{"speaker":"安藤委員","kind":"質問・要望","question":"複数回の説明会の開催も求めてはいるのですけれども、マスコミの対応は確かに参加をためらうという方もいるということなのでしょうから。ぜひ多くの方が参加ができて、そして判断ができるような、そういうものに資するようなものにしていただくために頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"筒井委員","kind":"質問・要望","question":"この羽田新飛行ルートの関係で、港区は羽田新飛行ルートと不動産価値との因果関係の調査を国へ要請するということなのですけれども、不動産価値との因果関係の調査をぜひ品川区も港区に続いて国へ要請していただきたいのですけれども、その点、いかがお考えか尋ねました。","respondent":"鈴木都市計画課長","answer":"さまざまな取り組みの中の１つとして国に求めていきたい、そういった声が地域の不安の声としてあるということも説明会では出ておりますので、そうした対応をとれるかどうかも含めて。","id":"exchange-048"},{"speaker":"筒井委員","kind":"質問・要望","question":"代替案を国に対して迫って、ほかにも道があるということをぜひ行っていただきたいと考えておりますが、いかがでしょうか。研究課題とおっしゃったので、今後どうされるのかお伺いいたします。","respondent":"鈴木都市計画課長","answer":"その検討、検討会が設置されて、国のほうには申し上げていきたいです。","id":"exchange-049"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひ積極的に代替案を示して見直しを求めていく、今お話のあったとおり、ルートの見直しを積極的に求めていっていただきたいと考えております。羽田新飛行ルートの固定化だけはぜひ避けていただきたいので、その点も踏まえて、今後もぜひよろしくお願い申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"大沢委員","kind":"確認","question":"委員長、お願いですけれども、７件ということで、もう１回確認で、７件、審査事項で(1)、(2)と振ってありますけれども、どことどことどこ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"安藤委員","kind":"質問","question":"このまま継続にすると、自動的に廃案になりますので、これは議会の責任としてどうなのでしょうか。態度の是非はあるにしても、結論は絶対に出すべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"}]},{"id":"topic-02","title":"平成３０年請願第２１号 都営地下鉄中延駅（東中延２丁目口）のエレベーターなどの設置に向け、品川区が東京都と連携して取り組むことを求める請願","agenda":"平成３０年請願第２１号 都営地下鉄中延駅（東中延２丁目口）のエレベーターなどの設置に向け、品川区が東京都と連携して取り組むことを求める請願","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"こういった具体的な要望が出たということで、一定、委員会でも審議をされまして、その後何か東京都とこの件について進捗があれば伺いたいと思います。費用負担の割合といいますか、品川区と東京都はどれくらいずつになるのか、わかれば教えていただきたい。","respondent":"鈴木都市計画課長","answer":"昨年の１２月以降、東京都に伺いまして、この中延駅のエレベーター設置について、協議といいますか、話を伺ってまいりました。設置した場合の費用負担ですが、基本的には区のほうで鉄道事業者に対するエレベーターの設置助成がありますが、東京都の事業になりますので。","id":"exchange-053"},{"speaker":"安藤委員","kind":"質問","question":"それ以降、協議、話を伺ってきたということですが、その内容についてはどのような感じで、東京都のお考えがどういうふうに示されたのか伺います。","respondent":"鈴木都市計画課長","answer":"設置については、都の所有の土地が非常に狭いということで、なかなか技術的に難しいというところでございました。冒頭ご説明しました、今検討いただいている中で、ぜひ上位に位置づけていただくような申し入れは口頭では行ってきた次第です。","id":"exchange-054"},{"speaker":"安藤委員","kind":"質問・要望","question":"なので、ぜひ繰り返し東京都との協議の連携を進めてほしいと求めました。都市計画道路の計画線に入っていないところが狭いという意味なのか、そこら辺がどういう話になったのかならなかったのか伺います。","respondent":"鈴木都市計画課長","answer":"区としての認識、あるいは東京都の認識、その場での私が感じた認識としましては。","id":"exchange-055"},{"speaker":"安藤委員","kind":"提案","question":"前回提案させていただいたのですけれども、Ａ３出口のところに、１人だけ通れるようなエスカレーター設置は十分可能です。そういったことについて、品川区として検討していただきたいのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"エスカレーターの設置につきましては、やはり朝のラッシュ時は、現状よりも流れが阻害される部分が側面的にはあるのかです。今後、複数化について検討していくですから、さらにどういった方向が具体的にとれるのかというところを検討していただけるように。","id":"exchange-056"},{"speaker":"安藤委員","kind":"質問・要望","question":"住民に最も身近な自治体として、ぜひそういったいろいろな方面から研究を重ねていただいて、東京都と具体化へ向けて連携してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"あくつ委員","kind":"意見","question":"先ほど、質疑の中でやりとりをしていただいたことがありました。そういう中でのいろいろなバランスを考えたときに、今回は継続としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"},{"speaker":"安藤委員","kind":"意見","question":"本日、結論を出して、採択を主張したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"松永副委員長","kind":"意見","question":"継続でお願いいたします。利用客もＡ３出口に関しましては８割を超えておりということですので、この件に関しましては、継続でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"筒井委員","kind":"意見","question":"東京都の「経営計画２０１９」に今後の取り組みを位置づけることや、また、ほかの出口を設置するということも、予算的に非常に苦しいかもしれませんが、あり得るかと思いまして、こうした経緯をしばらく見守っていきたいということで、継続でお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-061"},{"speaker":"安藤委員","kind":"質問・要望","question":"行きたい場所といいますか、行きたいのだけれども不便で行かれない場所はどこですかということで伺いましたところ、これは圧倒的ではあります。どういうふうに区民の直接的な要望をこういった会議体に反映させていくお考えなのかということと絡めてご説明をほしいと求めました。","respondent":"鈴木都市計画課長","answer":"平成２６年に地域交通検討会を設置しまして、こちらの検討会議体につきましては、いろいろ資料をお示しして議論をいただいてきたです。この検討会議体の中で、そういったものを加えながら、しっかりと議論していただく整理をつけながら進めていきたいです。","id":"exchange-062"},{"speaker":"安藤委員","kind":"質問・要望","question":"そして、そういう区民の行きたい場所の要望、なかなか行きづらいところの要望はアンケートでしっかり項目として聞く必要があると思うのですけれども。３点目として、住民または利用者の代表ということで３名なのですが、こちらはどういった方が参加しているのか説明を求めました。","respondent":"鈴木都市計画課長","answer":"アンケートを実施するわけですから、そういったところを計画の中に反映していくというところは、これは基本的なところかというふうに考えてあります。地域交通検討会の住民または利用者の代表につきましては、あと、観光協会の方というところで入っていただいているところです。","id":"exchange-063"},{"speaker":"安藤委員","kind":"質問・要望","question":"地域も偏らずに全区的にそういった要望はあると思いますので、きちんと意見を伺うというような、そういうものにしてほしいと求めました。より多様な意見が反映されると思うのですけれども、そういったことをぜひお願いしたいのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"地域の声の反映の仕方の１つとして、やはり地域の公募区民という考え方は１つあろうかと思います。入っていただかないで、何か違う方法で進めるのか等を含めて、しっかり検討していきたいです。","id":"exchange-064"},{"speaker":"あくつ委員","kind":"質問・要望","question":"コミュニティバスと言うかどうかは別にして、ほかの地域がどういう形で、できましたら建設委員会等でご報告をいただきたいというところ。そういう情報提供を議会のほうにもぜひお願いしたいと思いますが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"検討はご説明しました会議体で進めてまいりますが、議会、委員会のほうにも適宜、その委員会開催ごと以外にも必要なお出しすべき情報についてはしっかりお示ししながら検討を進めてまいりたいと思います。","id":"exchange-065"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２０２０年度は実施計画、そして２０２１年度は運行準備、早くても２年後というようなことになるのでしょうか。区民の期待がかなり大きいものですから、そこのところのお願いをさせてほしいと求めましたが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"いろいろ実施に当たって、検討から、導入までどれくらいかかるかというところを事前に今のうちから調査を開始していますが。具体的な検討はこれからですので、検討を重ねて、一刻も早い実施に向けて検討していきたいです。","id":"exchange-066"},{"speaker":"筒井委員","kind":"質問","question":"以前にも課長がコミュニティバス導入に当たって、ルートは既存の業者に配慮した形になるようなことをお話しされていましたけれども、料金もやはり今、既存の業者の方たちに対して配慮されていくのか、そのあたり、どういうふうにお考えになっているのか、現時点でわかる範囲で説明を求めました。","respondent":"鈴木都市計画課長","answer":"重複しない形で検討するようにしなさい、義務ではないのですけれども、そういう方向で検討するようにということは受けてあります。今の利用実態、民間の料金設定実態を当然ながら参考あるいは検討の題材にしますが、そういうところで具体的に示されているものではございません。","id":"exchange-067"},{"speaker":"筒井委員","kind":"質問・要望","question":"引き続きこの委員会でそうした情報を適宜出していただくよう、私からもお願いを申し上げて、これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"大沢委員","kind":"意見","question":"そもそもこれはどういう、それとも福祉の向上を目指すのか、どちらに重きを置いたらよいと考えますかとの意見を述べました。","respondent":"鈴木都市計画課長","answer":"この会議体でいろいろ議論した中で検討を進めていくことになろうかと思いますが、やはり１つは、区内の地域公共交通は非常に高い利便性がありますが。","id":"exchange-069"},{"speaker":"大沢委員","kind":"質問","question":"要は、警察等々も含めて交通不可のところもより福祉的要素をかもし出すために、そこら辺もいじって議論に加えていくということでいいのか尋ねました。","respondent":"中村都市環境部長","answer":"先ほど、そういった方も含めて、区民の皆様に広く利用していただくような方法でまずは検討するという具合に考えてあります。というのも、こういったものなくしてコミュニティバスは存在しないと考えておりますので、現状の道路規制の中で極力走らせていくべきと考えています。","id":"exchange-070"},{"speaker":"筒井委員","kind":"質問","question":"ルートのことですけれども、今後、開通予定の２６号線は、まだ開通していないわけですから、当然、既存の業者が走っていないわけですけれども、２６号線は、やはりコミュニティバスのルートの有力候補ということで、そういったお考えはあるのか尋ねました。","respondent":"鈴木都市計画課長","answer":"検討を進めていく中では、検討していくのかというところも含めて、検討の中には開通という方向性は１つの材料としてしっかり組み入れて検討していきたいと思います。","id":"exchange-071"},{"speaker":"安藤委員","kind":"意見","question":"２件一括して結論を出すべきだと思います。私たちは採択を主張しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-072"}]},{"id":"topic-03","title":"平成３１年請願第２号 再開発高層マンション・ビルへの補助金の見直しを求める請願","agenda":"平成３１年請願第２号 再開発高層マンション・ビルへの補助金の見直しを求める請願","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"震度６を超える大地震のときに、たしか東京は震度５強というところで、何か区がわかる情報があれば説明を求めました。","respondent":"稲田都市開発課長","answer":"震度６程度の地震の際に耐えられるような構造強度を持った建物として、その基準を守っておりますので、そういった実証が得られるような状況にはなっております。","id":"exchange-073"},{"speaker":"あくつ委員","kind":"確認","question":"横揺れが非常に大きくなる、これは映像でも私も見ましたけれども、それをもって実証されていないというのはなかなか難しいなというのが感想です。おそらくそれはさまざまな実験を繰り返して実証されていると言ってもいいのかとは思うのですけれども、そこのところを確認をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"安藤委員","kind":"質問","question":"質問ですが、１７条の住民説明会の前の段階で、行政はどのような把握をしているのか伺いたいと思います。それが２点目です。","respondent":"稲田都市開発課長","answer":"１７条の説明とか、事業計画を２週間、資金計画が入っております。設計計画費が幾らとか、そういうことが書いてありまして、それは一般の方に縦覧しています。","id":"exchange-075"},{"speaker":"安藤委員","kind":"質問","question":"先ほどの２番目の質問は、補助金は幾らなのですかと聞かれても、補助金の金額は明らかにされない場合が多いのです。私が伺ったのは、ビルを建てる事業費をどうやってまかなうかという資金計画を把握していないのですか、どのように把握しているのかと伺ったので。","respondent":"稲田都市開発課長","answer":"説明会のときに、補助金が幾らというのは、それはまだ正式に決まっていないというか、正式な形での算出がされていないです。組合設立、事業認可前のそこで明らかになるということですので、その辺での公表はしていないです。","id":"exchange-076"},{"speaker":"安藤委員","kind":"質問","question":"景観、駅混雑等のデメリットは、区はどう考えているのでしょうか。私たちとは見解が違うかもしれませんけれども、これは区はどう考えているか、これでいいと思っているのか伺います。","respondent":"稲田都市開発課長","answer":"風とか、日照とか、その他の面につきましてですが、先ほどもご説明いたしましたように、計画段階でいろいろと検討してきております。","id":"exchange-077"},{"speaker":"安藤委員","kind":"質問","question":"この問題、どう解決していこうと考えているのか、そういった問題を考えないでぼんぼん建てて、行政としていいのかという点を１点お伺いしたい。超高層ビルは防災に強いとお考えなのかどうか、弱いというお考えなのか、伺います。","respondent":"稲田都市開発課長","answer":"非常用発電、自家発電といいますか、そういうものが７２時間の対応ができるというようなところもあります。周辺から逃げ込む人たちにも対応でき、また、防災上には非常に強いというふうに考えております。","id":"exchange-078"},{"speaker":"安藤委員","kind":"質問","question":"そこら辺についてのお考えを伺いたい。地権者の合意など得られるわけがないわけですから、そこをわかっているかどうか、なぜ区民に説明しないのか伺いたいと思います。","respondent":"稲田都市開発課長","answer":"地域の方々が地区の問題点、地域の問題点等を考えながら話し合いを進めてきて、再開発事業という手法でやっていこうということでやっていくものです。そこで公告・縦覧をするというところで、私どもはそこでの公表というふうに考えております。","id":"exchange-079"},{"speaker":"安藤委員","kind":"質問・要望","question":"課題そのものもどうかということがあるのですが、しかし、その課題の解決となぜ超高層がセットなのですか。私はできると思いますし、そこにこそ力を出すべき、知恵を出すべきだと思うのですけれども、いかがか尋ねました。","respondent":"稲田都市開発課長","answer":"そういう中で、市街地再開発事業が最適だろうというところで、地域の皆様もそうやって検討してくるです。そういう中で市街地再開発事業の手法を選びながら、品川区のまちづくりをしっかりしていこうですので、超高層ありきというところではございません。","id":"exchange-080"},{"speaker":"安藤委員","kind":"意見","question":"さまざまな課題を抱えながら、しかも、そういった過程も頑なに情報公開も拒否されるということであれば許されないと思います。私は、こういったまちづくりを見直す、補助金も見直すというこの請願は、そのとおりだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-081"},{"speaker":"筒井委員","kind":"確認","question":"補助金の支出の割合ということについてお聞きしたいのですけれども、区は自由に補助金額を決めることができるのかということを確認として伺いたいのですけれども、それについてご説明をお願いします。","respondent":"稲田都市開発課長","answer":"その補助対象事業費を１と考えれば、３分の１を組合が持つ、３分の１を区が持つ、３分の１を国、国費で持つというような割合になっております。要綱とか、そういうものに従いながら、予算の内側の中でいろいろと決めていくです。","id":"exchange-082"},{"speaker":"筒井委員","kind":"質問","question":"３分の１という数字がありましたけれども、３分の１が補助金の上限というような理解でよろしいのかということと、この請願にあるとおり、廃止、要は、０円ということですけれども、０円にするというようなことも可能なのか尋ねました。","respondent":"稲田都市開発課長","answer":"３分の１というお話なのですけれども、それはまた検討の中で、精査をしながらやっていく。品川シーサイドは市街地再開発事業の中でも個人施工ということで補助金は入っておりません。","id":"exchange-083"},{"speaker":"筒井委員","kind":"確認","question":"補助金の額が、２週間の縦覧期間を過ぎた後でも、区民は事業収支の結果とか補助金額を見ようと思えば見られるのか。予算書等々、先ほど出ましたけれども、区民は後から事業収支計画、補助金額を確認することができるのか、それについて説明を求めました。","respondent":"稲田都市開発課長","answer":"基本的にこの２週間の間で、私どもの窓口に来られる方には見られるのですけれども、この後となりますと、それをもって東京都に提出して事業認可されるですので、東京都のほうへの文書公開等の手続になるかとは思いますが、そういうところで見られるです。","id":"exchange-084"},{"speaker":"筒井委員","kind":"質問・要望","question":"なるべく、税金も入っていることですから、今後行うときは積極的に公開の姿勢を行っていっていただきたいと考えています。どういうふうにお考えになっているか、２点、お聞かせできればと思います。","respondent":"稲田都市開発課長","answer":"これは私どものまちの活力や活性化、賑わい、そういうものにおいて非常に重要なものだというふうに考えております。私どもは、そういう個々の課題の解決をしながら、まちの活力を高めていこうというスタンスでやっているところです。","id":"exchange-085"},{"speaker":"筒井委員","kind":"意見","question":"２点目の居住者の高齢化によって大規模修繕等がかなりできにくくなるのではないかということについて、区はどう対策を考えられているのかとの意見を述べました。","respondent":"稲田都市開発課長、森住宅課長","answer":"マンションの管理業務というのは非常に難しいですけれども、私ども、再開発組合から管理組合への引き継ぎがあります。修繕費、もちろんそういうところのプロも入ってやっておりますので… 今、東京都のほうでも適正な管理の促進に関する条例案が出されているところでございまして、区としても適正な管理を進めてまいりたいと。","id":"exchange-086"},{"speaker":"大沢委員","kind":"質問・要望","question":"２つ伺いますけれども、１つは、東京都が認可するということがありました。公表しているという事実に基づけば公表しているわけですから、そこのところの確認。","respondent":"稲田都市開発課長","answer":"事業認可を受ける際に２週間、縦覧するということになっておりますので、それをもって公表しているというふうに考えております。それから２番目、このことに関しましては、何とも言えないところです。","id":"exchange-087"},{"speaker":"あくつ委員","kind":"質問","question":"９１億円の利益をデベロッパーが得るのではないかという、今、そもそも比較すること自体がナンセンスではないのかというのが１つ。品川区のほうに指摘があるのか、また、今までそういったことでの指摘があった例が近年あるのかどうか説明を求めました。","respondent":"稲田都市開発課長","answer":"今までそういうことはございません。何重にもチェックしながら、都とも協議しながら、いろいろと法、要綱等に従いながらやってきているものでございまして、現在のところはございません。","id":"exchange-088"},{"speaker":"安藤委員","kind":"質問","question":"そういったことで１部屋大体平均価格は売り出し価格が出ていますので、それを掛けたところで売り上げがわかります。根拠は一定あるということで、一応、紹介します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"},{"speaker":"あくつ委員","kind":"意見","question":"当然、専門家が入らなければ、なかなか進まないという現実があります。これを果たすことはなかなかできませんので、現実性から考えても、この請願に対しては不採択としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-090"},{"speaker":"安藤委員","kind":"意見","question":"相談とか、あるいは説明会などに参加する中では、そういった実感もあります。こういった事業を見直すべきだと私は思っておりますので、採択を主張したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-091"},{"speaker":"松永副委員長","kind":"意見","question":"補助金についても、国の要綱に基づいた金額を支出されていると説明がありました。住環境につきましても、法令の基準に基づいて設計されていることから、この請願第２号に関しましては、不採択としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-092"}]},{"id":"topic-04","title":"平成３１年請願第３号 国の方針に従い補助２９号線の見直しを求める請願","agenda":"平成３１年請願第３号 国の方針に従い補助２９号線の見直しを求める請願","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"かなり上位のほうにランクインをされていたということは記憶をしているのですが、ここについて品川区が何か情報をお持ちでしたら、改めて説明を求めました。","respondent":"高梨木密整備推進課長","answer":"平成３０年２月に東京都より公表されました地域危険度調査、第８回の結果をお知らせいたします。これが危険度４、建物の倒壊危険度等を合わせた総合危険度が最高ランクの５、このような決定になっております。","id":"exchange-093"},{"speaker":"あくつ委員","kind":"質問・要望","question":"確認ですけれども、特定整備路線補助２９号線の見直しを要望されているのですが、先ほどあったような背景でこれを今進めているという認識でよろしいか尋ねました。","respondent":"高梨木密整備推進課長","answer":"区といたしましても、平成２１年度からまちづくり協議会を地域の皆様と組織して、防災まちづくりについての話し合いを進めている地域です。そして、特定整備路線も含めて、防災性の向上に関する施策が必要な地域という認識です。","id":"exchange-094"},{"speaker":"安藤委員","kind":"質問","question":"そもそもですが、この木造密集地域という言葉があるのですけれども、大崎などでもよく関連事業がありますけれども、どういう定義で、何をもって木造密集地域というふうにされるのか、改めて伺います。","respondent":"高梨木密整備推進課長","answer":"区では、先ほどもご紹介させていただきました東京都が作成しております防災都市づくり推進計画上の整備地域もしくはそれよりさらに防災性の向上が見込まれる重点整備地域といわれるものがございまして、改善が必要である木造住宅密集地域であるという認識です。","id":"exchange-095"},{"speaker":"安藤委員","kind":"質問・要望","question":"もう少し、例えばこういう指標がどうだとか、こういう数字がどうだとか、そういったところがもしわかれば教えてほしいと求めました。それと、補助２９号線というのは、西大井三丁目に直接かかっているわけではないと思うのですけれども、そこら辺はどうか尋ねました。","respondent":"高梨木密整備推進課長","answer":"その１つの要素といたしまして、あと、地区内の木造住宅等の棟数などを勘案して指定されているものです。","id":"exchange-096"},{"speaker":"安藤委員","kind":"質問・要望","question":"こちらは２９号線計画があるところの住民の実感としては、そこら辺の危険度はどうなのか、改めて教えてください。一体どうなのですかということを要望しても、こういった実態、東京都がこういうことすら出していないということはご存じだったのかどうか伺います。","respondent":"高梨木密整備推進課長、鈴木都市計画課長","answer":"私からは、西大井四丁目の件についてお知らせをします。火災危険度が４、災害時活動困難度が３、それらを合わせた総合危険度が４という結果になっております。区としても、大崎あるいは西大井付近で、計画道路と周辺の市街地の高低差として出てくるというところまでの認識は当然持ってあります。","id":"exchange-097"},{"speaker":"安藤委員","kind":"質問","question":"ですから、品川区が手を挙げて東京都につくるべきだということで進んでいる事業なわけですから、早く出せということは強く言ってほしいと思います。区はどのようにお考えなのか、この１点だけとっても、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"都と連携をして、区民の方が設計を進める中で求める情報は、あるいは区のほうでも相談に乗りながら進められているというような理解です。防災性の向上に資するものとして必要だというところで区は認識しておりまして、東京都と連携して、防災性の向上に取り組んでいきたいです。","id":"exchange-098"},{"speaker":"安藤委員","kind":"質問","question":"４割と減っているところもあるわけですから、しかもその補償がどうなるかという問題もありますし、私は間違っていると思います。飛び火の問題、風が０ｍだったということを、それでも延焼遮断というふうに区はおっしゃるのかどうか伺いたいと思います。","respondent":"高梨木密整備推進課長","answer":"地震と、無風のときも、請願の中にあります個々の建物を火災に強い構造にしていただくことは基本的に非常に大事なことだなという認識でおります。それぞれの木密地域の中で防災生活道路等でも取り組みを行わせてもらっていますけれども、一定の延焼遮断効果が得られる。","id":"exchange-099"},{"speaker":"安藤委員","kind":"質問","question":"飛び火の問題は現実の問題として糸魚川でこのように示されたわけですから、飛び火について、どのように考えますか。それでも延焼遮断とおっしゃるのか尋ねました。","respondent":"高梨木密整備推進課長","answer":"それと、そこの道を通って避難ができる、緊急車両が通行できるといったような道路整備は必要である、このように考えております。それぞれの建物の不燃化、耐震化といったところを複合的に行うことが防災性の向上には必要だと、このように考えております。","id":"exchange-100"},{"speaker":"安藤委員","kind":"質問","question":"防災対策の考え方、軸足の置き方を大きく転換してほしいと思います。やはり住民の声も聞きながら見直すべきだし、区の受けとめ、お考えをお伺いします。","respondent":"鈴木都市計画課長","answer":"一方で、それ以外、優先的に整備を進めていかないところについても、今、都市計画道路のあり方検討の中で議論が進められているところです。そうした検討の中で、今、整備が進められているです。","id":"exchange-101"},{"speaker":"安藤委員","kind":"質問","question":"私が伺ったのは、東京都だけでなくて埼玉のほうでは、最も身近な基礎自治体でも見直しをかけたりしているのです。ですから、品川区の受けとめを伺ったので、もう一度お願いします。","respondent":"鈴木都市計画課長","answer":"そうした道路を区が独自に、近隣区あるいは東京都全体の枠組みを外して区だけが単独で検討していくというようなことは基本的にございません。","id":"exchange-102"},{"speaker":"大沢委員","kind":"質問","question":"国土交通省ですから、ここには廃止は２路線しかないということですけれども、それだけ東京都の中においては道路を整備をしなければいけない。その中で平成２３年に東日本大震災が起こったことによって、道路の重要性、その土地によって運用の仕方は違うということは認識していいわけですね。","respondent":"鈴木都市計画課長","answer":"考え方につきましては、地域の状況を踏まえながら検討していくというもので、各自治体がそれぞれの地域特性に応じて検討していくという内容のものです。","id":"exchange-103"},{"speaker":"大沢委員","kind":"質問","question":"そうなると、１番のところで、「ルート変更、幅員変更の路線数０で、全国的にみると突出して少ない」と記述はしてありますけれども、東京の現状を考えてみると、少なくなるのはいたし方ないというような考えでいいのか尋ねました。","respondent":"鈴木都市計画課長","answer":"この見直しの数ですとか、廃止の数について、これは全国一律で比較するものではなくて、東京都、２３区としては、やはり既存の都市計画道路が一定程度必要だということで議論がされて結論が出されて計画が出されたです。","id":"exchange-104"},{"speaker":"安藤委員","kind":"質問・要望","question":"８割方できていたところまで、きちんと正面から見直し対象にして、自然環境を守るということで廃止にしたところもあるのです。その状況こそ見直しすべきだし、地元から住民の声を聞いて、むしろ周りに働きかけていくというような立場になっていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-105"}]},{"id":"topic-05","title":"平成３１年請願第９号 特定整備路線 放射２号線の計画を見直し中止を求める請願","agenda":"平成３１年請願第９号 特定整備路線 放射２号線の計画を見直し中止を求める請願","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"伺いますが、先ほどの質疑もありましたが、この放射２号線を通る地域の危険度ランキングの状況について、それぞれお伺いします。伺いたい２点目ですが、星薬科大学は、品川区のシティプロモーションという感じで魅力の１つだということでＰＲもされておりました。","respondent":"高梨木密整備推進課長、鈴木都市計画課長","answer":"続きまして、西五反田五丁目ですが、順に、ランク２、ランク１、ランク３、総合危険度がランク２です。西五反田六丁目、順に、ランク２、ランク２、ランク１、総合危険度がランク２、このような状況です。意見をお聞きするというお話ですが、これまで区としてこの大学に出向いて、あるいは来ていただいて意見を伺うということは行ってございません。","id":"exchange-106"},{"speaker":"安藤委員","kind":"質問","question":"これが１点目です。こういう影響を認めるのか、そして、それをどう考えているのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"区としてもこういった取り組みに対して周辺の不燃化、連携をして、今後も進めていきたいです。説明をして、お話を聞くのは、やはり事業主体である東京都が最前線に立って行っていくべきものだというふうな理解です。","id":"exchange-107"},{"speaker":"安藤委員","kind":"質問・要望","question":"実際に当事者である大学が見直しということで要望もしているわけですから、手を挙げた責任を品川区は考えていないのか。これぐらいはやってもいいのではないかと思うのですけれども、これをぜひ都に働きかけていただきたいのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長、高梨木密整備推進課長","answer":"区としては、やはり総合的な観点から必要な都の事業だというふうに認識しておりますので、区としても必要な事業だというふうな認識を持っております。その上で、責任があるから沿道の大学には区も説明を行うべきだというところは… 買収が済み、老朽住宅が除却され空地になっていると、木密地域の防災性は一定程度向上しているものと考えております。要望を聞きながら、東京都と協議してまいりたい、このように考えているところです。","id":"exchange-108"},{"speaker":"安藤委員","kind":"質問・要望","question":"存続にかかわるような問題になったわけですから、きちんと地元の自治体として当事者の意見を聞く場面を持ってほしいと求めました。品川区としては東京都に開催を要求していただけるのかどうか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"冒頭ご説明しましたように、事業説明から始まって測量説明など、手順にのっとりまして東京都は事業開始に当たって説明会を開催してきてあります。","id":"exchange-109"},{"speaker":"安藤委員","kind":"質問・要望","question":"本当にどうなっているのだと思いますので、私は必要だと思いますので、区としても受けとめてほしいと求めました。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-110"},{"speaker":"安藤委員","kind":"意見","question":"結論を出すで、採択で。るる理由は申し述べましたので、これは採択すべきものだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-111"}]},{"id":"topic-06","title":"平成３１年請願第１０号 東京都に「柏崎刈羽原発に頼らない脱炭素の『東京再生可能エネルギー計画』策定を求める意見書」の提出を求める請願","agenda":"平成３１年請願第１０号 東京都に「柏崎刈羽原発に頼らない脱炭素の『東京再生可能エネルギー計画』策定を求める意見書」の提出を求める請願","exchanges":[{"speaker":"横山委員","kind":"確認","question":"何点か確認ですけれども、品川区の状況はどうなっていて、これからどういった形で考えられているのでしょうか。４番のところで、詳細、具体的にどのようなことなのかご説明をお願いします。","respondent":"小林環境課長","answer":"品川区の取り組みということで、都の取り組みの中で、東京都の中で今進められているところです。通常の東京電力等の発電時のＣＯ２排出量からしますと、約２５％程度ということで非常にクリーンなエネルギーだと認識しています。","id":"exchange-112"},{"speaker":"横山委員","kind":"質問","question":"品川区でも再生可能エネルギー、いろいろ使っていただいているかと思います。３６校で行われているということで、どういったバランスといいますか、どのように区として考えられているのか教えていただけたらと思います。","respondent":"小林環境課長","answer":"その中でも示されているとおり、やはりエネルギーミックスという考え方で進めてまいりたいです。２０３０年に向けた目標のご説明をしたところですが、その先の２０５０年に向けた対応という中では、今後。","id":"exchange-113"},{"speaker":"横山委員","kind":"質問・要望","question":"１つのエネルギーだけに依存しているときに、品川区としても国や都と連携しながら、ぜひ進めていただきたいというふうに思っているところであります。実績だったりの、都でつくっているものですけれども、区としてはどのように捉えていらっしゃいますか尋ねました。","respondent":"小林環境課長","answer":"なかなか都で策定した計画ですので、再生可能エネルギーの導入のところについては着実に進んでいるところかと捉えてあります。この達成に向けて、品川区もしっかりと努力して進めてまいりたいというふうに考えてあります。","id":"exchange-114"},{"speaker":"安藤委員","kind":"質問・要望","question":"福島原発事故の、再生可能エネルギーの量を増やしていくということが大変重要だし、その役割の先頭に立ってほしいと求めました。伺いますが、イメージがあれば教えていただきたいのと、そこら辺はどうなのか伺いたいと思います。","respondent":"小林環境課長","answer":"ＣＯ２が減る減らないというわけではなくて、空気の循環をして、そこの部屋を少しでも快適にしようという考え方で進めているところです。","id":"exchange-115"},{"speaker":"安藤委員","kind":"質問・要望","question":"再生可能エネルギー導入を促進する自治体、東京都が品川区の取組みを強力に後押しするという方向に行くというのはすごく重要なのではないかと。品川区としては、その支援についての評価といいますか、それをあわせてお伺いしたいと思います。","respondent":"小林環境課長","answer":"これは東京都と一緒に連携をして、その連携を深めながら、今いろいろな事業を進めているところです。研修制度や情報連携なども行ってございまして、さまざまなところで東京都と連携を深めながら、再生可能エネルギーの導入を推進しています。","id":"exchange-116"},{"speaker":"安藤委員","kind":"質問","question":"もう一度伺いますが、お金的なところでの支援は、品川区には今はしていないということでよろしいのでしょうか。以前は東京都からも何か来ていたような記憶もあるのですけれども、そこら辺とあわせてお願いします。","respondent":"小林環境課長","answer":"今、区の事業、環境課で行っている事業というところで太陽光のご説明をしたところですが、それについては区の単費です。逆に東京都のほうで助成を行っているところでございまして、そういったところをうまく連携させながら、区と都が行っているところです。","id":"exchange-117"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ東京都にもっと自治体を応援していただきたい。こういった意見を品川区から上げていくというのは、非常に重要なことだと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-118"},{"speaker":"筒井委員","kind":"質問","question":"都の再生可能エネルギー利用率で、２０１６年度の実績が載っているのですけれども、２０１７年とか２０１８年、さらに直近の実績はわからないか尋ねました。","respondent":"小林環境課長","answer":"これらの分析、解析が非常に難しいというのが現状でございまして、今、品川区で把握している、あるいは東京都で把握しているものも、公にされている情報も、２０１６年が最新です。","id":"exchange-119"},{"speaker":"筒井委員","kind":"質問","question":"目標は、品川区もそうなのですけれども、行政としては実績から大体どのぐらいを目標に立てるものなのでしょうか。品川区の場合は、目標を立てる際、実績値からどのくらいとか、どういう根拠で目標を立てているのか尋ねました。","respondent":"小林環境課長","answer":"ある一定の分析をしたうち３０％を出したというところでございまして、一定、積み上げた値から３０％が示されたというふうに聞いてあります。","id":"exchange-120"},{"speaker":"筒井委員","kind":"質問","question":"行政としては、目標に実際の実績が追いついていない状況で、さらに目標を高く上げるということは、どうお考えなのか尋ねました。","respondent":"小林環境課長","answer":"東京都の３０％の出し方については、根拠があるというか、達成ができそうな数字の中でお示しするべきというふうに認識しています。","id":"exchange-121"},{"speaker":"安藤委員","kind":"意見","question":"結論を出すで、採択です。世界の深刻な温暖化問題がありますけれども、それに向けて動いていくということは非常に大切なので、採択を主張いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-122"},{"speaker":"筒井委員","kind":"意見","question":"本日結論を出すで、再生可能エネルギーの普及促進という趣旨は賛成するのですけれども、今、目標の３０％にさらに上げるというのは、非現実的なことではないかと思いまして、不採択としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-123"}]},{"id":"topic-07","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"１点お伺いしたいのは、その場合に車両にはドライブレコーダーは搭載されているのかどうか、この点についてお聞きしたいと思います。","respondent":"工藤品川区清掃事務所長","answer":"清掃車につきましては、全車、区有車、委託車両等につきまして、ドライブレコーダーをつけております。したがいまして、事故時につきましては、ドライブレコーダーを解析して、事故の原因等を分析いたしまして、再発防止に努めているところです。","id":"exchange-124"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/876969?Template=document&Id=4256#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":91409,"voices":343}},{"id":"r01-20190225-9","meetingId":"r01-cm02","date":"2019年2月25日","dateIso":"2019-02-25","committee":"文教委員会","time":"午前１０時００分～午後 ３時１９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を92件整理しています。","topics":[{"id":"topic-01","title":"第１５号議案、品川区子ども・子育て会議条例の一部を改正する条例","agenda":"第１５号議案、品川区子ども・子育て会議条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"改正理由のところに、「会議の運営内容に応じた庶務所管とすることで効率的な運営を図る」とありますけれども、当初は子ども育成課がふさわしいということで、内容的なもので保育課に移したほうがいいと、子ども・子育て会議の内容とかが変わったのか、その辺をもうちょっと詳しく説明を求めました。","respondent":"高山子ども育成課長","answer":"所管としての会議の中身とどのようなふさわしさがあるかという点です。それに伴い次世代育成支援対策推進行動計画の内容については、純然たる、子ども・子育て支援事業計画という保育の内容を主とする。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"確認","question":"わかりました。今回の条例は、所管がかわるということだけで、ほかは何もないのかどうか、そこの確認をできますか尋ねました。","respondent":"高山子ども育成課長","answer":"今回の改正理由の中に書かせていただきましたとおり、その内容にふさわしい所管が庶務事項を所管するといった以上の変更は今回ご提案するものではございません。","id":"exchange-002"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"確認させていただきたいのですが、今度は保育課のほうでこの庶務所管の職務というんですか、役割をまた庶務担当の方が新しくどなたかなると。そういうことに関しては、特に条例云々ではなくて、組織が変わるのかなと思うんですけれども、その辺の扱いはどのようになるのか尋ねました。","respondent":"高山子ども育成課長","answer":"３目児童保育費という予算ということで、今回平成３１年度から分掌とする切り替え・変更を行っていくと、そのような趣旨のものです。","id":"exchange-003"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、保育課のほうの係長かどなたかがこれを担当することになるのでしょうか。そこのところを、すみません。","respondent":"高山子ども育成課長","answer":"今回の条例改正とともに規則のほうも変更を加えまして、保育課の係にこれまで子ども育成課の庶務係で担っていた事務そのものを移すというようなことですので、保育課の係において処理していくということとなります。","id":"exchange-004"}]},{"id":"topic-02","title":"第１６号議案、品川区女性福祉資金貸付条例を廃止する条例","agenda":"第１６号議案、品川区女性福祉資金貸付条例を廃止する条例","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"ちょっとそのあたりも含めて教えていただきたいというのが１つです。その後どういうふうに評価しているかという、とりあえず、３点。","respondent":"廣田子ども家庭支援課長","answer":"利用実績についての考え方ですけれども、貸し付けを受ける母子のお子さんのほうが２０歳を過ぎたときに母子福祉資金では対応できないということで。","id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"そういう点で見たときに、この制度の役割は終わったと認識していると受けとめていいのかというのを伺いたいと思うのです。そういうことでいいのかと非常に気になるので、改めてそこの考え方を伺っておきたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"は商業・ものづくり課のほうで女性の就労支援についても事業に力を入れて拡充しているというところと、自立支援については就業支援であるとか、品川区が女性の自立支援を低下させるということにはならないという判断をしています。","id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"商業・ものづくり課のほうでもどの程度の状況なのか、それを伺いたいと思います。廃止した後の他の制度で充実して対応できているというそこの制度の状況がどういうふうになっているのかを見ないと、教えてほしいと求めました。","respondent":"廣田子ども家庭支援課長","answer":"事業の継続等については直接は関係ないのではないかと思いますが、子ども家庭支援課で扱っている資金については低所得の方になるので、事業の開始。向こうで救える制度があれば、そちらで拾えるというところになっておりますので、問題はないものと考えております。","id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"もう一つ借りにくくなっているところとして保証人を確認、つけなくてはいけないと、非常に余りにも安易というかやめるべきではないかと。最後に、いろいろ借りやすいようにと工夫した実績というのはどういうところがあるのか、あったら教えてほしいと求めました。","respondent":"廣田子ども家庭支援課長","answer":"これだけで判断するものではないと考えておりますし、女性福祉資金については、ほかの制度で借りることができるので切るわけではありません。一定の利子のもとに貸し付けすることができるというのが福祉資金ですので、切り捨てているというような考えはしておりません。","id":"exchange-008"},{"speaker":"南委員","kind":"確認","question":"したがって、そこについてはどうだったのか、改めて伺いたいと思います。そこについての、ではなくすためには利子をいただくということをおっしゃっていたけれども、それだけなのかどうかも含めて確認したいと思います。","respondent":"廣田子ども家庭支援課長","answer":"保証人云々で借りにくいということではなく、子どもの年齢要件である等で借りられない人を拾っていたものです。品川区独自で変えるということは余り考えにくく、もともと都の社会福祉協議会の制度で、この分野についてはそれで役割は終わったと判断したものです。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問","question":"そういった意味で、女性の実態というのが果たしてつかめるのかどうか。今までの実績の教育のところで貸付継続者として大学生１名と２８名の償還をされている方が、この２８名のことも説明を求めました。","respondent":"廣田子ども家庭支援課長","answer":"他制度で拾うからという話があったのですけれども、どの方も助成については女性の相談を受けているので、子ども家庭支援課の窓口に見えます。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"確認","question":"ちょっとそこをもう一度確認したいのと、やはりきちんとした相談ができるのかどうかと疑問を抱くのですが、その点はいかがでしょうか。選択肢が狭まるということは明らかであると思うのですが、いかがか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"今も審査から貸し付け、償還まで子ども家庭支援課で行っておりますので人に渡すわけではございませんし、これからも連携できると考えております。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問","question":"今の時期大変だけれども、ちょっと頑張れば何とかなるという人たちの生活を支える住居の問題とかは、十分ほかでカバーされているのでしょうか。私はそこがそうなっていないのではないかと受けとめているのですけれども、いかがか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"それ以上所得が低い方については社会福祉協議会をご案内しますけれども、それ以上所得が低い方は生保になりますので、貸し付けをしないというのは貸し付けの対象がいないというふうに考えています。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問","question":"そういう人たちはその先の、生保も含めてきちんとした生活ができるような援助が実際に行われているのかどうか。どのくらい行われているのか、その辺も説明を求めました。","respondent":"廣田子ども家庭支援課長","answer":"それ以上の支援といいますか、そちらにまずご案内して、そこから生保かどうなるかというところにつないでおります。その先がどうなったかにつきましては生活福祉課で把握されているかと思いますので、残念ながら今手元にはデータはございません。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"多分、実際に困っていらっしゃる方をご案内したりするとどこも受けられないというような実態が多々あるのです。私はこの暮らし・しごと応援センターですか、最終的にはあきらめざるを得ないという実態があるのではないかと思いますが、その点はいかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問","question":"答弁はいいのですが、ずれてはいないのです。やはり考えていってほしいという意味においては、やはりどれだけ連携が取れているのかというところなので、答弁は結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"今回この条例の廃止がなぜこの時期に上がってきたのかという背景を改めて教えてほしいと求めました。私は、今の時代に合わないような条例に関してはやはりしっかり見直しするべきだと思っていて、私は廃止するのは当然のことかなと。","respondent":"廣田子ども家庭支援課長","answer":"一度、これをきっかけにそれぞれその１件あるかないかのために予算をつくって事務担当者をつけてというところは事務費もかかります。それとあわせまして、長期基本計画も見直しになりますので、トータル的にというところで進めていこうと考えております。","id":"exchange-016"},{"speaker":"つる委員","kind":"質問","question":"それから貸付金償還者、条例自体の廃止は今定例会に上程されている中で、ただその後の債権の回収等にかかる事務経費というのは今後も継続する。事務経費というところは大きく２つに分かれるとは思うのですが、その経費的な部分ではどうなっているのか、そのあたりを説明するよう求めました。","respondent":"廣田子ども家庭支援課長","answer":"不納欠損で落とすこともできませんので、６名の大体のめどがついたというところですので、近い将来事務費としては消えていく予定です。確認ができれば落ちる経費ですのでいつかはなくなるという認識をしております。","id":"exchange-017"},{"speaker":"つる委員","kind":"質問・要望","question":"そうすると、そこは当然なくなる、貸してくださいということに対する事務経費というのはなくなるわけです。ただ、そういう滞納者に対する対応、経費的な部分でどの程度財源的なところでは変わるのかというのは教えてほしいと求めました。","respondent":"廣田子ども家庭支援課長","answer":"その辺は横ばいなのですけれども、若干、遠方にいらっしゃる方について所在の確認をしなければいけない部分については委託を考えております。全部使うかどうかはわかりませんが、新年度の予算の中で債権回収業務等委託という形で計上しております。","id":"exchange-018"},{"speaker":"つる委員","kind":"質問・要望","question":"その中には今言った当然回収の事務経費、債権回収に対する委託の部分が大きくついているとは思うのですが、ただ通常の事務経費というのでしょうか。予算特別委員会の中でもこの辺は確認したいと思うのですが、今いろいろな議論があって、これは当然今後強化をしていただきたいというところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"非常に経済的にもいろいろな状況のところで苦労しておられる方々への支援を、他の制度に変わるということでなくしてしまうわけにはいかないと。やはり、女性の自立というところをしっかりとフォローする制度は残していただきたい、そういうことです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]},{"id":"topic-03","title":"第１７号議案、品川区児童育成手当条例の一部を改正する条例、(4)第１８号議案、品川区ひとり親家庭等の医療費の助成に関する条例の一部を改正する条例","agenda":"第１７号議案、品川区児童育成手当条例の一部を改正する条例、(4)第１８号議案、品川区ひとり親家庭等の医療費の助成に関する条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"今のご説明で、このいただいたＡ４の資料の下の表がありますね。ここのところが入ることで今までと同じ状況にあるという説明でしたが、これがもし入らないとどういうことになるのか、その違いを説明するよう求めました。","respondent":"廣田子ども家庭支援課長","answer":"私の説明が悪かったのかもしれないのですけれども、この「控除対象配偶者」を１人として数えるか数えないかだけ、金額の問題ではありません。","id":"exchange-021"}]},{"id":"topic-04","title":"第１９号議案、品川区子どもの医療費の助成に関する条例の一部を改正する条例","agenda":"第１９号議案、品川区子どもの医療費の助成に関する条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問","question":"この高校生まで対象を広げるということは私たちも主張してきたことなので大歓迎したいなと思っています。それ以前の小さなお子さんたちとの関係でどういうふうに振り分けたのか、そのあたりの説明をお願いします。","respondent":"廣田子ども家庭支援課長","answer":"現在、１５歳未満の方につきましても東京都以外で診療されたり、同様の形を考えています。償還払いという形が一元的に、医療証を発行して各病院に手配する手間暇を考えると、事務効率がいいのではないかということで検討いたしました。","id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"ただし、今後の問題としてそういった外来、通院の部分も対応していただけるように求めていきたいということは言っておきたいと思います。いろいろあるのですが、ぐちゃぐちゃになってしまうのでやめて、償還払いにしたという理由はわかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"石田（し）委員","kind":"質問","question":"ちょっとお伺いしたいのですけれども、あとは、システムの改修費は毎回何かあると出てくるのです。このシステム、何にこんなに１,０００万円もかけているのか、まずそこを説明するよう求めました。","respondent":"廣田子ども家庭支援課長","answer":"入院費の年度またぎなのですけれども、医療費は月ごとの支払いになりますので、４月１日の支払い分以降から適用になると考えております。契約金額ではなく、予算額ですので、契約金額はもうちょっと落とせるのではないかと思います。","id":"exchange-024"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"それはそのシステムをつくっているところの仕事ですから、予算書を見ると、このシステム改修費は毎回いろいろ出てくるのです。大体１,０００万円単位で出てくるので、これはでも本当にそういうふうなものにしていただきたいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"高橋（し）委員","kind":"質問","question":"話が外れてしまったら申し訳ありませんが、婚姻の年齢、これはあれですよね、お子さんでも結婚している方の話ですよね。とすると、これは条例でそういうふうに付け加えてあるのですけれども、女性の婚姻年齢が変わったらまた条例も変えるのか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"何を言っているかというと、ここの説明はすごくざっくりしているのですけれども、親との扶養関係を示しているところです。事実婚も含むので、条例の改正をその都度するということはなるべくないような形で考えています。","id":"exchange-026"},{"speaker":"高橋（し）委員","kind":"確認","question":"確認で、女性の婚姻年齢が１８歳になったとしても、それによって影響がない記述の方向だということか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"そのとおりです。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ちょっとそこを具体的に一つお伺いしたいのと、今回は、例えば通院を含めて試算をするとこの予算が幾らぐらいになるのか。多分計算されているのではないかと思うので、教えてほしいと求めました。","respondent":"廣田子ども家庭支援課長","answer":"千代田区が外来まで全部行っているのですが、１６歳から１８歳の子どもが１,０００人ぐらいしかおりません。単純計算ですけれども１億８,０００万円になってしまうので、入院のみでというのが妥当な線かなというところを検討しています。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問・要望","question":"数字を教えていただいてありがとうあります。私たちとしてはぜひ早い時期に通院も含めて１８歳までの医療費ゼロを実現してほしいなと思うのと、できたら保護者の方々の負担を考え。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"つる委員","kind":"質問・要望","question":"公明党としても高校生までの医療費の助成を求めてきて、その中でもせめてということで入院費のところもあわせて求めてきたところなので。ほかと何かしら連携させていてこういうふうにシステム予算がかかっていくのか、ちょっと細かい部分なのですけれども、そこのところを説明するよう求めました。","respondent":"廣田子ども家庭支援課長","answer":"今年度予定して、９区なら９区受けもっていると、５区入っていれば２００万円ずつみたいな感じでのせられるという形で。ちょっと言いなりには契約をしないようにいろいろ研究をした上で契約をしようと思っているところです。","id":"exchange-030"},{"speaker":"つる委員","kind":"質問・要望","question":"どうしても表に見えない部分で、その限りではないと思うんですけれども、きちんと精査していただいてやっていただきたいなと思います。当然想定以上にそういう助成が必要になることもあると思うのですが、そうした部分の対応について説明を求めました。","respondent":"廣田子ども家庭支援課長","answer":"北区について過去の様子も見たのですが、大体１件当たり５万円から７万円ぐらい負担されているのかなというところが計算上は出ています。ですので、参考からいうとこの程度でおさまる範囲と、やってみながら実績と見合いながらというところで考えていきたいと考えています。","id":"exchange-031"},{"speaker":"つる委員","kind":"質問","question":"今の五、六万円の参考値というのは、入院の部分についての試算での五、六万円という計算でよろしいですね。そこになおかつ品川区はプラスアルファして予算立てをしているという考えでいいのか説明を求めました。","respondent":"廣田子ども家庭支援課長","answer":"１件当たり５万円から７万円助成をしているという、北区の実績から見るとその程度なのだなというところを参考にさせていただきました。北区と品川区で１６歳から１８歳の児童人口がほぼ同じぐらいだったので、データが出てくればまた変わってくるかもしれません。","id":"exchange-032"},{"speaker":"つる委員","kind":"質問・要望","question":"失礼しました。今回、引き続き公明党としても高校生等の医療費全体の拡大ということは求めていく立ち位置ですが、先ほども申し上げたとおり。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"}]},{"id":"topic-05","title":"第２６号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","agenda":"第２６号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"大もとのところは何を基準にしているのか教えていただきたいのと、学校医の方たちから公務災害に関するものについて何か意見があるかどうか。該当者がいつもいないということなのですが、その後発生はしていないのかどうか説明を求めました。","respondent":"篠田学務課長","answer":"いつも東京都と合わせて変更しているのですが、あと、ずっと合わせて変えてきているという経緯があります。発生件数ですけれども、先ほど申し上げたとおり、これまで区に関しては１件もなく、現在もそういう状況が続いているものです。","id":"exchange-034"}]},{"id":"topic-06","title":"第２７号議案、幼稚園教育職員の勤務時間、休日、休暇等に関する条例の一部を改正する条例、(8)第２８号議案、学校教育職員の勤務時間、休日…","agenda":"第２７号議案、幼稚園教育職員の勤務時間、休日、休暇等に関する条例の一部を改正する条例、(8)第２８号議案、学校教育職員の勤務時間、休日…","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"最初のご説明にありました、国家公務員と同様に区固有教員、あと幼稚園教員も超過勤務の上限を取り入れるといった後に、勤務時間のガイドラインの条例ですか、ちょっと聞きとれなかったのですが、それがどういうものなのか説明を求めました。","respondent":"熊谷指導課長","answer":"こちらについては、これについては今回のものとは全く別物でありまして、今後それについての条例ですとか規則改正が行われることになっております。今回はあくまでも超過勤務を行うことができる上限時間について定める条例ということになっております。","id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問","question":"人事委員会勧告の、多分まだ出ていない時期に区によってばらばらにこの条例が出されるところと出されないところとあるというのを伺ったのですが。なぜこの時期にこれを品川区が出してきたのかというあたりをまずお伺いします。","respondent":"熊谷指導課長","answer":"例えば人事委員会規則等の対象、その条例から教育職員は除く必要がないということで、まず同じような措置を講じなさいということが示されております。","id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういう特殊な環境にある教員に対して上限を定めるというのはどういうことなのかと、そこのところを教えていただきたいです。１年については３６０時間以下と書かれていますが、これを書くこと自体がどういう意味があるのかというのと、ちょっとそこのところを説明するよう求めました。","respondent":"熊谷指導課長","answer":"（２）のほうは国家公務員でも他律的な業務の比重の高い部署というところで、法令協議、予算折衝等に従事と非常に限られた部署なのです。規則案については都からも、（２）のほうは、これは先ほど申し上げた超勤４項目では該当しないということになります。","id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問","question":"だから、大事なところが規則に書かれるといった意味においては、そうですかと言って受けとめるのは大変危険であるなと思っているのが一つです。労使間の合意というのは普通の労働者は労使間で３６協定が結ばれているのだけれども、超長時間労働、その点はいかがか尋ねました。","respondent":"熊谷指導課長","answer":"４％の調整手当が出ているので、ただ、今回の条例はそういったことで改正になっているということです。もちろんそれはとても重要なことで、体が元気で子どもたちの前に生き生きと立たないと教員として本来業務を全うすることができないと考えています。","id":"exchange-038"},{"speaker":"石田（し）委員","kind":"質問","question":"今のご説明だと、第１０条第３項のいわゆる「承認を得て、今後ガイドラインができてまた示されたらこれはまた変えますよという説明だったのですよね。第１０条第３項の「人事委員会の承認を得て、先ほどの説明でいまいちわからなかったので、改めて説明を求めました。","respondent":"熊谷指導課長","answer":"その超過勤務の上限を決めますよという、あくまでもその条例改正を行うというところですので、まだ具体は全くわからない。これから決めますというところで、まず今までは全く「上限」という言葉が出てこなかったところに、それを示すための条例改正ということになります。","id":"exchange-039"},{"speaker":"石田（し）委員","kind":"提案","question":"それをつけますよ、それで規則でそれは何時間ですよというのを同時に提案しても、そんなに問題はないのかなと思うのです。私の今までの記憶の中にはこんな２段階の条例の改正は余りイメージがないのだけれども、何でなのかというのがもしわかれば説明を求めました。","respondent":"熊谷指導課長","answer":"総務省から、これについてはまず条例の改正をしてくださいという通知が来ました。順番として、条例改正をした上で規則改正をしていく、段階を踏んだというところでそうした通知が出たことから今回の条例改正となったものです。","id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問","question":"ちょっと意見をよろしいですか。規則を見ないとどういうふうに書かれているかわからないというところで、とても判断ができないといった意味では、反対いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"}]},{"id":"topic-07","title":"ただいま１２時少し前でございますけれども、次の議題に入りたいと思います。 次に、(9)第２９号議案、学校教育職員の給与に関する条例の一部を改正する条例","agenda":"ただいま１２時少し前でございますけれども、次の議題に入りたいと思います。 次に、(9)第２９号議案、学校教育職員の給与に関する条例の一部を改正する条例","exchanges":[{"speaker":"石田（し）委員","kind":"質問・要望","question":"これは都が行っていることですから余り言うことでもないのかなと思うのだけれども、今すごく教員の倍率も低くなってきてしまっているのですよね。金額とはちょっと離れてしまうのですけれども、その辺をどういうふうに考えているのかだけ教えていただければなと思います。","respondent":"熊谷指導課長","answer":"やはり教員になりたいという思いを持って、それを実現できる若者というのはこれから非常に日本の国をつくっていく上で大事ではないかと思っています。","id":"exchange-042"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"１,０００円引き上げる等々も含めて環境整備というのはしっかりしていかなければいけないのかなと思います。ぜひ環境整備という部分では、効率化も含めて取り組んでいっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１の条例改正の概要のところに、「初任給を１,０００円引上げる他、どういうことなのかというのが１点です。東京都においてもそういった検討とか実態に合わせたものに変えていこうというような議論があるのかどうか、教えてほしいと求めました。","respondent":"熊谷指導課長","answer":"それから、ちなみに、それから品川区立学校の取り組みが東京都の全教員に対して効果的な取り組みということで紹介をされております。ですので、本区がやっていることもその一つの効果的な事例ということで示されているということをご紹介したいと思います。","id":"exchange-044"},{"speaker":"つる委員","kind":"質問・要望","question":"これは給料表自体の事務的な確認をさせていただきたいと思うのですが、質疑の間、号給はどこまでが初任層になるのか教えていただきたい。どの辺のところまでを初任層というのか、説明を求めました。","respondent":"熊谷指導課長","answer":"ですので、３級の主任教諭ですとか４級の主幹教諭や指導教諭は対象にはなっておりません。２年目、３年目、大体２級の３０号給までが対象となっているところです。","id":"exchange-045"},{"speaker":"つる委員","kind":"意見","question":"１級、２級というのは、大学の、短大とかの、僕はどうかなと思うのだけれども、短大と四大のあれで１と２と等級でいうと違うのでしたかとの意見を述べました。","respondent":"熊谷指導課長","answer":"１・２級につきましてはご指摘のとおりで、短期大学卒業、四年制大学卒業ともにおるということになっております。","id":"exchange-046"},{"speaker":"つる委員","kind":"確認","question":"いずれにしてもその中で品川区においては２級の３０号給までの中におさまる方が９名いて、そういうことですか、確認です。","respondent":"熊谷指導課長","answer":"そのとおりです。１級はおりませんので、２級の３０号給までが対象となっております。","id":"exchange-047"}]},{"id":"topic-08","title":"平成３１年請願第５号、一人ひとりの子どもが大切にされる品川区を求める請願","agenda":"平成３１年請願第５号、一人ひとりの子どもが大切にされる品川区を求める請願","exchanges":[{"speaker":"南委員","kind":"質問","question":"あるいは実際にどういうふうに行っているのか、そのところを一つ具体的に伺いたいと思います。私の理解は、認証保育園も３歳未満のところが結構あるので、それについてもどういうふうに区としては受けとめているのかを伺いたいと思います。","respondent":"大澤保育支援課長","answer":"指導、検査も実施しておりますし、ソフト面の保育士の確保についても区として処遇改善等に取り組んでいるところです。３歳からの保育につきましては、そういった意味では整っていると認識しています。","id":"exchange-048"},{"speaker":"南委員","kind":"質問・要望","question":"それから、そこの今品川区の現状、公立あるいは私立も含めて正規・非正規の割合がどのくらいになっているのかというところを伺いたいと思います。３歳の年齢で環境ががらっと変わってしまう、そういう状況が起きてしまっていることに対して、区はどういうふうに認識しているか伺いたいと思います。","respondent":"大澤保育支援課長、佐藤保育課長","answer":"ビルの中のフロアを使って保育園を開設するような場合は、どうしても園庭はできませんので、そういう場合はいたし方ないと考えております。後にさせていただいて、３歳児の転園につきましては… 当然その数はクリアしているところで、約２.５倍の保育士、保育関係職員を配置しているところです。正規に関しましては、約その半分、５５％程度、それ以外に関しては人材派遣や非常勤等で対応しているところです。","id":"exchange-049"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、そこについて、転園できるからいいのだという考え方には立たないでいただきたいと。認証保育園も小規模保育園も何らかの形で、否定的な意味ではなくいい意味で解消できるように、改めてその辺についても伺いたいと思います。","respondent":"大澤保育支援課長、吉田保育施設調整担当課長、佐藤保育課長","answer":"確かにもう一度３歳のときにいわゆる保活をしなければいけないという煩わしさは私どももわかります。必ず３歳児で受け入れはできる状況ではありますけれど… この辺を含めまして、一定程度ご利用の皆さんのご理解を得られていると考えています。民間でできることは民間でという方針もありますので… 特別支援であったりさらなる保護者支援等について、より進めている状況ですので、公立は公立としての役割をしっかりやっていきたいと考えております。","id":"exchange-050"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひ誤解しないでいただきたいと思い、あえてつけて加えておきたいと思います。そこのところはそういう姿勢があるのだということを改めて確認できたので、私自身もそういう立場でこれからも引き続き頑張りたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問・要望","question":"過去５年間の増設の数をもう一度教えていただきたいのと、あと請願にマンション建設によるファミリー世帯の増加が見込まれていますと書かれています。さっき増設の数もお聞きしているところですけれども、待機児童をなくしてほしいという願いが書かれているのですが、その辺の認識を説明するよう求めました。","respondent":"大澤保育支援課長、吉田保育施設調整担当課長","answer":"平成２７年度が５園、平成２８年度が７園、平成２９年度が１２園、平成３０年度が１７園、平成３１年度が１２園の予定です。開設数につきましては、就学前人口増や就労率の増加を見込んで計画を立て直して… 就労率の変化なのですけれども、今子ども・子育て支援事業計画というのを平成３２年度から新しく見直すための保護者向けの調査等をやっております。速報値ですのでまだ細かくは分析していないところですけれども、そういったところです。","id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問","question":"今のご説明だと、平成２５年度よりも１０％、保護者の皆さんの統計ですよね、既に預けていらっしゃるということか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"子ども・子育て支援事業計画をつくる意向調査の中では、その保護者に対して調査をかけた次第です。細かいところはまだ集計できておりませんので、そこはご理解いただきたいと思います。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問","question":"就学前ということで、区内全域でサンプルを選んだということなので、とても大事なことだと思います。この辺が、同じような状況で平成２５年に調査をして１０ポイントにということなのかどうか、そこももう一度説明を求めました。","respondent":"吉田保育施設調整担当課長","answer":"今回につきましては、就学前乳児人口が増えていることもありまして、７,０００サンプルをとったところです。ただし、回収率については若干下がっておりまして５５％程度で、前回よりも下がっているところです。","id":"exchange-054"},{"speaker":"飯沼委員","kind":"確認","question":"待機児童は１９人でほぼ待機児童は解消したという答弁が何回かあったのですけれども、今年の一次のところをもう一度確認させてほしいのです。この状況からして、保育課の見解というのはもう一応計画どおりにすれば待機児童はないと考えているのか、その辺も説明するよう求めました。","respondent":"大澤保育支援課長","answer":"追加でご説明すると、現在のところ二次の空き状況は１,１３７人になっています。平成３１年４月の入園状況ですが、平成３０年４月とほぼ同様の状態になると現時点では見込んでおります。","id":"exchange-055"},{"speaker":"飯沼委員","kind":"意見","question":"それにしても１９人もいるのにほぼ解消という認識はどうなのかと思うのと、１５２人になるのですよね。不承諾通知を受け取った子が１５２人もいると、幼稚園のところはとっくに終わっているというところでこの辺をどう考えているのかを説明するよう求めました。","respondent":"大澤保育支援課長","answer":"委員おっしゃったとおり、不承諾にはなっておりますが、少し希望園の枠を広げていただければ必ずどこかの認可保育園には入れる状況です。他の園に行ってほしいということを申し上げているのではなくて、区として受入れ枠はしっかりありますということをご説明しているところです。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問・要望","question":"平成３０年は９５５人が不承諾だったのですけれども、そのうち待機児童が１９人になっていて、ぜひ明確な数字で教えていただきたいのです。ちょっとそこの数字の減らしていく中身を教えてほしいと求めました。","respondent":"大澤保育支援課長","answer":"入園が決まったけれども辞退をされる方というのが去年も３３１人出ていますし、不承諾者全員が入れないという状況ではないと思っています。認証等の受け皿もある以上、認可に申し込んだ方で入れなかった方全員が待機児童というふうには国としても区としても考えてはいません。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問・要望","question":"待機児童のカウントの仕方を変えたのですから。改善もしてほしいと思うので、昨年の１９人、待機児童をなくしてくださいという願いを真摯に私は受けとめていくべきであると思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そんな状況の中で、やはり公立の保育園が求められているのが私は当然であると思うので、こんなに保育園が足りなくて次々にできていて。この点について見解をお聞かせほしいと求めました。","respondent":"大澤保育支援課長、吉田保育施設調整担当課長","answer":"これは厚生労働省で定義が決まっているので、それに沿って区としても待機児童をカウントするしかないと思っています。認証を含めて既存の施設の活用を前提として待機児童解消を進めていくことがやはり区として何年… 比較的区として立地条件のいい保育園を民営化していくことを予定しております。いい保育ができる、保育の質の確保等を含めて民営化してでも続けていけるものと理解しております。","id":"exchange-059"},{"speaker":"飯沼委員","kind":"質問・要望","question":"園庭はもちろん求めているのですが、考え、改善しようと考えているのか一点お聞きをしたい。そういった面で保育支援課と公園課の両面にお伺いしたい。","respondent":"大澤保育支援課長、溝口公園課長","answer":"保育園の公園活用ですけれども、一般の方もいらっしゃいますからというお話はさせていただいて、ここ１年公園に関するトラブル等はございません。例えば学校ですとか、神社の境内ですとか… ただやはり、なかなか土地の確保というのが難しい現状があります。公園の整備には当たっていきたいと考えていますし、少しずつ公園を増やしていけるような取り組みを引き続き行っていきたいと考えているものです。","id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もっと実態を知っていただきたい、園庭が必要だと。未来の子どもたちのためにしてほしいと求めましたが、最後に一言、保育支援課と公園課にお聞きします。","respondent":"溝口公園課長","answer":"そういった中で計画的に改修することによって、子どものアイデアですとか地域のご要望等を聞きながら改修を進めてきているところです。これからも新たにつくっていきたいと考えていますし、そういったものも行っていきたいと考えているところです。","id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問・要望","question":"足りないところにつくっていただきたいと言いました。区民の皆さんから切実に出されているものです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"南委員","kind":"質問","question":"質問者が納得し得ないような答弁だったら、また聞くしかないではないですか。きちんと発言させるべきですので、そういう運営をしていただくよう求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"石田（し）委員","kind":"質問","question":"そのことに対してどうこうというのは、それは委員会運営の一つの調整ですから、そこだけは私もつけ加えておきます。ぜひそこは、理解する部分は理解をするというのも必要なのかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"南委員","kind":"意見","question":"であるのだったら、委員会運営上こうしたいからと説明があってしかるべきです。それもなくて、一方的に判断してとめるというのは委員会運営としてはどうかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-065"},{"speaker":"渡部委員","kind":"質問・要望","question":"今後子どもが増えていくということも確認させていただいている中で、区としてはしっかり政策を進めていただいています。その回答ですから、誰が聞いてもわかるような見地をいただけていますので、そこについては進めていただければなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"つる委員","kind":"質問・要望","question":"制度に人をはめていくような視点に見受けられるような形での求め方というのは、私は違うと思いますし、この間品川区は行ってきたと考えています。そういうような内訳があるわけですから、認可を含めた総合的な待機児童対策の強化、これはこれからも必要であると考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひ公立保育園の基準がとても大事だということにおいては存続を求める、これも当然です。直ちに整備と改修が必要であると思いますので、この３つの請願項目はもっともであると考えていますので、採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"これはしっかりと公立保育園のみならず、さまざまな視点をもってその需要に対応するべきだと思っており、不採択の理由といったところであります。それはもちろん、ある意味皆さんが使えるような施設をうまく配置をしていただきたいというのは思いますので、そこは要望も含めて意見をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"より一層スピーディーにということと人口の増加に対応する形を求めていきたいとは思いますが、現状実際に行われているのでという認識を持っています。そういったことを活用しながら、園庭のないところはそれでフォローしていくことが可能ではないかと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"}]},{"id":"topic-09","title":"平成３１年請願第１１号、小中学校の給食費の無償化を求める請願","agenda":"平成３１年請願第１１号、小中学校の給食費の無償化を求める請願","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"そうすると、５・６年生は１日の食単価２８０円かける月、月は２０日で計算するのでしょうか、月額と年額がどういうふうになっているのか。今子ども、注視をしていくというのはどういうところをどういうふうに見ようとしているのか、その辺をちょっと教えてほしいと求めました。","respondent":"篠田学務課長","answer":"年間ですけれども、それを基本的には１０カ月もしくは１１カ月で割り返して各学校で徴収しているという形になっているところです。今回、あくまで給食費の無償化ですので、そのようにお答えしたものです。","id":"exchange-071"},{"speaker":"南委員","kind":"質問・要望","question":"先ほどの認識を伺いたいのと、２０１７年のときの２３区の調査を見てみると、品川区の給食費は高いのです。その点について、実態的に教育委員会としてはどういうふうに見ているのかも含めて考えを伺います。","respondent":"篠田学務課長","answer":"ですので、そういった意味で１食単位で見ていけば決して負担感が高いという認識は私どもは持っていないものです。委員ご指摘の順位よりも今はもう少し下に下がっている状況があったというふうに認識しています。","id":"exchange-072"},{"speaker":"南委員","kind":"質問","question":"財政的に余裕がある区というところで、やはりそういう財政状況にあるわけですから、いい条件を提供していくという考え方に私は立つべきだと思のです。先ほどは高いとは思わないとかこういうことで進めていきたいとおっしゃっていたけれども、改めてその認識を伺っておきたいと思います。","respondent":"篠田学務課長","answer":"これは、新に発生する経費は８億５,０００万円をこえる金額になるのではないかというお答えをさせていただきました。やはり区の考え方ももちろんですけれども、国等の考え方もよく見ながら、注視していきながら考えていきたいと考えています。","id":"exchange-073"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、国の無償化を待つまでもなく、教育のこういう分野でも品川区は先進自治体というふうにとっていただきたいと私は思います。教育にお金をかけることが無駄なお金なのかどうか、そこについての認識を最後に伺って終わります。","respondent":"篠田学務課長","answer":"私どもといたしましても、できるだけ魅力的な教育をお子様方に提供したいという思いを持ってありますけれども、やはりそれは優先順位等を考えながら、どこまで何に取り組んでいくのかというのは、さまざまな状況を判断しながら考えていくべきものだと考えるところです。","id":"exchange-074"},{"speaker":"飯沼委員","kind":"質問・要望","question":"就学援助の割合を改めて教えていただきたいのと、あと、多子家庭の３人目以降のところをやっているからこの程度で十分であると考えているのか。今後どのように考えているのか、その辺も説明を求めました。","respondent":"篠田学務課長","answer":"就学援助の小中学校の割合、人数でしょうか。","id":"exchange-075"},{"speaker":"飯沼委員","kind":"質問","question":"最低限をしているという捉え方なのですか。給食費の未納の状況はどれくらいあるのか、わかったら説明を求めました。","respondent":"篠田学務課長","answer":"要は法律に基づいた必要な対応をとりつつ、また低所得者等に対する施策も行っているという形で考えているところです。平成２７年度の未納率が０.０２％、それから平成２８年度が０.０５％、平成２９年度が０.０４％という状況です。","id":"exchange-076"},{"speaker":"飯沼委員","kind":"質問・要望","question":"品川区が取り組むべき点には４９.５％の人が出産、どうしたら子育て支援ができるのかというのを本当に考えていくべきであり、書かれていますよね。品川区はそういう力があると思うので、ぜひ踏み出していただきたいのですが、いかがか尋ねました。","respondent":"篠田学務課長","answer":"例えば学校給食の無償化をする場合、財源の話で言いますと、特定財源等ございませんので全て区の一般財源という形になってあります。そうしますと、政策としてそれが一般の区民の方に受け入れられるかどうかというのは十分考えていく必要があろうかと考えているところです。","id":"exchange-077"},{"speaker":"石田（し）委員","kind":"質問","question":"未納の対応、回収というのでしょうか、対応は誰がやっているのか教えてください。それと、未納が続いていて払わないとなった場合に、その子は給食が食べられないのか、そういう事例があったのか説明を求めました。","respondent":"篠田学務課長","answer":"足りなかったらどうするかという対応をとっているところなのですけれども、さらに全てご入学のときに口座振替の手続をとっていただいていますので。","id":"exchange-078"},{"speaker":"南委員","kind":"質問・要望","question":"こういうふうに考えることは正論なのでしょうか。正しいのか、正しくないのか、そのあたりを責任ある立場の理事者の皆さんに伺いたいと思います。","respondent":"篠田学務課長","answer":"あくまで区の政策として打ち出していく中でどういったものを順番に行うかというのは区として考えていくべきものだろうということでお話をしたもので…それから。","id":"exchange-079"},{"speaker":"南委員","kind":"質問・要望","question":"やはり私は教育に関しての予算を使うということは、区民からの反対はゼロとは言わないけれども、広く理解していただける問題だと思っています。自信を持ってやっていただきたいし、そういう角度で一つひとつの問題を精査していただきたいということをあえて強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"つる委員","kind":"質問・要望","question":"請願の文章の確認からですが、そうしたところも政策的なことを時の政府に求めて首相もそうした観点での答弁をやるというところがあるのですが、それについて説明を求めました。","respondent":"篠田学務課長","answer":"憲法における第２６条の無償化の範囲です。こちらに関しましては、申し訳ありません、基本的に個人にかかるもの以外を無償化していくといったものであるように記憶しております。","id":"exchange-081"},{"speaker":"つる委員","kind":"提案","question":"正確性というか、そのところがどうなのだろうと思ったので、ちょっと確認をさせていただきました。だから、全国の、それこそ区だけではなくて自治体でどのような給食の状況になっているのかということを提案してとの意見を述べました。","respondent":"篠田学務課長","answer":"財源に関しましては、先ほど申し上げたとおり、要は学校給食の食材費に関しては特定財源等がございませんので全て一般財源にならざるを得ないです。","id":"exchange-082"},{"speaker":"つる委員","kind":"質問・要望","question":"そういった部分と、これも既に我が党としては求めている部分もあるので、そうしたところもしっかりと注視をしていかなければならないのかなと。ですから、先ほどちょっとざっくりとした聞き方でお聞きしましたけれども、このあたりについては区としてはどういうふうに考えるか説明を求めました。","respondent":"篠田学務課長","answer":"やはり、こちら財源等につきましては、なかなか区だけの努力では賄い切れない部分もあろうかと思います。特に今、国のほうでは子育て支援に関してさまざまな形での支援が検討されている状況ですので、十分注視してまいりたいと考えておるところです。","id":"exchange-083"},{"speaker":"つる委員","kind":"確認","question":"そうしたところでも実施前の課題とかで挙げられている項目の中にもあるわけですから、さまざま精査しなければいけない観点もあるのかなと思います。先ほど申し上げたとおり、今ちょっと聞いた中で区のお考えを確認できたので、わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"},{"speaker":"渡部委員","kind":"質問","question":"決算特別委員会でいろいろ伺わせていただいて、自分の町、我が町に子どもがたくさん来てほしいという施策の一つです。国のほうで法律が決まってくればそれに乗るのでしょうから、そこに対して文句も当然ないわけですけれども、ただ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"渡部委員","kind":"意見","question":"ただ、品川区で言うのであれば、本当に厳しい方には無償化対応をしていますし、かかる給食費は、これ、高い安いではないです。しかるべき費用はご家庭にその分、お子さんが３人以上いるようなところはその分は補助しますよというスタンスで、この請願は不採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-086"},{"speaker":"つる委員","kind":"質問・要望","question":"国として手当していくべきという方向性を党としては示している中で、そうした財源のバランスの課題も一方ではあるのかなというところです。国の動きもある中で、そして推進させ、今この段階で区だけに対して求めるのはちょっとハードルが高いのかなという質疑中で確認させていただいたこと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"},{"speaker":"南委員","kind":"質問・要望","question":"私たちは、先ほどの質問の中で表明してきましたけれども、やはり子どもたちの教育にかかわる費用については、無償化であるべきだと。それから、先ほどつる委員のほうから憲法２６条の部分のところ、やはり区民の方々にそこまで求めるということは酷かなと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-088"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"が、請願項目においては、我が会派としては承認していく方向で取り組んでいただきたいという思いがあるので、採択を主張しました。そこを強く我々も求めているところでありますが、そういった観点を含めたら、今回のこの請願に関しては採択ということでお願いをしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"},{"speaker":"高橋（し）委員","kind":"意見","question":"ほかの政策とともにセットにしてどこでフォローしていくかというのを考えなければいけないのではないかと考えています。もっと広い範囲での義務教育というところの給食費については考えていくべきだということで、そちらをきちんと見ていってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-090"}]},{"id":"topic-10","title":"を行います。 専決処分の報告","agenda":"を行います。 専決処分の報告","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"１点だけ。貸し付けの返済に応じない理由というのは把握されているのか、どのように把握しているのか説明を求めました。","respondent":"廣田子ども家庭支援課長","answer":"この方は貸し付けを受けた後に、区外、東京ではないところに転居されておりましてしばらく連絡がとれなかったところです。再三にわたり督促を行っており、お母様とは電話番号がわかりお話はできましたが、連帯借受人とは連絡が一切取れない状況にあるといった状況です。","id":"exchange-091"}]},{"id":"topic-11","title":"その他","agenda":"その他","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"子どもの権利条約活かした教育への転換を」の質問の中で、質問の４、この出退勤システムの管理というのがどういうものなのか教えていただきたいのと。質問は１個だったのですが、答弁のところの中身がよくわからなかったので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/211588?Template=document&Id=4964#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":76158,"voices":304}}]);
